window.__D("text/likkut-maanot-kodesh/c013",{"p":[[9200200143,"143\nמענות קודש – ה ' תשמ \" א\nרעג\n[ תשמ \" א ( 2 ])\nמענה להת ' יונה אבצן על מכתבו ( להמזכיר רחמ \" א חדקוב ) בקשר\nלקונטרס \" החלצו \" בתרגום לאנגלית שמו \" ל , בו כתב : \" במענה\nלשאלותיו : תירגמנו רק י \" ז פרקים הראשונים מפני שתרגמנו רק הביאור\nעל אהבת ישראל וכו ', ועד פרק י \" ז נשלם כל הענין , וכמו \" כ כל הפסוקים\nמבוארים עד פרק י \" ז , השאר לא תרגמנו \" ( מהעתקה . המענה מתפרסם\nבזה לראשונה באדיבות ר ' שמואל שי ' אבצן וזכות הרבים תלוי ' בו :)\nצ \" ל דבר שלם , כמובן\nרדע\nתשמ \" א ][\nמענה להשליח ר ' טובי ' טעלדאן ( מהעתקה . המענה מתפרסם בזה\nלראשונה באדיבות מערכת הספר \" שליחות כהלכתה \" וזכות הרבים\nתלוי ' בהם :)\nכמפורסם כ \" ז שייך להתייעצות בעסקנים המומחים בכל כיו \" ב\n( העבודה המיוחדת שצ \" ל שם וכו ' )\nערה\nתשמ \" א ][\nמענה להחתן הת ' פסח צבי לזרוב ( מהעתקה . המענה מתפרסם בזה\nלראשונה באדיבות הנמען שי ' וזכות הרבים תלוי ' בו :)\nבטח החליטו שניהם לייסד ביתם על יסודי התורה והמצוה – ויהא\nהשידוך בשעה טובה ומוצלחת .\nאזכיר על הציון .\n( באם היא בת כהן ילמוד להיות בקי בתוכן מסכת אחת – אפשרי גם\nבאנגלית וממסכתות הקטנות כלה , וכיו \" ב .)"],[9200200144,"144\nמענות קודש – ה ' תשמ \" א\nרעו\nתשמ \" א ][\nמענה להחתן הת ' פסח צבי לזרוב ( מהעתקת המזכיר . המענה מתפרסם\nבזה לראשונה באדיבות הנמען שי ' וזכות הרבים תלוי ' בו :)\nצריך להתענין ולסדר ענין דפרנסה ( וקב \" ע בתורה בכל יום – בזמן הפנוי\nמהנ \" ל )\nכל זה בעיר ובענין – ע \" פ עצת ידידים ובהתייעצות שניהם ( הוא וב \" ג\nתי )'\nאזכיר על הציון\nרעז\nתשמ \" א ][\nמענה לא ' מרבני אנ \" ש ( מהעתקה . המענה מתפרסם בזה לראשונה\nבאדיבות א ' מאנ \" ש שי ' וזכות הרבים תלוי ' בו :)\nבקשר לפעולה מסויימת , כתב :\nכנראה מכתבו לקמן – בכל משך זמן זה לא עשה דבר ממשי בזה כלל !\n(1 )\nעל התיבות שבמכתבו : \" איך להסתדר \", כתב :\nישתדל באופן לחיוב וממשי ( לא רק בירור השוועריקייטן שישנם כבכל\nעניני עוה \" ז ) – ואם צורך – גם באופן ד \" יגעתי \"\nובכל ענין דרבנות שכותבם , לבד אלה דהשגת גבול ומחלוקת , ירבה\nרעים וכו '\nויבש \" ט . ( 2)\nאעה \" צ"],[9200200145,"145\nמענות קודש – ה ' תשמ \" א"],[9200200146,"146\nמענות קודש – ה ' תשמ \" א\nלזכות\nכ \" ק אדמו \" ר שליט \" א"],[9200210001,"ליקוט\nיום הבהיר י ” ד כסלו\nפראנקפורט , גרמני '\nיום הבהיר י “ א ניסן\nמענות קודש\n• •\n• ה ' תש ” נ תשמ \" ב •"],[9200210002,""],[9200210003,"ב \" ה .\nפתח דבר\nלקראת וא \" ו תשרי , יום היארצייט - הילולא של הרבנית הצדקנית מרת\nחנה נ \" ע זי \" ע , אמו של כ \" ק אדמו \" ר שליט \" א ,\nהננו מוציאים לאור בזה ליקוט \" מענות קודש – ה ' שת מ \" ב \", הכולל את\nמענות קודש כ \" ק אדמו \" ר שליט \" א שכתבם במשך שנת ה ' שת מ \" ב .\n*\n\" פון איין תורת נשיא דורנו גייט מען צו נאך א תורת נשיא דורנו \" ( שיחת\nש \" פ תזו \" מ תנש \" א – בלתי מוגה ). כמה \" חלקים \" ישנם לתורת נשיא דורנו\nכ \" ק אדמו \" ר שליט \" א .\nבין החלקים השונים בתורת כ \" ק אדמו \" ר שליט \" א , \" חלק \" מיוחד ישנו ,\nוהוא : \" מענות קודש \", הם אלפי המענות אשר כתב כ \" ק אדמו \" ר שליט \" א\nבמענה להשואלים :\nהחל מהשנים הראשונות לנשיאות כ \" ק אדמו \" ר שליט \" א , הנה לצד\nה \" אגרות \" ששלח להפונים אליו , נענו רבים מהמכתבים ע \" י כ \" ק אדמו \" ר\nשליט \" א בכתב יד קדשו על מכתב השואל , כאשר לאחר מכן נמסרים\nהדברים להנמען .\nבעוד ובשנים הראשונות הי ' זה באופן מצומצם ( בעיקר – לאלו הנמצאים\nבסמיכות מקום ), הנה ככל שעברו השנים הלך הדבר והתרחב יותר ויותר , עד\nשהי ' לאופן העיקרי בו עונה כ \" ק אדמו \" ר שליט \" א להכותבים אליו .\nעל אף היותו של \" חלק \" זה בתורת כ \" ק אדמו \" ר שליט \" א – חלק עיקרי ,\nנדמה , כי חלק זה אין מוסבת תשומת הלב אליו ככל הדרוש .\nטעם העיקרי לדבר הוא , ככל הנראה , כיון שמפוזרים מענות הקודש על\nפני כמה וכמה מקומות שונים , ועד עתה לא נמצא להם גואל שילקטם\nלפונדק אחד .\nצורך זה באנו למלאות בליקוטים אלו . קד מו לליקוט שלפנינ ו \" ליקוט\nמענות קודש – תשמ \" ג \" \", ליקוט מענות קודש – תש ד \" מ \", \" ליקוט מענות\nקודש – תשמ \" ה \",\" ליקוט מענות קודש – תשמ \" ו \", \" ליקוט מענות קודש –\nתשמ \" ז \" ,\" ליקוט מענות קודש – תשמ \" ח \" , \" ליקוט מענות קודש – תשמ \" ט ,\"\n\" ליקוט מענות קודש – תש \" נ ,\" \" ליקוט מענות קודש – ת נש \" א ו \"\", ליקוט\nמענות קודש – תש נ \" ב ,\""],[9200210004,"4\nמענות קודש – ה ' תשמ \" ב\nובתכניתנו להוציא ליקוטים נוספים מסוג זה , להרוות צמאון אנ \" ש\nוהתמימים .\n*\nתודתנו נתונה לכל אלו שהואילו למסור את מענות הקודש שבידם\nלפרסום בליקוט זה , וזכות הרבים תלוי ' בהם .\nבמיוחד תודתנו נתונה למערכת אפליקציית \" מפתח \" על עזרתם .\nוכאן המקום לבקש בבקשה כפולה ומכופלת מכל מי שיש בידו מענות\nקודש שטרם פורסמו , למוסרם לידי המערכת על מנת לפרסמם בליקוטים\nיבואו , ויהיו בזה ממזכי הרבים .\nכתובת הדוא \" ל של המערכת : likkutkatyak@gmail.com .\n*\nויהי רצון שיחוס וירחם השי \" ת עלינו , ונזכה להתראות עם כ \" ק אדמו \" ר\nשליט \" א תיכף ומיד ממש , ו במהרה תחזינה עינינו בהתפשטות מלכותו על\nכל באי עולם , תיכף ומיד ממש !\nמערכת \" ליקוט כתבי יד קודש \"\nערב וא \" ו תשרי , ה ' תש פ \" א\nשבעים שנה לנשיאות כ \" ק אדמו \" ר שליט \" א\nברוקלין , נ . י ."],[9200210005,"5\nמענות קודש – ה ' תשמ \" ב\nצילו מי כתי \" ק\n– פרסום ראשון –\nלקמן מענה נה"],[9200210006,"6\nמענות קודש – ה ' תשמ \" ב\nלקמן מענה נו\nלקמן מענה פח"],[9200210007,"7\nמענות קודש – ה ' תשמ \" ב\nלקמן מענה רכב"],[9200210008,"8\nמענות קודש – ה ' תשמ \" ב\nלקמן מענה רכג"],[9200210009,"9\nמענות קודש – ה ' תשמ \" ב\nלקמן מענה רלד"],[9200210010,"10\nמענות קודש – ה ' תשמ \" ב"],[9200210011,"11\nמענות קודש – ה ' תשמ \" ב\nמענות קוד ש – ה ' שת מ \" ב\nא\nמוצאי ראש השנה ][\nמענה להרב דוד ראסקין שכתב דו \" ח מאסיפה שנערכה ע \" י הנהלת\nישיבת תו \" ת המרכזית – בקשר לכתיבת ספר תורה הכללי שע \" י תו \" ת ,\nע \" פ הוראת כ \" ק אדמו \" ר שליט \" א בהתועדות יום ב ' דראש השנה\n( מצילום כתי \" ק – \" בית משיח \" גליון 225 תדפיס מספר \" ועבדי דוד \". –\nס \" ת הכלליים שע \" י תו \" ת המר כזית – ע ' 29 :)\n[1 במכתבו כתב : \" הוצע לעשות ההתחלה מחר .\"]\nכ \" ק אדמו \" ר שליט \" א סימן בעיגול תיבות אלו , וכתב :\nונכון במאד מאד\n[2 ] במכתבו כתב : \" ולמכור כל אות עבור 1 דולער .\"\nכ \" ק אדמו \" ר שליט \" א סימן בעיגול תיבות אלו , וכתב :\n!? הרי המדובר גם בבעלי פרנסה – ולמה יגבילו אותם ?! ובמילא אין\nשייך זה בכלל בס \" ת זו\n[3 ] במכתבו כתב : \" שאלה בנוגע לבנות הלומדות בבית רבקה האם הם\nמקנים זכות להוריהם ( שלא למדו בתו \" ת )? האם להקים ביניהן ועד\nשיפעל במוסדות לבנות כמו בית יעקב .\"?\nכ \" ק אדמו \" ר שליט \" א סימן בעיגול קטע זה , וכתב :\nהרי מייסדי תו \" ת לא עירבו בנות בזה .\nבית רבקה וכו ' ס \" ת בפ \" ע\n[4 על כללות המכתב , כתב :]\nכמובן – מצדי רק ההצעה בכללותה .\nפרטי ' שייך לההנהלה\nוגם הנ \" ל כתבתי לגודל פשטות הענינים\nאזכיר עה \" צ ( 4 )"],[9200210012,"12\nמענות קודש – ה ' תשמ \" ב\n[ בקשר למבצע ספרי תורה הכלליים – ראה גם לקמן מענות : ב , ג , ח , ט ,\nיא , יב , יז , כ , כא , לו , מד , נח , ס ג , ס ד , ס ט , פ א , פ ב , פ ג , פ ד צ , צ ב , צ ט ,, ק ה ,\nקי א , קי ב , קי ג , קי ד , ק טו , ק כא , קמ ט , ק נ , ק נא , ק עא , קע ג , קע ט , קפ ח ,\nקצ ה , קצ ט , ר ה , ר ז , ר לא , רמ ז , רמ ח .]\nב\nג ' תשרי , צום גדלי ]'[\nמענה להרב דוד ראסקין שכתב : \" הנהלת תו \" ת בקשו להודיע אשר היום\nג ' תשרי מתחילים לכתוב הס \" ת כאן בביהכנ \" ס הגדול \" ( תדפיס מספר\nועבדי דוד \"\" – ס \" ת הכלליים שע \" י תו \" ת המרכזית – ע ' 31 :)\nויהא בשטומו \" צ בכל\nאזכיר עה \" צ\nכדאי שיודיעו עד \" ז לסניפי תו \" ת שבכ \" מ\n[ כ \" ק אדמו \" ר שליט \" א צירף מאה דולר – עבור האות הראשונה בס \" ת\nשנרכשה עבורו , ומאה דולר – עבור האות השני ' שנרכשה עבור הרבנית\nהצדקנית .]\nג\nד ' תשרי ][\nמענה להרב דוד ראסקין על דו \" ח ממעמד התחלת כתיבת ס \" ת הכללי\nהראשון שע \" י ישיבת תו \" ת המרכזית , ומההודעה לסניפי תו \" ת שבכ \" מ\nע \" ד התחלת הרישום ( מצילום כתי \" ק – \" בית משיח \" גליון 225 . תדפיס\nמספר \" ועבדי דוד \" – ס \" ת הכלליים שע \" י תו \" ת המרכזית – ע ' 33 :)\n[1 על מה שכתב : \" וכבר התחילו לרשום בהס \" ת וכנראה שכהנ \" ל נת ']\nבטוב \" – כתב :\nכנראה ( כמה ) הבינו מההודעה שלהם שיכתבו ס \" ת בפ \" ע !\n[2 ] על כללות הדו \" ח , בצירוף טופס הרישום המצורף – כתב :\nכהנ \" ל נת ' ות \" ח ת \" ח . אזכיר עה \" צ ."],[9200210013,"13\nמענות קודש – ה ' תשמ \" ב\nד\nלאחר י \" ג תשרי ][\nמענה להרב אברהם יצחק ברוך גערליצקי על מכתבו בקשר להמדובר\nבהתועדות ו ' תשרי והמשכו בהתועדות י \" ג תשרי – שנתבאר פס \" ד\nהרמב \" ם ואדה \" ז שהמתוודה צריך לפרט החטא , דאף שבירושלמי נחלקו\nבזה רבי עקיבא ורבי יהודה בן בתירא , ור \" ע ( דהלכה כר \" ע מחבריו ) ס \" ל\nדאין צריך לפרט , הנה בבבלי הובאו דברי רב שבחטא שאינו מפורסם\nצריך להתוודות ברבים משא \" כ בחטא מפורסם , ומזה משמע דס \" ל\nכריב \" ב דצריך לפרט ( דהא לר \" ע גם בחטא שאינו מפורסם אי \" צ\nלהתוודות ברבים ), ופסקו הרמב \" ם ואדה \" ז כרב בבבלי . במכתבו כתב :\n\" בהערות וביאורים דעיוהכ \" פ סעי ' ה ' שאלו דמהשיחה נראה דאדה \" ז\nקאי בשיטת הרמב \" ם , ולכאו ' הרמב \" ם מחלק בעבירות שבין אדם\nלמקום לשבין אדם לחבירו , ואינו מחלק בין חטא מפורסם לחטא שאינו\nמפורסם , ואילו אדה \" ז ( בסי ' תר \" ז , סעי ' ד ) מחלק בין חטא מפורסם\nלשאינו מפורסם , ואינו מ חלק בין אדם למקום או בין אדם לחבירו ?\nובההתוועדות די \" ג תשרי אמר כ \" ק אדמו \" ר שליט \" א שהביאור בענין זה\nנמצא בספר תוס ' יוהכ \" פ , ושיצרפו דבריו להרשימה של השיחה .\nוהנה תוכן דבריו של התוס ' יוהכ \" פ הוא , דהרמב \" ם מפרש דפלוגתת\nהתנאים – דר \" ע וריב \" ב , אינה שייכת כלל להך פלוגתא דאמוראי ( אם\nמחלקין בין חטא מפורסם לשאינו מפורסם , או דבין אדם למקום וכו )'\nדר \" ע וריב \" ב פליגי כשמתודה בינו לבין קונו , אם צריך לפרט החטא או\nלא , ובזה ליכא נפק \" מ אם הוא חטא מפורסם או שאינו מפורסם , או אם\nהוא בין אדם למקום , או בין אדם לחבירו , דר \" ע סב \" ל דתמיד אי \" צ\nלפרט חטאו , וריב \" ב סב \" ל דתמיד צריך לפרט , והרמב \" ם פסק כריב \" ב\nמשום : א ) דיש ברייתא אחרת ( בגמ ' שם ) דפליגי על עבירות שה תודה\nעליהם ביוהכ \" פ שעבר אם יכול להתודות עליהם ביוהכ \" פ אחר אם לאו ,\nמשמע מזה דהברייתא סבר דצריך לפרט החטא . ב ) כיון דגם לר \" ע אין\nאיסור לפרט החטא אלא דאי \" צ , ואם הזכירם לית לן בה , לכן נקטינן\nכוותי ' דריב \" ב דצריך , ואמוראי פליגי בענין אחר , בנוגע לעושה תשובה ,\nדיש ש בח גדול לשב שיתודה ברבים , כדי שיתבייש , או שילמדו ממנו\nלעשות תשובה , ופליגי מתי יפרט חטאיו ברבים ומתי לא יפרט חטאיו\nברבים , ( אבל בנוגע לוידוי בינו לבין קונו אפ \" ל בין כר \" ע ובין כריב \" ב ,)\nוהרמב \" ם פסק בזה כלישנא בתרא שיש חילוק בין אדם למקום כו ,'\nדמשמע לי ' דהנך ב ' תירוצי אליבא דרב נאמרו , דמר סבר דהכי אמר רב ,\nומ \" ס דהכי אמר רב , והוא פסק כלישנא בתרא , ע \" כ תו \" ד ."],[9200210014,"14\nמענות קודש – ה ' תשמ \" ב\nולכאורה אכתי צריך להבין :\nא ) דסוכ \" ס למה פסק אדה \" ז כלשון ראשון , לא כהרמב \" ם שפסק כלישנא\nבתרא ?\nב ) לפי דבריו של התוס ' יוהכ \" פ נמצא דהטעם דפסק הרמב \" ם כריב \" ב\nדצריך לפרט החטא הוא משום הברייתא המובא אח \" כ אם יתודה בשנה\nאחרת , והרי ברייתא זו איתא גם בהירושלמי שם , ובמילא נמצא לכאו '\nדגם הירושלמי פסק דצריך לפרט החטא , וזה אינו כמשנ \" ת בהשיחה .\nג ) מהשיחה לכאו ' משמע דלר \" ע לא יפרט חטאיו בדוקא , כי זהו חסרון\nמצד העתיד , שיזכירו לו חטאיו , ולכאו ' ז . א . כמשנ \" ת בס ' הנ \" ל דלר \" ע\nרק אינו צריך אבל אם מפרט לית לן בה ?,\nד ) איך אפ \" ל דאדה \" ז והרמב \" ם קיימו בשיטה אחת , הרי לשון הרמב \" ם\nהוא \" וצריך לפרוט את החטא \", ומשמע דזהו מעיקר הדין בגדר הוידוי ,\nואילו אדה \" ז כתב : \" אם לא פרט את חטאיו אלא אמר סתם חטאתי יצא\nידי מצות וידוי , ומ \" מ לכתחילה נכון לפרט את החטא כו ' מפני שערב\nיוהכ \" פ הוא מתבייש יותר לפני הקב \" ה מחטאיו וכו '\", משמע לכאו '\nדמעיקר הדין אי \" צ לפרט החטא ( כמו שפסק המחבר בשו \" ע כר \" ע ) ומ \" מ\nנכון שיפרט בכדי שיתבייש וכו ' ( וזהו ע \" ד שכתב בשל \" ה ריש מס ' יומא\nדלר \" ע יתודה בלחש כדי שיתבייש .\"?)\nמענה כ \" ק אדמו \" ר שליט \" א ( מצילום כתי \" ק – ס ' היובל הערות\nוביאורים ע ' קלא :)\n[1 ] על מה שכתב : \" ובההתוועדות די \" ג תשרי אמר כ \" ק אדמו \" ר שליט \" א\nשהביאור בענין זה נמצא בספר תוס ' יוהכ \" פ , ושיצרפו דבריו להרשימה\nשל השיחה \", כתב :\nשהביאור ][ בכמה פרטים ד ענין זה נמצא בספר תוס ' יוהכ \" פ ][\n[2 על מה שכתב : \" ולכאורה אכתי צריך להבין \", כתב :]\nועוד כמה שצריך בי ' – ומהי הסתירה שכמה ענינים נתבארו !?\n[3 ] סימן בעיגול את מה שכתב : \" לפי דבריו של התוס ' יוהכ \" פ . . וזה אינו\nכמשנ \" ת בהשיחה \", וכתב :\nמעולם לא אמרתי שהשיחה מתאימה לכל מש \" כ התיוה \" כ בכל ספרו\nאו בכל פי ' בזה – מאין לקחו קס \" ד כזו !?\n[4] על מה שכתב : \" איך אפ \" ל דאדה \" ז והרמב \" ם קיימו בשיטה אחת ,\nהרי כו ' \" – סימן בעיגול את התיבות \" קיימו בשיטה אחת \", וכתב :"],[9200210015,"15\nמענות קודש – ה ' תשמ \" ב\nברוב המקומות שמובא ל ' זה הוא שמחולקים בכמה פרטים אלא\nשבנקודה אחת משותפים\nה\nי \" ד תשרי , ערב חג הסוכות ][\nמענה לר ' שניאור זלמן יפה שכתב ע \" ד רצונו לשלם עבור הד ' מינים\nשקיבל מאת כ \" ק אדמו \" ר שליט \" א בערב חג הסוכות , וצירף שטר של\nחמישים דולר ( ס ' \" Manchester Mr. ע '\" 276 :)\nכוונתו רצוי ' אבל באם אקבל כסף – אצטרך לבקש כסף מכל אלה שנתתי\nלהם ד ' מינים !! ולכן מוחזר בזה .\nו\nתשרי ][\nמענה לר ' ישראל לייבוב יו \" ר \" צעירי אגודת חב \" ד \" באה \" ק ( מצילום\nכתי \" ק – \" כפר חב \" ד \" גליון 675 והעתקה :).\nלכל לראש אנהאַלטן כל הפעילים בופרצת בכל התוקף –\nכי הולכת ומתפשטת אצלם הנטי ' \" לברוח \" מעסקנות חב \" ד , מפני כו .'\nולמנוע חורבן – מחוייבני לפרש : כי \" היושבים על הכסא \" רודפים פנים\nחדשות באם הם . . מצליחים\nז\nתשרי ][\nמענה לר ' ישראל לייבוב יו \" ר \" צעירי אגודת חב \" ד \" באה \" ק ( ס ' \" צעירי\nאגודת חב \" ד \" ע ' 97-8 והעתקה :),\nכ \" ק אדמו \" ר שליט \" א סימן את מה שכתב : \" אילו היו כל עסקני חב \" ד\nשיחיו מאוחדים \", וכתב :\nהי ' משיח בא מכבר ולכן היצה \" ר משתולל באופן ובפיתויים היפך\nהשכל לגמרי ולע \" ע הצליח ר \" ל במלחמת אחים וכו ' וה ' ירחם"],[9200210016,"16\nמענות קודש – ה ' תשמ \" ב\nח\nתשרי ][\nמענה להרב יצחק יהודה ירוסלבסקי מזכיר ועד רבני חב \" ד באה \" ק – על\nמכתבו בקשר לס \" ת הכללי של ילדי ישראל ( ס ' אלבום \" אות בספר\nתורה \" ע ' 110 :)\nהיש מי שממשיך במרץ ב \" גיוס \" ילדים / ות לס \" ת זו ?\nהנשלחו התעודות להנרשמים בהס \" ת ?\nט\nתשרי ][\nמענה להרב נחום טרבניק שכתב הצעה שרבני חב \" ד יתעסקו ברישום\nלס \" ת הכללי ( ס ' אלבום \" אות בספר תורה \" ע ' 111 :)\nכבר עושים בזה באה \" ק .\nהרי ענינם הס \" ת השני ' דילדי בנ \" י שי ' – ולהיותה שני ' נחוץ כל המרץ\nכו ' וכו .'\nי\nתשרי ][\nמענה לר ' שלום דובער לוין על מכתבו – בקשר למה שכתב כ \" ק אדמו \" ר\nשליט \" א על עלי - ההגהה דפתח - דבר לס ' מאמרי אדה \" ז תקס \" ב ח \" ב :\n\" שי \" ל ששינוי דהנוסחאות שישנם בהמאמרים שבבוך זה וכיו \" ב הוא\nמפני שנאמרו בזמנים שונים בנוסחא שונה \". במכתבו כתב :\n\" הרי מדובר כאן בשני ביכלאך . . שנכתבו באותה שנה – על סדר השנה ,\nוא \" כ בודאי נכתבו באותה שנה לאחר אמירת המאמר באותה פעם , ומ \" מ\nישנם השינויים ביניהם .\"\nמענה כ \" ק אדמו \" ר שליט \" א ( קובץ \" עבודת הקודש אצל הרבי \" ע ' קסב -\nג :)"],[9200210017,"17\nמענות קודש – ה ' תשמ \" ב\nלא אמרתי שכל השינוים זוהי סיבתם .\nכו \" כ מאמרים חזרו עליהם ( בחזרה , או בהמשך הש \" ק והיו \" ט עצמו –\nע \" ד תורת הבעש \" ט שהא ' חזרה עוה \" פ ) ועוד כיו \" ב .\nלהעיר שב \" סדר תורה \" הוא אמר ד ' פעמים אותו הענין .\nיא\nאור לי \" ז תשרי , א ' דחול המועד סוכות ][\nמענה להרב דוד ראסקין על דו \" ח מש ת י אסיפות שנערכו ע \" י הנהלת\nישיבת תו \" ת המרכזית בקשר לכתיבת ס \" ת הכללי שלהם ( תדפיס מספר\nועבדי דוד \"\" – ס \" ת הכלליים שע \" י תו \" ת המרכזית – ע ' 36 :)\n[1 ] במכתבו כתב : \" ההצעות שהיו . . לשלוח מכ ' להתומכים לתו \" ת\nולבאר גודל הזכות בקנית אות בס \" ת זו , וכל המרבה הרי זה משובח\nולפחות דולער אחד .\"\nכ \" ק אדמו \" ר שליט \" א מחק את התיבות \" ולפחות דולער אחד .\"\n[2 ] במכתבו כתב : \" אלו שלא תמכו עד עכשיו באם יתנו לתו \" ת או\nלהסניפים לפחות דולער אחד לבד קנית האות בס \" ת הרי זה בכלל\nתומך .\"\nכ \" ק אדמו \" ר שליט \" א מחק את התיבות \" לפחות דולער אחד .\"\n[3 ] במכתבו כתב : \" בהנוגע להסניפים : שיתנו לפחות דולער אחד בעד אות\nוהשאר יכולים לקבל עבור המוסד שלהם , כדי שיתענינו לרכוש יותר\nמשתתפים בהס \" ת .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\nבהחלוקה עם המוסדות מתאים יותר מחצה למחצה\nוראה לקמן מענה יב .]["],[9200210018,"18\nמענות קודש – ה ' תשמ \" ב\nיב\nאור לכ \" ף תשרי , ד ' דחול המועד סוכות ][\nמענה להרב דוד ראסקין על דו \" ח מאסיפת ישיבת תו \" ת המרכזית בקשר\nלכתיבת ס \" ת הכללי שלהם , בו כתב :\n\" בנוגע למענת כ \" ק אדמו \" ר שליט \" א \" בהחלוקה עם המוסדות מתאים\nיותר מחצה למחצה \" [ לעיל מענה יא ], אנו חושבים שהפי ' בזה שהחלוקה\nיהי ' בהרווח שישאר לאחר ההוצאות של הסניפים , ובעד הוצאות דכאן\n( שנכלל בזה גם בעד הסניפים ) וגם שאפשר שיהי ' סניפים שיעשו הוצאות\nגדולות ביותר , שהסניפים יתנו דולער בעד כל אות .\nלהערת כ \" ק אדמו \" ר שליט \" א ע \" ד נפטרים שאפשר לזכותם , דברנו עם\nהרב ז \" ש שי ' דבורקין ואמר שאפשר לזכות הנפטרים השייכים בהס \" ת\nשל תו \" ת .\"\nמענה כ \" ק אדמו \" ר שליט \" א ( מצילום כתי \" ק – תדפיס מספר \" ועבדי\nדוד \" – ס \" ת הכלליים שע \" י תו \" ת המרכזית – ע ' 37 :)\nסימן בעיגול את מה שכתב : \" שהפי ' בזה שהחלוקה יהי ' בהרווח שישאר\nלאחר ההוצאות של הסניפים , ובעד הוצאות דכאן ( שנכלל בזה גם בעד\nהסניפים ) וגם שאפשר שיהי ' סניפים שיעשו הוצאות גדולות ביותר ,\nשהסניפים יתנו דולער בעד כל אות \", וכתב :\n– אבל כ \" ז וכל כיו \" ב אינו עיקר כלל , כ \" א : כמה נרשמו כבר בפועל ?\nמדת הזריזות בזה בעתיד ?\nיג\nער \" ח מרחשון ][\nמענה להנערה דוואניע ראסקין שכתבה שהציעו לה להיות מורה בבית\nספר חב \" ד בטקסס , ומבקשת הסכמת וברכת כ \" ק אדמו \" ר שליט \" א\nתשורה כ \" ץ יו \" ד כסלו תשע \" ט :)(\nכ \" ק אדמו \" ר שליט \" א מחק תיבת \" ומבקשת \" וסימן בחץ ובקו את\nהתיבות \" הסכמת וברכת \", וכתב :\nאזכיר עה \" צ"],[9200210019,"19\nמענות קודש – ה ' תשמ \" ב\nיד\nבדר \" ח מרחשון ][\nמענה להנהלת \" צעירי אגודת חב \" ד \" המרכזית שכתבו ע \" ד שני נגידים\nהמקורבים לצאגו \" ח הנוסעים לאה \" ק עם קבוצה של ארבעים איש , ובעת\nביקורם מתעתדים לבקר בכפר חב \" ד ; ושאלו האם כדאי שיסע עמהם גם\nנציג מצאגו \" ח , ועי \" ז תצא טובה גדולה לחב \" ד ( מהעתקה . המענה\nמתפרסם בזה לראשונה באדיבות מערכת הספר \" ועבדי דוד \" וזכות\nהרבים תלוי ' בהם :)\nבהתייעצות ועל פי חוו \" ד עסקני אנ \" ש שי ' שבאה \" ק\nטו\nתחלת מרחשון ][\nמענה להחתן הת ' מנחם מענדל גארדאן וב \" ג רחל קליין שכתבו :\n\" התדברו מב ' הצדדים לסדר הווארט בינינו ליום ב ' ה ' מ \" ח הבעל \" ט כאן\nבקראון הייטס ומבקשים ברכת כ \" ק אדמו \" ר שליט \" א \" ( מצילום כתי \" ק\n– תשורה גארדאן ו ' אלול תשס \" ז :)\nויהא בשטומו \" צ\nטז\nו ' מרחשון ][\nמענה לר ' צבי מאיר שטיינמעץ שכתב – בהמשך ל \" שיר \" שכתב , בו קישר\nאת ראשי - תיבות וסופי - תיבות דהפסוק \" מאור עינים ישמח לב \" עם שמו\nהק ' של כ \" ק אדמו \" ר שליט \" א ושם הוריו נ \" ע :\n\" המשך ותקון בר \" ת וס \" ת מאו ר עיני ם י שמ ח לב , שבשולי שירי מליל\nהושענא רבה רשמתי : ס \" ת של שלש מלים האחרונות השם ושם האם ,\nור \" ת של שתי המלים האחרונות שם האב . אך באה ה \" ריש \" של מאו ר\nוטענה בפי - ה : למה אגרע . אז אורו עיני : ר בנו מ . ב . ח . ( כיוצא בו בפסוק\nאור זרוע לצדיק ולישרי לב שמחה , שאמרו בו ס \" ת עקיבה ( וכידועים\nחלופי הדברים בין הרבי האמצעי זי \" ע והגאון רע \" א זצ \" ל בזה )\nואשתמיט הריש של או ר כלומר רבי עקיבה .\")"],[9200210020,"20\nמענות קודש – ה ' תשמ \" ב\nמענה כ \" ק אדמו \" ר שליט \" א ( תשורה זלמנוב כ \" ד סיון תשע \" א :)\nעל מה שכתב : \" ואשתמיט הריש של או ר כלומר רבי עקיבה \" – סימן\nבעיגול תיבת \" ואשתמיט \", וכתב :\nובפרט לדעה הב ' הוא בתוס ' רבי \" אותיות אביר יעקב \" ( כ \" ז בשמות\nגיטין )\nאזכיר עה \" צ\nיז\nח ' מרחשון ][\nמענה לא ' ששאל – בקשר לדברי כ \" ק אדמו \" ר שליט \" א ע \" ד ספרי התורה\nהכלליים – האם פירושו של דבר הוא שמעתה יש לכלול גם את הילדים\nבס \" ת הכלליים , או להמשיך ברישום לס \" ת הכללי של ילדי ישראל .\nכמו \" כ העלה הצעה שאולי כדאי שכל הילדים יירשמו יחד עם המבוגרים\nלס \" ת הכללי בלבד , ו כך יהי ' קל יותר לנהל את הרישום המרוכז ( ס '\nאלבום \" אות בספר תורה \" ע ' 111 :)\nבאם לאחרי כל המדובר כשנה רצופה ע \" ד מעלת עניני הבל שאין בו\nחטא , שואלים הנ \" ל – מוכרח שימצאו מישהו שיש לו חוש בהסברה\nותעמולה , ויקרא ההנחות , עכ \" פ בשימת לב קצת דקצת , ויענה שאלתם .\nפשוט ומנהג ישראל הוא , שהזכרתיו בהתוועדויות , שנרשמים ביותר\nמספר תורה אחת , ושאין לומר שילדי ישראל לא יירשמו ח \" ו בס \" ת\nהכללית .\nיח\nועש \" ק לך , ט ' מרחשון ][\nמענה לר ' מיכאל אהרן זליגסון שכתב שכבר גמר את ה \" מפתח ענינים \"\nשערך לסה \" מ עטר \" ת , ותקוותו שחלק חשוב יהי ' מוכן לדפוס לכ \" ף\nמרחשון ( מהעתקה . המענה מתפרסם בזה לראשונה באדיבות הנמען שי '\nוזכות הרבים תלוי ' בו :)\nנת ' ות \" ח . אזכיר עה \" צ .\nוראה לקמן מענות : יט , כב , ל .]["],[9200210021,"21\nמענות קודש – ה ' תשמ \" ב\nיט\nועש \" ק לך , ט ' מרחשון ][\nמענה לר ' מיכאל אהרן זליגסון שהכניס את הכרטסיות של ה \" מפתח\nענינים \" שערך לסה \" מ עטר \" ת ( מצילום כתי \" ק – \" כפר חב \" ד \" גליון\n1459 :)\nמהיר\nכדאי להו \" ל בהקדם , כמובן\nכ\nי \" א מרחשון ][\nמענה להרב דוד ראסקין על דו \" ח מאסיפת הנהלת ישיבת תו \" ת\nהמרכזית – בקשר להגברת ההתעסקות בכתיבת ס \" ת הכללי שלהם\n( בהמשך להמדובר בהתועדות ש \" פ לך ), ובקשר לסדרי הלימוד ב - 770\nתדפיס מספר \" ועבדי דוד \"( – ס \" ת הכלליים שע \" י תו \" ת המרכזית – ע '\n39 :)\nויה \" ר שיהא כהנ \" ל בהצלחה\nאזכיר עה \" צ\nכא\nי \" ב מרחשון ][\nמענה לא ' שכתב – בקשר למבצע כתיבת ס \" ת הכלליים : \" מודים אנחנו\nברגשי כבוד לכ \" ק מרן שליט \" א בעבור פעולתו של כ \" ק . השי \" ת יצליח\nמחשבתו והוא יתברך יקבל את מעשיו ויזכה להרחיב גבול הקדושה\nבמדה גדושה ולהשפיע בלבות של אחינו ב \" י ותהי האמת נעדרת \" זאת\nאומרת \" שאין לנו אחרת כי אם להשען על אבינו שבשמים לשלוח לנו\n\" ישועה ממהרת \" לשלוח \" משיח צדקנו \" אמן \" ( מצילום כתי \" ק –\nצדי \" ק למלך \" חוברת ה ע '\" 151 :)\nכ \" ק אדמו \" ר שליט \" א סימן בעיגול את שם הנמען , וכתב :\nאזכיר עה \" צ\nבטח יענוהו מהועד ( וקבלה )"],[9200210022,"22\nמענות קודש – ה ' תשמ \" ב\nכב\nי \" ב מרחשון ][\nמענה לר ' מיכאל אהרן זליגסון שהכניס את הכרטסיות של \" מפתח\nענינים \" שערך לסה \" מ פר \" ת ( מצילום כתי \" ק – \" כפר חב \" ד \" גליון 1459 :)\n[1] במכתבו כתב : \"\" מפתח - ענינים \" למאמרי שנת פר \" ת . ( כולל גם :\nביטוים בלתי רגילים , הערות כלליות , כן רשמתי בההערות כלליות ,\nרשימה מא ' הת ' ע \" ד ש \" פ שמות וש \" פ וארא .\")\nמענה כ \" ק אדמו \" ר שליט \" א :\nלהו \" ל בהקדם\n[2 ] במכתבו כתב : \" במפתח ענינים לסה \" מ עטר \" ת וכן פר \" ת ערכתי רק\nמפתח ענינים וכו ' אבל לא מפתח פ סו קים וכו .\"'\nכ \" ק אדמו \" ר שליט \" א סימן בעיגול את התיבות \" מפתח ענינים \", וכתב :\nוזה העיקר\nכג\nי \" ג מרחשון ][\nמענה לכמה מתלמידי ישיבת תו \" ת המרכזית 770 שכתבו : \" נתעורר\nאצלינו לשלוח ולפרסם הספר חידושים וביאורים בש \" ס מכ \" ק אד \" ש\nבאופן המתאים בין כל הישיבות דמדינת ארצה \" ב , ולכל ר \" י ור \" מ\nורבנים דמדינה הנ \" ל . והשילוח יהי ' תחת השם \" ספרי ' תות \" ל 770 \"\n( שאנו הגבאים דהנ \" ל ). הספרים שיושלחו להישיבות יהי ' בחינם בכדי\nשהספר תהי ' באו צר הספרים שלהם , והספרים שיושלחו להר \" י ורבנים\nתהי ' עם מכתב בקשה לשלם עבור הספר כפי יכולתם . הננו בזה לבקש\nחו \" ד כ \" ק אדמו \" ר שליט \" א , ואם בחיוב ברכת כ \" ק אדמו \" ר שליט \" א\nעבור הנ \" ל \" ( מצילום כתי \" ק – תשורה טלזנר כ \" ט שבט תשנ \" ז :)\nלא זו הדרך כלל – משא \" כ המחברים שי ' הזקוקים לפרנסה גשמית ,\nוכשאי אפשר בכבוד עושים כנ \" ל וק \" ל .\nהדרך הסלולה – שהתלמידים שי ' זאלן זיך קאכן אין לערנן ( והם –\nבכלל ) ולאח \" ז יפגשו עם הנ \" ל וידברו אין לערנן כדבעי ויזכירו הס '\nופשוט\nח"],[9200210023,"23\nמענות קודש – ה ' תשמ \" ב\nכד\nמרחשון ][\nמענה כללי - פרטי דימים אלו [ בין השאר : ( 1 ) להשליח ר ' יוסף דוד\nווייטמאן על ההודעה ע \" ד פתיחת קעמפ \" פרדס חנה \" לבנות בבראזיל ,\nבנוסף על קעמפ \" גן ישראל \" לבנים ( קובץ \" ח \" י שנים גן ישראל – פרדס\nחנה \" ע ' 33 ;) ( 2 ) לר ' יונה אבצן שהכניס כמה דברי דפוס של ועד שיחות\nבאנגלית , וכמה ענינים נוספים ( מהעתקה , באדיבות ר ' שמואל שי '\nאבצן :])\nנת ' ות \" ח .\nודבר בעתו –\nבסמיכות ליום הולדת אדנ \" ע , שמזלו גובר .\nאזכיר עה \" צ .\nכה\nמרחשון ][\nמענה לר ' ישראל לייבוב יו \" ר \" צעירי אגודת חב \" ד \" באה \" ק ( ס ' \" צעירי\nאגודת חב \" ד \" ע ' 257 , 375-6 \" התקשרות \" גליון שלה :).\nכיון שבשנה זו צריך להיות מבצע חנוכה במימד הכי גדול – לכן ישתתפו\nמהמזכירות בשני שליש מההוצאות ( אם זקוקים ) לסיוע .\nאזעה \" צ .\nוראה לקמן מענות כו , לג .][\nכו\nמרחשון ][\nמענה לר ' ישראל לייבוב על מכתבו בקשר לפעילות ב \" מבצע חנוכה \"\nבצפון אה \" ק (\" התקשרות \" גליון שלה :)\nהרי עד חנוכה יהיו כמה חדשות ושינויים וכו ' שקו \" ט ודיבורים פעם\nאחר פעם וכו ' הכבר התחילו עכ \" פ בהכנות בפועל ?"],[9200210024,"24\nמענות קודש – ה ' תשמ \" ב\nכז\nמרחשון ][\nמענה לר ' שלום דובער לוין ( קובץ \" עבודת הקודש אצל הרבי \" ע ' כח :)\nהקובץ יג \" ת ( מד ) נת ' ות \" ח ת \" ח .\nכח\nמרחשון ][\nמענה לר ' אלתר לוי רייטער ( המענה מתפרסם בזה לראשונה באדיבות\nהת ' מנחם מענדל שי ' הכהן העכט וזכות הרבים תלוי ' בו :)\n[1 ] במכתבו כתב ע \" ד פציינטית שלו הסובלת מרעשים באזנה , שרוצה –\nבאם כ \" ק אדמו \" ר שליט \" א מסכים – להפנות אותה לרופא מסויים\nשפיתח טיפול חדש בנושא , ופירט את מעלות הטיפול .\nמענה כ \" ק אדמו \" ר שליט \" א :\nעפכ \" ז כדאי ( 1 )\n[2 במכתבו ציין שיטות פעולה שונות בקשר לבעי ' האמורה .]\nכ \" ק אדמו \" ר שליט \" א מחק את התיבות \" electro-therapy \", ותיבת\n\" surgery \" .\nכט\nח \" י מרחשון ][\nמענה לר ' טובי ' פלס שכתב שעומד לנסוע ביום זה מחצרות קדשנו חזרה\nלאה \" ק ( תשורה פלס ט ' תמוז תש \" פ :)\nכיון שכבר נמצא כאן , ובאם אין קשור בקישויים כו ' וזוגתו תחי ' תסכים\n– קדימה שיסע מכאן לאחר שהותו כאן ביום הולדת אדנ \" ע היינו\nבמוצאי או אמצע יום כ ' מ \" ח ."],[9200210025,"25\nמענות קודש – ה ' תשמ \" ב\nל\nכ \" ב מרחשון ][\nמענה לר ' מיכאל אהרן זליגסון שהכניס את עלי - ההגהה דפתח - דבר\nל \" מפתח ענינים \" שערך על מאמרי אדמו \" ר מהרש \" ב ( מצילום כתי \" ק –\nתשורה זליגסון כ \" א אייר תשנ \" ה :)\nמהיר\nהבפו \" מ דהערות וכו ' להיום יום ?\n[ וראה לקמן מענות : מג , נה , נו , ע ב .]\nלא\n[ לאחר ש \" פ חיי שרה , כ \" ד מרחשון ( 1 ])\nמענה לא ' על שאלתו בהמדובר בהתועדות ש \" פ חיי שרה :\n\" נתבאר אשר ע \" י \" ישלח מלאכו לפניך \" נפעל הסכמתה ורצונה של רבקה\nללכת עם אליעזר , ללא השתדלות מיוחדת מצדו של אליעזר , כי אליעזר\nלא דיבר מאומה ע \" ד השידוך עם רבקה , והראי ' ממה שנאמר \" נקרא\nלנערה ונשאלה את פי '\", ז . א . שלא דברו בפני ' ( ואפילו שכבר נתפרסם\nשעלי ' מדובר ,)\nולכאו ' פסוק זה \" נקרא לנערה גו \"' – נאמר למחרת ביאתו ועיקר דיבורו\nשל אליעזר , לאחרי \" ויאכלו וישתו . . . וילינו ויקומו בבקר \", אבל ביום\nביאתו ובנוגע לדיבורו הרי נאמר ( חיי שרה כד , נא ) הנה רבקה לפניך קח\nולך , ובפסוק נג : ויוצא העבד כלי כסף וגו ' ויתן לרבקה , ורק אח \" ז ויאכלו\nוגו ,'\nדמזה משמע שרבקה כן נוכחה בעת דיבורו של אליעזר .\"\nמענה כ \" ק אדמו \" ר שליט \" א ( קובץ הערות וביאורים אהלי תורה ש \" פ\nתולדות תשמ \" ב ( גליון קי :))\nאמרתי וכו \" כ פעמים – שכשיש קושיא , ובפרט קלאץ קושיא , לראות :\n1 בכתוב ,) 2 בפרש \" י ,) 3 ) לשאול בן חמש למקרא – אולי מעיקרא ליכא .\nובנדו \" ד : 1 ) מפורש : ויוצא גו ' ובגדים ( ולא שהי ' מונח על השלחן הנערך\nלאכילתו ) גו ' ולאמה ולא לבתואל , כי לאחר ויען לבן ובתואל בא מלאך\nוהמיתו ( ולדעתו – הומת בתואל וכל השאר ממשיכים במו \" מ כו ' וכ \" ז"],[9200210026,"26\nמענות קודש – ה ' תשמ \" ב\nעל השלחן ובהמשך אחד .)! 2 ) פרש \" י ( כד , מז ) שינה הסדר – איך\nאפשרי בנוכחיות רבקה ? 3 ) כשמדברים בענין הכי חשוב יקראו לנערה\nבת ג ' ומבית אמה שתשתתף ! ( ובפרט שלא ידעו שאודותה מדובר .)\nלב\n[ לאחר ש \" פ חיי שרה , כ \" ד מרחשון ( 2 ])\nמענה להמזכיר ריל \" ג שכתב – בהמשך להמענה שנתקבל בקשר להמדובר\nבהתועדות ש \" פ חיי שרה :\nלכאורה : א ) בלקו \" ש כרך יו \" ד ע '\" 65 הערה 9 מבואר שזה שאליעזר לא\nנתן מתנה גם לבתואל \" כי מובן שמגדנות – פירות . . . ה \" ז מתנה קטנה\nשאינה חשובה ולכן גם אינו ראוי ליתן לבעה \" ב עצמו , ולכן לא נתן אלא\nלאחי ' ולאמה \" – שעפ \" י ביאור זה הרי בתואל כן הי ' חי ונוכח בעת\nחלוקת המתנות והומת אח \" כ .\nב ) עפ \" י תשובה הנ \" ל – נשארת השאלה שבלקו \" ש שם \" והא דלא הוקשה\nלו לרש \" י \" ובתואל היכן הי '\" במ \" ש לפנ \" ז ( שם , נג ) \" ומגדנות נתן לאחי '\nואמה \"\" – כיון שמת לפני החלוקה .\nג ) עפ \" י תשובה הנ \" ל , צ \" ע סדר הפסוקים – למה נאמר מקודם ויוצא\nהעבד כלי כסף גו ' לפני ויאכלו וישתו .\"\nמענה כ \" ק אדמו \" ר שליט \" א ( קובץ הערות וביאורים אהלי תורה ש \" פ\nויצא תשמ \" ב ( גליון קיא :))\nעל מה שהביא מלקו \" ש ח \" י , כתב :\nהערה לאחר זמן : המבואר בלקו \" ש הנ \" ל אינו גלאטיק – שמי מעכבו\nלתת מתנה חשובה ( והי ' לו עשרה גמלים וכו .)'\n[ על שאלתו שע \" פ המענה נשארת השאלה שבלקו \" ש שם – ענה ( בע \" פ :)\nיש לומר שמהפסוק \" ויאמר אחי ' ואמה \" הכרח יותר גדול להפירוש\nברש \" י \" הי ' רוצה לעכב וכו '\" מאשר הנאמר לפני זה \" ומגדנות נתן לאחי '\nולאמה .]\""],[9200210027,"27\nמענות קודש – ה ' תשמ \" ב\nלג\nכ \" ה מרחשון ][\nמענה לר ' ישראל לייבוב יו \" ר \" צעירי אגודת חב \" ד \" באה \" ק שכתב\nשעלתה הצעה לתת לחיילי צה \" ל כ \" דמי חנוכה \" מטבע של חצי שקל ( ס '\nצעירי אגודת חב \" ד \" ע '\" 261 . והעתקה , באדיבות מערכת הספר \" שליחות\nכהלכתה :)\"\nכ \" ק אדמו \" ר שליט \" א סימן את התיבות \" חצי שקל \", וכתב :\nמטבע חדש נכון לתת זה .\nלולי הבטלנות וכו ' אפשרות לקבל ( חלק חשוב מזה או הכל ) במתנה\nהשתתפות מהאוצר ,\nמכבר היו מציעים מטבע בציור שיוצע ע \" י חב \" ד ככתבי מאז ( לוחות\nמרובעות וכו ' .)\nוראה ליקוט מענות קודש תשמ \" ג מענה פו .][\nלד\nמוצש \" ק תולדות , ב ' כסלו ][\nמענה לר ' צבי מאיר שטיינמעץ על דו \" ח מאסיפת חברי הנהלת רשת\nחדרי תורה אור \" באה \" ק , בה דנו בההצעה אשר רשת \" חדרי תורה אור \"\"\nתאמץ את רשת \" רמת \" ותתמוך בממון בפעולותי ', ובשני אופנים : ( 1 )\nשרשת \" רמת \" תמשיך להתקיים כחטיבה עצמאית , בתמיכת רשת \" חדרי\nתורה אור ;\" ( 2) למזג א ת רשת \" חדרי תורה אור \" ורשת \" רמת \" לחטיבה\nאחת ( תשורה זלמנוב כ \" ד סיון תשע \" א :)\nפי ' למעשה ולטווח לא ארוך –\nבטול חת \" א\nבהתחלה בתור ענין עצמאי וחשיבות בפ \" ע\nולאח \" כ התדרדרות וכו '\nולפלא הכי גדול הקס \" ד"],[9200210028,"28\nמענות קודש – ה ' תשמ \" ב\nלה\nג ' כסלו ][\nמענה למרת בילא רישא גאלדשטיין שכתבה : \" הנני כעת עובדת בתור\nמורה בבית רבקה , שלש פעמים בשבוע , שיעור חסידות לתלמידות כיתה\nי \" ב ולסמינר ב '. היות ש . . נוסעת , המנהלת שואלת ממני לקחת עוד כמה\nשעות חסידות בכיתות י ' יא ' יב . והנני בזה לשאול עצת כ \" ק אדמו \" ר\nשליט \" א האם ל הסכים להצעה זו . גם , הנני לבקש ברכת כ \" ק אדמו \" ר\nשליט \" א להצלחה בהשיעורים שאני כבר מלמדת הן בההשפעה והן\nבהלימוד ומשמעת \" ( מהעתקה . המענה מתפרסם בזה לראשונה באדיבות\nמשפחת הנמענת וזכות הרבים תלוי ' בהם :)\nכ \" ק אדמו \" ר שליט \" א מחק תיבת \" האם \" וסימן בחץ ובעיגול את\nהתיבות \" להסכים להצעה זו \", וכתב :\nאזכיר עה \" צ\nלו\nז ' כסלו ][\nמענה להרב דוד ראסקין על דו \" ח מאסיפת ישיבת תו \" ת המרכזית בקשר\nלכתיבת ס \" ת הכללי הראשון שלהם ( תדפיס מספר \" ועבדי דוד \" – ס \" ת\nהכלליים שע \" י תו \" ת המרכזית – ע ' 45 :)\nצירקינד .\"\nכ \" ק אדמו \" ר שליט \" א סימן בעיגול תיבות אלו , וכתב :\nלהחזיר\n[2 ] במכתבו כתב : \" וכן לכתוב על המעיל לזכות כ \" ק אדמו \" ר שליט \" א\nוהרבנית שתליט \" א ע \" י העובדים בישיבת תו \" ת המרכזית וסניפי .\"'\nכ \" ק אדמו \" ר שליט \" א מחק תיבת \" וכן \", וכתב :\nלא לכתוב על המעיל לזכות כו ]'[\n[3 על כללות המכתב , כתב :]\nכל השאר – כפשוט שייך להנהלת תו \" ת"],[9200210029,"29\nמענות קודש – ה ' תשמ \" ב\nלז\nלאחר ש \" פ ויצא , ט ' כסלו ][\nמענה להרב אברהם יצחק ברוך גערליצקי על שאלותיו בהמדובר\nבהתועדות ש \" פ חיי שרה והמשכו בהתועדות ש \" פ ויצא – שנתבאר שהדין\nשהמגי ' אות אחת בס \" ת ה \" ז כאילו כתבו , הוא גם כאשר לא מצא שום\nטעות בהס \" ת , ומקור הדברים : ( 1 ל ' השו \" ע שתפס ל ' הגהה ולא ל ')\nתיקון , והיינו בדיקת הס \" ת , וע \" ד הדין בבדיקת חמץ ; ( 2 ) ע \" פ הדין\nד \" אסור להשהות ספר שאינו מוגה \", והיינו אפילו בספק טעות ( מצילום\nכתי \" ק – ס ' היובל הערות וביאורים ע ' קלז :)\n[1 על כללות המכתב , כתב :]\nהרי צ \" ל השילוח לקובצים\n[2 במכתבו כתב : \" במה שאמר כ \" ק אדמו \" ר שליט \" א בההתוועדות ,]\nדכיון דאמר הלשון \" הגיה \" ולא תיקן , מוכח דאי \" צ תיקון , לכאו ' צריך\nלהבין הרי גם בשבת קד , ב , אמר הלשון \" הגיה אות אחת חייב \" וכן הוא\nברמב \" ם הל ' שבת פי \" א הל ' י \" ג , ושם הרי הפי ' הוא ש תיקן ע \" י כתיבה ,\n( דאל \" כ בודאי פטור , וכמו שמפרש שם בגמ ') וא \" כ הרי גם הכא אפשר\nלפרש כן דהגיה היינו שתיקן ? ( וכן הוא בשו \" ע אדה \" ז סי ' ש \" מ סעי ' ה .\")'\nמענה כ \" ק אדמו \" ר שליט \" א :\nב \" מלאכה \" ( שם ) אין מקום לטעות\n[3 ] במכתבו כתב : \" במה שאמר כ \" ק אדמו \" ר שליט \" א דאסור להשהות\nספר שאינו מוגה ( כתובות יט , ב ) זהו גם בספק טעות ( ואינו מוגה היינו\nשלא נבדק ) צריך להבין הרי בשטמ \" ק שם כתוב דהיינו \" כשיש בו טעויות\nבחסר ויתיר והשמטת תיבות וכיוצא \", משמע דהיינו דיש שם ודאי טעות ,\nולא נתתק ן .\"?\nמענה כ \" ק אדמו \" ר שליט \" א :\nמאין ידוע זה ? והזכרתי שתלוי בהשקוט הזהו מד \" ס וכו ' ודין ספקו וכו '\n[4 ] במכתבו כתב : \" במה שהובא דוגמא מבדיקת חמץ צריך להבין הרי\nשם המצוה היא ה בדיקה , וא \" כ אין נפק \" מ אם לא מצא סו \" ס בדק , אבל\nכאן המצוה היא כתבו לכם וגו ' כתיבת ספר תורה , וא \" כ הרי אפ \" ל דאם\nלא כתב כלל , לא קיים המצוה , ( ע \" ד בשבת דאינו חייב משום כתיבה , אם\nלא כתב כלל ורק בדק ס \" ת .\")"],[9200210030,"30\nמענות קודש – ה ' תשמ \" ב\nמענה כ \" ק אדמו \" ר שליט \" א :\nולמדה גו ' שלכן האידנא כו ' היינו שזהו עיקר המצוה\nלח\n[ לאחר ש \" פ ויצא , ט ' כסלו ( 1 ])\nמענה לר ' שלום דובער לוין שכ תב בקשר להמדובר במאמר ד \" ה אתה\nאחד דש \" פ ויצא – שהובא ממש \" כ ב \" התמים \" ( חוברת ב ע ' פד פט , ד )( )\nאודות מאמר זה ( שנדפס בקונטרס בפ \" ע בשנת תשכ \" ה ) שנאמר ע \" י\nאדמו \" ר האמצעי בש \" ק האחרון לשבתו במאסר קודם תפלת המנחה :\n\" יש להעיר מאגרת כ \" ק אדמו \" ר מוהרש \" ב נ \" ע ( גוכתי \" ק ) מאור לי \" ח\nטבת אעת \" ר [ אגרות - קודש אדמו \" ר מהרש \" ב ח \" ב ע ' תקנז ]: \" ובצאתו\nלשלו ' אמר הדרוש אתה אחד שנ תחדש לו במנחה דש \" ק ההוא , כן\nמספרים \"\" ( קובץ \" עבודת הקודש אצל הרבי \" ע ' קנד :)\nלחפש הנמצא המאמר בעוד כת \" י ( לבד הג ' שצוינו בהקדמה .)\nלט\n[ לאחר ש \" פ ויצא , ט ' כסלו ( 2 ])\nמענה לר ' שלום דובער לוין שהכניס – בהמשך להמענה שקיבל – את\nרשימת הכתבי - יד שבהם מועתק מאמר ד \" ה אתה אחד , וכתב : \" בכמה\nמהם מועתק מאמר זה בין מאמרי הצ \" צ , ובא ' מהם ( 696 ) בכותרת \" ב \" ה\nיום הששי פ ' וישב שנת תד \" ר לפ \" ק \" . . מאמר זה בנוסח אחר , בבוך מס .\n535 לה , א בכותרת : דהאמצעי , הנחת החסיד ר ' יעקב קאדאנער .\"\"\nעפכהנ \" ל אולי יש מקום לשער , שהוא מאמר אדה \" ז , שחזרו עליו גם\nאדהא \" מ והצ \" צ \" ( קובץ \" עבודת הקודש אצל הרבי \" ע ' קנד :)\n[1 על מה שכתב : \" מאמר זה בנוסח אחר , בבוך מס .] 535 לה , א בכותרת :\nדהאמצעי , הנחת החסיד ר ' יעקב קאדאנער \", כתב :\"\nלהראני .\n[2 על מה שכתב : \" עפכהנ \" ל אולי יש מקום לשער , שהוא מאמר אדה \" ז ,]\nשחזרו עליו גם אדהא \" מ והצ \" צ \", כתב :\n?!"],[9200210031,"31\nמענות קודש – ה ' תשמ \" ב\nמ\n[ לאחר ש \" פ ויצא , ט ' כסלו ( 3 ])\nמענה לר ' שלום דובער לוין על מכתבו בצירוף כתבי - היד דמאמר ד \" ה\nאתה אחד – בהמשך להמענות שקיבל ( קובץ \" עבודת הקודש אצל הרבי \"\nע ' קנה :)\n[1 ] במכתבו כתב : \" מצינו כמ \" פ בין מאמרי הצ \" צ , שחוזר על מאמר\nאדה \" ז ( בתוס ' הגהות ), אך לא מצינו שיחזור על מאמרי אדהא \" מ . ומזה\nבאה הסברא שהמאמר הוא של אדה \" ז ( הנחת אדהא \" מ ), וחזרו עליו\nאדהא \" מ ( בתקפ \" ז ) והצ \" צ ( בתר \" ד .\")\nמענה כ \" ק אדמו \" ר שליט \" א :\nכו \" כ מאמרים דביאוה \" ז שנמצאים עד \" ז בביאוה \" ז דהצ \" צ , וכן דתו \" ח .\n[2 ] במכתבו כתב : \" לפי מ \" ש באגרת הנ \" ל \" אשר יו \" ד כסלו דההוא שתא\nהי ' ביום ש \" ק \", א \" כ יצא לחירות ביום הש \" ק , ונאמר המאמר בסמיכות\nלמנחה \" בצאתו לשלום \". וכיון שע \" פ הקביעות של אותה שנה הי ' ט '\nכסלו ביום הש \" ק , עפ \" ז מסופר ב \" התמים \" שהמאמר נאמר בבית\nהאסורים .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\nיברר ( בס ' עתים לבינה ?) מתי חל יוד כסלו בתקפ \" ז ( וספק קצת אולי\nהגאולה ) בתקפ \" ו .\nמא\nלאחר ש \" פ ויצא , ט ' כסלו ][\nמענה לא ' מילדי צבאות - השם על שאלתו בהמדובר בהתועדות ש \" פ ויצא\n– שנתבאר פרש \" י ( ויצא לא , יז ) בהחילוק בין יעקב לעשו , שיעקב הקדים\nבניו לנשיו ועשו הקדים נשיו לבניו . ושאל הנ \" ל דלכאורה גם במשה רבינו\nמצינו שהקדים נשים לבנים ( שמות ד , כ ): \" ויקח משה את אשתו ואת\nבניו גו '\" ( קובץ הערות התמימים ואנ \" ש מאריסטאון ש \" פ ויגש תשמ \" ב\nגליון רמה ). לקו \" ש חכ \" א ע '( 352 :)\nבנו הי ' קודם או בן ח ' ימים – כדפרש \" י ( קודם למילתו ) ואיך הי ' יכול\nלשימו על החמור קודם שהייתה אשתו על החמור !?"],[9200210032,"32\nמענות קודש – ה ' תשמ \" ב\nמב\nי \" ג כסלו ][\nמענה לעסקני חב \" ד בקריות אה \" ק שכתבו ע \" ד החלטתם למנות את הרב\nדוד מאיר דרוקמן לרב קהילת חב \" ד ( קובץ \" חב \" ד קריות \" ע ' 43 :)\nשייך לועד רבני אנ \" ש שי ' שבאה \" ק ת \" ו כמובן , ויפנו אליהם .\nמג\nועש \" ק וישלח , ט \" ו כסלו ][\nמענה לר ' מיכאל אהרן זליגסון שכתב – בהמשך להוספת כ \" ק אדמו \" ר\nשליט \" א ברשימת תולדותיו שב \" שלשלת היחס \" שבריש ס ' היום יום :\n\" מעורר אשר . . בכמה ספרים דשנת תשמ \" ב היא שנת הקץ . . ראה חת \" ס\nעה \" ת ...\" ( מצילום כתי \" ק – קובץ \" שלשלת היחס \" ע ' צז :)\n[1 ] במכתבו כתב : \" כמו שהובא בחת \" ס לפ ' תולדות וכן דרשות שלו , הרי\nשם כותב רק תמצית הדברים ושהקץ הוא בשנת תק \" ע .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\n– אין מזה סתירה כלל , כי כמפורסם כאו \" א מכותבי קצין – לכל לראש\nהי ' קץ הקרוב ממש לזמנו .\n[2 ] על גליון מכתבו ציין המזכיר ריל \" ג : \" בקשר להנסמן ששנת תשמ \" ב\n– קץ מחת \" ס עה \" ת .\"\nכ \" ק אדמו \" ר שליט \" א סימן קטע זה , וכתב :\nלהשמיט\nמד\nועש \" ק וישלח , ט \" ו כסלו ][\nמענה להרב דוד ראסקין על דו \" ח מאסיפת הנהלת ישיבת תו \" ת\nהמרכזית בקשר לכתיבת ס \" ת הכללי הראשון שלהם ( תדפיס מספר\nועבדי דוד \"\" – ס \" ת הכלליים שע \" י תו \" ת המרכזית – ע ' 46 :)"],[9200210033,"33\nמענות קודש – ה ' תשמ \" ב\n[1 במכתבו כתב : \" הצעתינו לעשות הסיום בי ' שבט הבעל \" ט שאז יהי ']\nברוב עם וכו '. הסופר אמר שישתדל לסיום בכ \" ד טבת הבעל \" ט ,\nשאלתינו : לעשות הסיום בי ' שבט או בכ \" ד טבת ( וכבר נמכרו כל\nהאותיות שבס \" ת זו .\")\nמענה כ \" ק אדמו \" ר שליט \" א :\nע \" פ אגה \" ק סכ \" א כ \" ד טבת ][\n[2 ] במכתבו כתב : \" וכן מאחר שישנם עוד הרבה עשיריות אלפים שרוצים\nלהשתתף בהס \" ת דתו \" ת ובודאי יהיו עוד משתתפים , הצעתינו להתחיל\nלכתוב עוד ס \" ת מטעם תו \" ת , והסופר ר ' אליעזר שי ' צירקינד מקבל עליו\nלכתוב עוד ס \" ת ולהשתדל לסיים לי \" א ניסן הבעל \" ט .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\n– יחסר בדיוק הכתיבה , ול \" ג בעומר השתא הוכפל בו כי טוב\nמה\nמוצש \" ק וישלח , ט \" ז כסלו ][\nצעטל \" בכתי \" ק שכתב כ \" ק אדמו \" ר שליט \" א לה \" ועד להפצת שיחות \"\"\n– בהמשך להמדובר בהתועדות ש \" פ וישלח ע \" ד ס ' \" לקוטי אמרים –\nמהדורא קמא \" ( מצילום כתי \" ק – \" בית משיח \" גליון 72 :)\nב \" ה\nמוצש \" ק\nבהמשך להמדובר בההתועדות דרעד \" ר בביהכנ \" ס ובביהמ \" ד\nכדאי שיתחילו במהד \" ת דלקו \" א מהד \" ק בערב יט \" כ ע \" מ לגומרה לכ \" ד\nטבת\n___\nלהגי ' עוה \" פ וכו ' ואפשר שימצאו עוד כת \" י )(\nבתור התחלה וכו ' 6 ציונים"],[9200210034,"34\nמענות קודש – ה ' תשמ \" ב\n[ כ \" ק אדמו \" ר שליט \" א צירף את הכרך דס ' \" לקוטי אמרים – מהדורא\nקמא \" שלו , ועליו 6 ציוני תיקונים בכתי \" ק ( ראה צילום כתי \" ק – \" בית\nמשיח \" שם .)\nוראה גם לקמן מענות : נב , נז , ס ז , צ ד .]\nמו\nכסלו ][\nמענה כללי - פרטי דימים אלו [ בין השאר : ( 1 ) למערכת הערות התמימים\nואנ \" ש מאריסטאון שהכניסו את הקובץ דש \" פ וישלח ( קובץ הערות\nהתמימים ואנ \" ש מאריסטאון ש \" פ וישב תשמ \" ב ( גליון רמג ). וראה לקמן\nמענה מז ;) ( 2 ) להנהלת בית חב \" ד אנטווערפן בלגיא בקשר לתכנית הבנין\n( תשורה סלבטיצ קי ר \" ח שבט תשס \" ו . וראה לקמן מענה מח ;) ( 3 לר ')\nיונה אבצן מנהל \" ועד שיחות באנגלית \" שהכניס את שיחת ש \" פ ויצא\nבעיבוד אנגלי ( מהעתקה , באדיבות ר ' שמואל שי ' אבצן :])\nנת ' ות \" ח .\nודבר בעתו –\nבין הגאולה דיו \" ד כסלו\nלגאולה די \" ט כסלו .\nאזכיר עה \" צ .\nמז\nכסלו ][\nמענה למערכת הערות התמימים ואנ \" ש מאריסטאון שהכניסו את\nהקובץ דש \" פ וישלח ( קובץ הערות התמימים ואנ \" ש מאריסטאון ש \" פ\nוישב תשמ \" ב ( גליון רמג :))\nוכל החוברות הקודמות המצו \" ב\nוצירף את המענה כללי - פרטי דימים אלו ( לעיל מענה מו .)"],[9200210035,"35\nמענות קודש – ה ' תשמ \" ב\nמח\nכסלו ][\nמענה להנהלת בית חב \" ד אנטווערפן בלגיא שהכניסו את תכנית הבנין\nתשורה סלבטיצקי ר \" ח שבט תשס \" ו :)(\nנת ' ות \" ח . והסכמה וברכה .\nוצירף את המענה כללי - פרטי דימים אלו ( לעיל מענה מו .)\nמט\nכסלו ][\nמענה לר ' אפרים וואלף על דו \" ח מאסיפת הנהלת ה \" ארגון גג \" בו דובר\nבין השאר ע \" ד ההכנות לכנס עולי מרוקו וטוניס שעורכים ביום הבהיר\nיו \" ד שבט הבע \" ל ( ס ' \" מקדש מלך \" ח \" א ע ' 130 . ס ' \" ימי תמימים \" ח \" ח\nע ' 122 , 156 :)\nצ \" ל זהירות וביותר שלא יהי ' הרושם ( ח \" ו ) כאילו נשלחו אנשים לשם\nבשביל להוציא בנ \" י ממדינות ההם וכו ' – נוסף – להמפורסם שנשלחו\nלייסד שם בי \" ס וישיבות וכו ' ( וז \" ע ייסדו שם כולל ) – מובנות התוצאות\nבאם ח \" ו תגיע לשם קס \" ד כזו . וד \" ל .\nכמדומה נדפס במכ \" ע דרשת ובהדגשה היפך הנ \" ל !!\nנ\nכסלו ][\nמענה להשליח ר ' משה הרסון שכתב ע \" ד החיכוכים בקשר להקמת\nמנורה ציבורית בעיר טינעק ניו דזשערזי ע \" י השליח דשם . אנשי הקהילה\nהמקומית התנגדו לזה , ורבני העיר פסקו שאסור לו להקים את המנורה ,\nונתנו פסק זה לממשלת העיר שהתנגדו לכך אף הם . בהמשך לזה כתב\nכ \" ק אדמו \" ר שליט \" א כמה מכתבים לאנשי הקהילה בהסברת החשיבות\nשבמנורה ציבורית ברשות הרבים . אך הנ \" ל עמדו בהתנגדותם , וחשב\nהשליח ללכת לערכאות להלחם להשיג אישור להקמת מנורה ציבורית ."],[9200210036,"36\nמענות קודש – ה ' תשמ \" ב\nבמהלך החיכוכים , הנה א ' הסנטורים המיודד עם חב \" ד כעס על כך\nשהפעילות בנושא נעשתה מבלי להתייעץ עמו מקודם . וכשדיברו עמו\nלפייסו , הציע שבינתיים יפסיקו להלחם על מנורה בעיר טינעק , ולחילופין\nיעזור שתהי ' מנורה בעיר הבירה , טרענטון .\nוכתב הנ \" ל שישנם שלשה אפשרויות : ( 1 לא להתייחס לדברי הסנטור ,)\nולהלחם על כך שתהי ' מנורה ציבורית בטינעק ; ( 2 ) להלחם שיהיו מנורות\nציבוריות בשתי העיירות , טינעק וטרענטון ; ( 3 ) לקבל את הצעתו ולא\nלהלחם שתהי ' מנורה ציבורית בטינעק שנה זו , ולסדר שתהי ' מנורה\nציבורית בטרע נטון .\nמענה כ \" ק אדמו \" ר שליט \" א ( ס ' \" והאר עינינו בתורתך \" ע ' רפח . ס '\nשליחות כהלכתה \" ע '\" 674 :)\n[1 על מה שכתב שהסנטור כעס שלא התייעצו עמו , כתב :]\nוהרי בזה צודק הוא .\n[2 ] סימן את האפשרות השלישית – לא להלחם על מנורה בעיר טינעק\nובמקומה לסדר בעיר טרענטון , וכתב :\nלאחר שיגששו באופן המתאים ויבררו שיש סיכויים להצלחה .\n[3 על כללות המכתב , כתב :]\n(1 ) מלכתחילה אמרתי שיזהרו פון אנצינדן אַ מחלוקת ( ומכו \" כ טעמים .)\n(2 ) בטלנות הכי גדולה שלא התחילו קודם לכל פעולה בהנוגע לטינעק\nבפרסומות ע \" ד המנורה בוושינגטון והשתתפות הפרעזידענט וכו ,'\nובפרסומות ע \" ד המנורה בניו יארק והשתתפות האטארני כללי\nאיבראמס שי .'\n(3 ) כו \" כ מהעסקנים בעיר הנ \" ל לא ידעו כלל מהטעמים שכתבתי\nבמכתבי , וכנראה שכמה גם עתה אין יודעים ע \" ד כל הנ \" ל .\n(4 ) לאחרי אז מ ' האט דערלאזן שרבנים ארטאדאקסים דהעיר יפסקו\nדין להיפך – יביאו הוא וכו ' הענין לערכאותיהם !?"],[9200210037,"37\nמענות קודש – ה ' תשמ \" ב\nנא\nלאחר כ \" ה כסלו , א ' דחנוכה ][\nמענה להרב אברהם יצחק ברוך גערליצקי על מכתבו בהמשך להמדובר\nבהתועדות מוצאי יום א ' דחנוכה – שנתבאר שזה שכתב משה רבינו י \" ג\nספרי תורה ביום אחד , יום פטירתו , הוא כיון שנותר לו רק לגמור מה\nשלא נכתב עד אז , וגם למ \" ד \" תורה חתומה ניתנה \" ופרש \" י ד \" לא נכתבה\nעד סוף ארבעים \", הנה כוונת הדברים הוא שכתב אז את אותן הפרשיות\nשנאמרו שלא על הסדר . במכתבו כתב :\n\" זה עכשיו ראיתי בשו \" ת בנין שלמה ( להגאון בעל חשק שלמה ) שכתב\nבהקדמתו וז \" ל : ועתה כתבו לכם את השירה הזאת וגו ' משום דבש \" ס\nדגיטין אמרינן דר \" י אמר דתורה מגילה מגילה ניתנה ואפי ' למ \" ד דתורה\nחתומה ניתנה מ \" מ כתבו התוס ' שם דנכתב מיד אחר האמירה רק\nדנכתבה על הסדר כמו שה יא סדורה עכשיו ע \" ש בתוס '. וא \" כ באותו זמן\nשנאמר ציווי זה לא הי ' להם לכתוב דכבר כתבו כל התורה עד פרשת\nהאזינו , ולכן אמר ועתה כתבו לכם את השירה , אבל לדורות צריך לכתוב\nכל התורה , עכ \" ל .\"\nמענה כ \" ק אדמו \" ר שליט \" א ( מצילום כתי \" ק – ס ' היובל הערות\nוביאורים ע ' קמד :)\nנת ' ות \" ח\n___\nכמדובר – ( גם ) לקובץ\nנב\nשלהי כסלו ][\nצעטל \" בכתי \" ק שכתב כ \" ק אדמו \" ר שליט \" א לה \" ועד להפצת שיחות \"\"\nבקשר למהדורא תניינא דס ' \" לקוטי אמרים – מהדורא קמא \" שהורה\n( לעיל מענה מה ) להו \" ל לכ \" ד טבת ( מצילום כתי \" ק – \" בית משיח \" גליון\n72 :)"],[9200210038,"38\nמענות קודש – ה ' תשמ \" ב\nכיון שע \" פ השמועה כבר אזלה מהדו \" ק לגמרי ,\nבכדי שאלו שקנו הנ \" ל יהנו מההוספות מבלי שיוכרחו לקנות עוה \" פ כל\nהספר ,\nבכדי שמהד \" ק דהמד \" ק לא תהי ' \" מוזנחת \" וכו '\n– כדאי שלכל לראש יו \" ל כל ההוספות בקונטרס בפ \" ע – לכד טבת ,\nיו \" ל הוצאה ב ' דמהד \" ק דמהד \" ק ( בצילום ) תומ \" י\nנג\nשלהי כסלו ][\n\" צעטל \" בכתי \" ק שכתב כ \" ק אדמו \" ר שליט \" א לר ' שלום דובער הלוי\nוולפא מחבר ספר \" דעת תורה בעניני המצב בארץ הקודש \" (\" כפר חב \" ד \"\nגליון 635 . תשורה שפיצר כ \" ב אד \" ש תש \" ס . תשורה הלפרין כ \" ד סיון\nתשע \" ח :)\nחשאי ומהיר .\nלא מצאתי בספרו ולא במקום אחר , שיעוררו על ענין פשוט ועיקרי : כל\nהאומר להחזיר מהשטחים מפני שלא להתגרות באומות העולם ופקוח\nנפש ( היינו שזהו חיוב ,) במכל שכן וקל וחומר שכך הוא בנוגע לירושלים\nוכותל המערבי ( כיון שדרישתם בזה היא בתוקף יותר וביותר ). ובודאי\nיאמרו כן על כל פנים עתה וכו .'\nכשירעישו על דבר זה ברדיא , מכתבים למערכת וכו ' – ולא חב \" ד יתחילו\nויעשו בזה שלא יאמרו שזהו מעין מיהו יהודי וכו )'( – יפסיקו בההיתר\nלהחזיר , וקצת מהם אולי גם יחזרו בהם .\nוהזריז הרי זה משובח , וככל שיגדל הרעש – ( ובפרט שהנ \" ל מובן ופשוט\nורק שחסר האומר ) תגדל התועלת .\nויהי רצון שיבשר טוב עד \" ז ."],[9200210039,"39\nמענות קודש – ה ' תשמ \" ב\nנד\nועש \" ק מקץ , ער \" ח טבת , ה ' דחנוכה ][\nמענה לר ' לוי גאלדשטיין שכתב :\n\" בהתוועדות דש \" פ וישב ש . ז . ביאר כ \" ק אדמו \" ר שליט \" א פירש \" י ד \" ה\nאת כתנתו וד \" ה את כתנת הפסים , והביאור הי ' בהתאם להדיעה ( שפ \" ח )\nשלפירש \" י \" כתנתו \" ו \" כתנת הפסים \" הם ב ' בגדים , ולא בגד א ' כדעה הב '\nרא \" ם .)(\nולא הבנתי :\nאם \" כתנתו \" היינו חלוק ( פרש \" י ), דהיינו בגד הסמוך לבשר , ו \" כתנת\nהפסים \" היינו בגד שעל גביו , הי ' צ \" ל סדר הפסוק : ויפשיטו . . את כתנת\nהפסים . . ( ואח \" כ ) את כתנתו . . – שכך הוא סדר ההפשטה , תחילה בגד\nהעליון ואח \" כ בגד התחתון ( הסמוך לבשר .)\nואין לומר שלא בא הכתוב להשמיענו סדר ההפשטה , אלא מה שהפשיטו\nבפועל , דאפ \" ה , לאיזה טעם יהפוך הסדר , ובפרט שמצד חשיבות וכן\n( ובעיקר ) מצד שעיקר השנאה היתה מצד הכתנת פסים , הי ' צ \" ל נכתב\nתחילה כתנת הפסים .\nמשא \" כ להדיעה הב ' ( שהם בגד א '), ליכא נפק \" מ בסדר הפסוק .\nאגב , בנוגע לפ ' דבגדי כהונה נתבאר ( בהתווע ' דש \" פ תצוה (?)) דיוק הסדר\nבהכתובים בנוגע להבגדים , עפ \" י סדר ההלבשה .\"\nמענה כ \" ק אדמו \" ר שליט \" א ( מהעתקת המזכיר . המענה מתפרסם בזה\nלראשונה באדיבות הנמען שי ' וזכות הרבים תלוי ' בו :)\nהשלח לקובצים\nהרי כו \" כ מפרשים דנו בזה !\nנה\nבדר \" ח טבת , ז ' דחנוכה ][\nמענה לר ' מיכאל אהרן זליגסון ( מצילום כתי \" ק – נדפס לעיל , מתפרסם\nבזה לראשונה ( במלואו . חלקו בקובץ \" שלשלת היחס \" ע ' צא ) באדיבות\nהנמען שי ' וזכות הרבים תלוי ' בו לקו \" ש חל \" ה ע '. 264 :)"],[9200210040,"40\nמענות קודש – ה ' תשמ \" ב\nא . במכתבו כתב : \" בשיחת ש \" פ מקץ שבת חנוכה ור \" ח טבת ביאר כ \" ק\nאדמו \" ר שליט \" א מה שאצל המלאכים דאברהם נזכר רק \" ויאכלו \" ולא\nוישתו \"\" – מפני שהעיקר הוא האכילה והשתי ' טפלה , וכמובן גם\nמפשטות הסיפור שכיבדם בשניהם הן באכילה והן בשתי '. ולא הבנתי\nשהרי במאמרי אדה \" ז – תקס \" ב ח \" ב ( שנדפס ז \" ע ) ע ' תטו : \" ולכך לא\nנזכר השתי ' באכילת המלאכים אצל אברהם מפני שאם היו אוכלין גם\nחיצוניות המאכל שהוא הגורם חמימות והמשקה מקרר כו ' אבל\nכשהפריד אברהם רוחניות המאכל לבד ונתן להם לא נצטרכו לשתות .\"\"\nמענה כ \" ק אדמו \" ר שליט \" א :\n[1 על מה שכתב : \" שכיבדם בשניהם הן באכילה והן בשתי '\", כתב :]\nחמאה וחלב .\n[2 סימן בעיגול את התיבות : \"( שנדפס ז \" ע ) ע ' תטו \", וכתב :]\nעדיפא הו \" ל להקשות על הש \" ס ( ב \" מ . . ) כמו שאכלו ושתו\n[3 סימן בעיגול את התיבות : \" לא נצטרכו לשתות \", וכתב :]\nויל \" פ – אבל שתו מפני טעם טפל ולכן לא נזכר בפי ' ( שיהי ' לישראל גם\nהבאר עי \" ז דוקא וכו '\n[4 על כללות השאלה , כתב :]\nהרי המדובר בפרש \" י בפשוטו של מקרא .\nוגם בכו \" כ ספרי טעמי המנהגים דעברו על איסור בשר בחלב ( וש \" נ –\nפס \" ר ועוד )\nב . במכתבו כתב : \" בלוח היום יום בשלשלת היחס בתולדות כ \" ק אדמו \" ר\nהאמצעי מתחיל תולדותיו : \" הוד כ \" ק אדמו \" ר \" – מה שלא נזכר תואר\nזה אצל שאר רבותינו נשיאינו .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\nקרוב לודאי שזהו השמטת המעתיק\nולהעיר מהתוארים בשערי הס ' ( ואולי גם בהקוה \" ק )\n[ וראה לקמן מענות נו , ק ז .]"],[9200210041,"41\nמענות קודש – ה ' תשמ \" ב\nנו\nד ' טבת ][\nמענה לר ' מיכאל אהרן זליגסון שכתב : \" בהמשך למענת כ \" ק אדמו \" ר\nשליט \" א ע \" ד תואר \" הוד \" אצל כ \" ק אדמו \" ר האמצעי – \" קרוב לודאי\nשזהו השמטת המעתיק ולהעיר מהתוארים בשערי הס ' ( ואולי גם\nבהקוה \" ק )\" [ לעיל מענה נה ], ראיתי בשערי הס ' שלא נזכר \" הוד \" אצל אף\nא ' מהם , משא \" כ בהקוה \" ק נזכר \" הוד \". ולכן שאלתי אם לעורר ( ומה\nלעורר ) בלוח התיקון לזה , א ) להשמיטו בכלל או ב ) להעתיקו אצל כולם ,\nאו שיש איזה טעם פנימי בקשר לאדמו \" ר האמצעי \" ( מצילום כתי \" ק –\nנדפס לעיל , מתפרסם בזה לראשונה באדיבות הנמען שי ' וזכות הרבים\nתלוי ' בו . קובץ \" שלשלת היחס \" ע ' צב :)\nכ \" ק אדמו \" ר שליט \" א סימן בחץ ובעיגול את התיבות \" להעתיקו אצל\nכולם .\"\nנז\nד ' טבת ][\nמענה לה \" ועד להפצת שיחות \" על ההודעה שההדפסה השני ' דס ' \" לקוטי\nאמרים – מהדורא קמא \" שהורה כ \" ק אדמו \" ר שליט \" א להו \" ל ( לעיל\nמענה נב ) – נכנסה כבר לדפוס (\" בית משיח \" גליון 72 :)\nות \" ח ת \" ח על הבשו \" ט .\nנח\nה ' טבת ][\nמענה לועד כתיבת ספר תורה הכללי לילדי ישראל שכתבו ע \" ד התחלת\nהכנת התעודות עבור האותיות שנקנו בספר התורה השני ( ס ' אלבום\nאות בספר תורה \" ע '\" 89-90 :)\n[1 ] כ \" ק אדמו \" ר שליט \" א הורה לציין בתעודות בקשר לספר התורה\nהראשון – כ \" ף מנ \" א תשמ \" א , ולספר התורה השני – פורים תשמ \" ב ;\nוכתב ( לציין :)\nספר התורה השני – כדי לשלול לעז ."],[9200210042,"42\nמענות קודש – ה ' תשמ \" ב\n[2 על כללות המכתב , כתב :]\nמה נעשה בפועל להמשיך קטנים וקטנות לס \" ת שלהם .\nנט\nועש \" ק ויגש , ו ' טבת ][\nמענה לא ' השלוחים על מכתבו ע \" ד המצב במקומו ( מהעתקה . המענה\nמתפרסם בזה לראשונה באדיבות א ' מאנ \" ש שי ' וזכות הרבים תלוי ' בו :)\nכעצת עסקני אנ \" ש שי '. \" כמדומה \" לא בפעם הא ' אצלו מצב כהנ \" ל ,\nוכן בכל מוסדות חינוך הכשר שבארצות הברית . אזכיר עה \" צ .\n[ וראה גם לקמן מענות : ס ו , ע ח , קפ ג , ר כא .]\nס\nח ' טבת ][\nמענה לא ' השלוחים שהכניס ( ללא ידיעת השליח האחר במקומו ) הצעה\nלתכנית חדשה (\" התקשרות \" גליון קכה :)\nדי מה שעל אחריותו ע \" ע !\nולא יכנס ויתחיל בהנ \" ל , ומעוד כמה טעמים .\nאזכיר עה \" צ .\nסא\nט ' טבת ][\nמענה להרב דוד ראסקין על מכתבו בו כמה שאלות בנוגע ל \" צבאות\nהשם \" ( ס ' \" שליחות כהלכתה \" ע ' 237 :)\nבשאלותיו וכיוצא בזה – שייך להנהלת צאגו \" ח ."],[9200210043,"43\nמענות קודש – ה ' תשמ \" ב\nסב\nלאחר עשירי בטבת ][\nמענה ל \" ועד הנחות התמימים \" על שאלתם בהמדובר בשיחת עשירי\nבטבת :\n\" בנוגע למ \" ש בעמוד יז , שהנהגת יעקב שמקדים אפרים למנשה כיון\nשהקב \" ה אוהב הקטנים כו ' – בעבודת האדם הוא : שע \" י הקדמת הכנעה\nושפלות בעבודת התפלה , ממשיכים אח \" כ ע \" י התפלה \" יהי רצון \", רצון\nחדש , יותר מע \" י ברכה , שממשיך רק משרשו ומקורו , כמ \" ש \" איש אשר\nכברכתו ברך אותם \" –\nהרי מבואר בפירוש בהדרושים המבארים החילוק בין תפלה וברכה\n( לקו \" ת ראה יט , רע \" א . ד \" ה כה תברכו תרכ \" ו . המשך תער \" ב ח \" ב ס \" ע\nתשלו ואילך . ע ' תשסו ואילך . ועוד שברכת יעקב לאפרים ומנשה הי ')\nדוקא בבחי ' ברכה ( ולא תפלה ) שממשיך רק משרשם ומקורם , ולכן אמר\nיעקב ליוסף \" ידעתי בני ידעתי גם הוא יהי ' לעם וגם הוא יגדל ואולם\nאחיו הקטן יגדל ממנו \", ולא בירך מנשה שיגדל עוד גם מאפרים –\nשהרי \" ז הי ' ברכה ואין בכח הברכה כ \" א להמשיך ולגלות מה שכבר יש\nבמקור כו .\"'\nמענה כ \" ק אדמו \" ר שליט \" א ( מצילום כתי \" ק – תשורה שטרן ט \" ו אד \" ר\nתשס \" ה :)\nעל מה שכתבו : \" הרי מבואר בפירוש כו '\", כתב :\nבכלל\nלכן הדגשתי שהוא ע \" ד ולא אותו הענין ,\nכי ( כמובן בלאה \" כ מכו \" כ מקומות ) כמה דרגות בברכה , וכן [ כמה דרגות ]\nבתפלה .\nברכת הדיוט , ברכה סתם , בר \" כ . סוג בר ' יצחק ( גבו ') יעקב ומשה . עשר\nל ' נק ' תפלה . עושה מחצה , כולה , מהפכת כעס וכו '\nכנראה שיטתם שכאו \" א ובכל זמן יכול להמשיך מהמקור ועד ממקור\nדמקור !!\nלמרות שמפורש שרשב \" י לאחרי כל עבודתו ( ותפלותיו ) המשיך מקורו\nבהסתלקותו בלג בעומר ."],[9200210044,"44\nמענות קודש – ה ' תשמ \" ב\nסג\nי \" א טבת ][\nמענה להרב דוד ראסקין שכתב דו \" ח מאסיפת הנהלת ישיבת תו \" ת\nהמרכזית בקשר לסיום ס \" ת הכללי הראשון שלהם שיתקיים – ע \" פ\nהמענה שקיבלו ( לעיל מענה מד ) – אור ליום ג ' כ \" ד טבת . במכתבו כתב :\n\" מקוים שנזכה שכ \" ק אדמו \" ר שליט \" א ישתתף וגם יסיים בכתיבת\n( למלאות בדיו ) האות ב ' של תיב ת בראשית \" ( מצילום כתי \" ק – תדפיס\nמספר \" ועבדי דוד \" – ס \" ת הכלליים שע \" י תו \" ת המרכזית – ע ' 47 :)\nכ \" ק אדמו \" ר שליט \" א סימן בעיגול תיבת \" יסיים \", וכתב :\nיראתי וכו ' וגם בהקודם לא עשיתי כו '\nסד\nט \" ו טבת ][\nמענה להרב דוד ראסקין על מכתבו בקשר למעמד סיום ס \" ת הכללי\nהראשון שע \" י ישיבת תו \" ת המרכזית , בו הציע אשר הסיום יתקיים ב -\n770 תדפיס מספר \" ועבדי דוד \"( – ס \" ת הכלליים שע \" י תו \" ת המרכזית –\nע ' 20 , 56 יומן ר ' מיכאל אהרן שי ' זליגסון :).\nבהאטל גדול או בבנין בתו \" ת וכו '\nסה\nטבת ][\nמענה להת ' ישראל מרדכי הלוי קאזאמינסקי שכתב שבאנציקלופדיא\nיודאיקא מייחסים את התמונה הנפוצה דהבעש \" ט – לבעל - שם אחר שחי\nופעל בלונדון ( לקו \" ש חי \" ט ע ' 531 \" התקשרות \" גליון תקסא . יומן ר '.\nמיכאל אהרן שי ' זליגסון :)\nכמדומה יש בזה ר \" ד מרבותינו שאינו הבעש \" ט נ \" ע – שע \" פ המסורה\nצ \" ל י \" ג ?( – י \" ב ) תק \" ד ניכר בהזקן ."],[9200210045,"45\nמענות קודש – ה ' תשמ \" ב\nסו\nטבת ][\nמענה לא ' השלוחים על מכתבו – בהמשך להמענה שקיבל ( לעיל מענה נט )\n– בו כתב את אשר ייעצו לו העסקנים ( המענה מתפרסם בזה לראשונה\nבאדיבות א ' מאנ \" ש שי ' וזכות הרבים תלוי ' בו :)\nבני אדם שכל עזרתם היא : עצה שפלוני צריך לעשות , כי הם פוחדים\n( מקול עלה נדף ) הרי זה אינם עסקנים כלל והעצה אינה חכמה כי אם\nמורך לב .\n2 ) באם חושש שפלוני מזיק עפ \" י שו \" ע יזמינו לב \" ד ובהקדם כמובן .\nסז\nאור לט \" ז טבת ][\nמענה לר ' צבי מאיר שטיינמעץ ( תשורה זלמנוב כ \" ד סיון תשע \" א :)\n[1 ] במכתבו כתב , שבמשך השנים כאשר מסר שיעורים בס ' התניא הלך\nבעקבות \" לוח התיקון \" ו \" הערות ותיקונים \" שבסו \" ס התניא , ובנוסף לזה\nרשם לעצמו עוד כו \" כ תיקונים בהתאם לדקדוק וכו '. וכתב שעתה , כאשר\nנדפס ס ' \" ליקוטי אמרים – מהדורא קמא \", מצא כי רוב התיקונים\nשרשם לעצמו נמצא ים באחד הנוסחאות אשר שם . ושאל , שעפ \" ז אולי\nכדאי להשלים את התיקונים שבסו \" ס התניא , ע \" פ הנמצא בס ' מהדו \" ק\nהנ \" ל , ועוד תיקוני לשון ע \" פ דקדוק .\nמענה כ \" ק אדמו \" ר שליט \" א :\n1 נת ' והמצו \" ב ות \" ח ת \" ח .) 2 ) ידבר בזה ( בהקדם !) עם המתעסקים\nבההו \" ל דתניא מהדו \" ק עם קונ ' המילואים שהו \" ל ועוד המשך יבוא .\n[2 על ההודעה ע \" ד הולדת נכדתו , כתב :]\nת \" ח על הבשו \" ט ויגדלוה הורי ' שי ' לתחומע \" ט אזכיר עה \" צ ."],[9200210046,"46\nמענות קודש – ה ' תשמ \" ב\nס ח\nח \" י טבת ][\nמענה להנהלת ישיבת \" תורת אמת \" בירושלים עיה \" ק ( ס ' \" תורת אמת \"\nע ' 441 :)\nעל מה שכתבו ע \" ד תורמים לישיבה , כתב :\n1 ת \" ח על הבשו \" ט . נלקח ( אלו יעמדו על הברכה .))\nעל מה שכתבו : \" לרגל שבעים שנה של התייסדות הישיבה \", כתב :\n2 ) לא ניצלו כלל וכלל ( כדרך שלא ניצלו – 50 שנה וכו ')! ולאח \" ז\nמתאוננים על המצב הכספי ( וגם על חוסר תלמידים )! בלי התבוננות\nיתרה כלל הייתה צ \" ל עכ \" פ : נאכמאַכן אַנדערע ( עכ \" פ עתה ): להו \" ל\nאַלבום יפה ( כולל תמונות ) קו \" ק יפה , פרסים יפים ( להמתנדבים בקשר\nל 70 שנה ), בַנקעט מסודר ויפה באה \" ק ( בעונת התיירות ) בצירוף\nהשתתפות גדולי ישראל )( ועוד . וזוהי הדרך לכיסוי כל הדעפיציטן\nדלעתיד .\n3 ) בנוגע לפועל – באם ימצאו ( דוקא עמלק \" פ , ולא כ \" טובה \") איש\nהמסוגל לזה יתענינו בזה . באם לאו – גם לא יתחילו . כנראה הורגלו\nב \" פערל גרופען \" עד שאפילו אין קס \" ד ע \" ד פערל אַפן האַלדז !!\n4 ) כמובן אין כוונתי ל \" מוסר \" ולא לתירוצים ושקו \" ט ולמכ ' רצו \" ש –\nכ \" א כולי האי ואולי כו .' וא \" צ לכתוב לי בזה עוד .\nאזכיר עה \" צ\nסט\nי \" ט טבת ][\nמענה לא ' שכתב שיש לו חתונה ביום ער \" ח שבט , וכתב שחושש שמעמד\nסיום ס \" ת הכללי ביום זה יבלבל זאת ( יומן ר ' מיכאל אהרן שי ' זליגסון :)\nבטחון בהשם ועשי ' בדרך הטבע וה ' יצליחם אזכיר עה \" צ ."],[9200210047,"47\nמענות קודש – ה ' תשמ \" ב\nשבעים\nכ \" ד טבת ][\nממענה ל \" ועד הנחות התמימים \" על מכתבם בו העלו הצעה להו \" ל –\nלקראת יום הבהיר י \" א ניסן שמונים שנה – חוברת שתכלול את\nהמאמרים שנאמרו ביום הבהיר י \" א ניסן במשך השנים ( ס ' \" מאוצר\nהמלך \" ח \" ב ע ' 195 ליקוט כתי \" ק יום הבהיר י \" א ניסן ע '. 38 :)\nכ \" ק אדמו \" ר שליט \" א שלל הצעה זו , וכתב :\nויציעו מה שא \" צ להגהתי וכיו \" ב\n[ וראה לקמן מענה צ ד .\nבקשר ליובל שמונים שנה להולדת כ \" ק אדמו \" ר שליט \" א – ראה גם לקמן\nמענות : ע ד , צ ד , ק ג , ק טו , קכ ב , קכ ג , קכ ד , קכ ו , קכ ט , קנ ה , קנ ט , רכ ט .]\nעא\nכ \" ה טבת ][\nמענה להת ' שלום יעקב חזן והת ' יוסף יצחק איידלמן המתעסקים בהכנת\nס ' המאמרים תרס \" ה היו \" ל ע \" י מערכת \" אוצר החסידים \" ( מצילום\nכתי \" ק – ס ' \" מאוצר המלך \" ח \" א ע ' 354 :)\nומגודל ענין ג ', ובפרט כשר \" ה וכו ' ביום ג ' – כדאי לצרף עוד – שיהיו ג .'\nאזכיר עה \" צ .\nמהיר\nעב\nכ \" ה טבת ][\nממענה לר ' מיכאל אהרן זליגסון ור ' יוסף יצחק שגלוב בקשר לס ' \" היום\nיום עם הערות וציונים \" ( ח \" א ) שבעריכתם ( מהעתקה , באדיבות ר '\nמיכאל אהרן שי ' זליגסון :)\n.[ ]. והעיקר – ישתדלו בהפצת הס ' ע \" מ להתעניין ע \" ד מהד \" ת בצירוף\nכו ' כרגיל ."],[9200210048,"48\nמענות קודש – ה ' תשמ \" ב\nעג\nשלהי טבת ][\nמענה כללי - פרטי דימים אלו [ בין השאר – להת ' אברהם לייב שוחאט\nראש ישיבת ליובאוויטש קסבלנקה מרוקו על דו \" ח ( מהעתקה , באדיבות\nמערכת הספר \" שליחות כהלכתה :])\"\nנת ' ות \" ח .\nודבר בעתו –\nבסמיכות לכ \" ד טבת\nהילולא אדה \" ז .\nאזכיר עה \" צ .\nעד\nשלהי טבת ][\nמענה לתלמידים השלוחים לישיבת ליובאוויטש קסבלנקה מרוקו\nשכתבו : \" ברשות ההנהלה אנו מבקשים עצת והסכמת כ \" ק אדמו \" ר\nשליט \" א אם לנסוע לניו יורק להיות בחצרות כ \" ק אדמו \" ר שליט \" א עבור\nיום הבהיר י \" א ניסן הבעל \" ט שמונים שנה להולדת כ \" ק אדמו \" ר\nשליט \" א לאורך ימים ושנים טובות , ואם לישאר ג \" כ עבור חגה \" פ ולחזור\nאיזה ימים אחרי חגה \" פ הבעל \" ט \" ( מהעתקה . המענה מתפרסם בזה\nלראשונה באדיבות מערכת הספר \" שליחות כהלכתה \" וזכות הרבים\nתלוי ' בהם :)\nכ \" ק אדמו \" ר שליט \" א סימן בעיגול את התיבות \" ברשות ההנהלה ;\"\nסימן בעיגול את מה שכתבו : \" לישאר ג \" כ עבור חגה \" פ ולחזור איזה ימים\nאחרי חגה \" פ הבעל \" ט \", וכתב :\nלבוא לכאן לי \" א ניסן ולנסוע חזרה קודם חה \" פ – אינו ענין ומכמה\nטעמים .\n– כיון שקשור בהשלימות דכמה ענינים דקאזאבלאנקא – ישאלו ב \" ד\nדרבני אנ \" ש שי ' ויעשו כעצתם ."],[9200210049,"49\nמענות קודש – ה ' תשמ \" ב\nעה\nלפני חודש שבט ][\nמענה להחתן הת ' מנחם מענדל גארדאן וב \" ג רחל קליין שכתבו :\n\" התדברו מב ' הצדדים לקבוע זמן חתונתנו ליום ד ' ג ' שבט הבע \" ל כאן\nבקראון הייטס ומבקשים הסכמת וברכת כ \" ק אדמו \" ר שליט \" א \"\n( מצילום כתי \" ק – תשורה גארדאן ו ' אלול תשס \" ז :)\n[1 סימן שני קווים תחת התיבות \" כאן בקראון הייטס .\"]\n[2 ] מחק תיבת \" ומבקשים \" וסימן בחץ את התיבות \" הסכמת וברכת כ \" ק\nאדמו \" ר שליט \" א .\"\nעו\nלפני חודש שבט ][\nמענה להחתן הת ' מנחם מענדל גארדאן וב \" ג רחל קליין שכתבו : \" לאחרי\nהתדברות שנית מב ' הצדדים התדברו להקדים קביעת זמן החתונה ליום\nאחד , ג ' ב ' שבט הבעל \" ט כאן בקרון - הייטס ומבקשים הסכמת וברכת\nכ \" ק אדמו \" ר שליט \" א \" ( מצילום כתי \" ק – תשורה גארדאן ו ' אלול\nתשס \" ז :)\n[1] סימן שני קווים תחת התיבות \" כאן בקרון - הייטס .\"\n[2 על מה שכתבו : \" ומבקשים הסכמת וברכת כ \" ק אדמו \" ר שליט \" א ,\"]\nכתב :\nבטח בהסכמת כולם\nויהא בשטומו \" צ בכל\nעז\nתחלת שבט ][\nמענה כללי - פרטי דימים אלו [ בין השאר : ( 1 ) למערכת הערות התמימים\nואנ \" ש מאריסטאון על הקובץ דש \" פ בא והגליונות שלפני זה ( קובץ\nהערות התמימים ואנ \" ש מאריסטאון ש \" פ בשלח תשמ \" ב ( גליון רנ ;)) ( 2 )\nלהנהלת \" צעירי אגודת חב \" ד \" המרכזית על דו \" ח ממלוה - מלכה השנתית"],[9200210050,"50\nמענות קודש – ה ' תשמ \" ב\nשהתקיימה במוצש \" ק שמות ( מהעתקה , באדיבות מערכת הספר \" ועבדי\nדוד :])\"\nנת ' ות \" ח\nודבר בעתו –\nבסמיכות לעשתי עשר חודש באחד לחודש\nאזכיר עה \" צ\nעח\nח ' שבט ][\nמענה לא ' השלוחים על מכתבו בקשר לה \" קעמפ \" במקומו ( מהעתקה .\nהמענה מתפרסם בזה לראשונה באדיבות א ' מאנ \" ש שי ' וזכות הרבים\nתלוי ' בו :)\nישאלו עוד הפעם\nכעצת עסקני אנ \" ש שי ' שב .[ ].\nאזכיר עה \" צ\nעט\n[ לאחר יום הבהיר יו \" ד שבט ]\n\" צעטל \" בכתי \" ק שכתב כ \" ק אדמו \" ר שליט \" א להמניחים בו ציון מראי -\nמקומות למאמר ד \" ה באתי לגני דיו \" ד שבט ( מצילום כתי \" ק – ריש\nסה \" מ תשמ \" ב ( הוצאת ברוקלין , תשס \" ב :))\nמ \" מ להמאמר\nע \" ח היכל א ענף ב ( ולהוסיף המ \" מ דמבו \" ש וכו ' – הובאו בס '\nהליקוטים מע ' צמצום )\nהיום יום יא תשרי\nכשט ס ' רצב\nלקוא ואות בתחלתם"],[9200210051,"51\nמענות קודש – ה ' תשמ \" ב\nש ' היחוד פיב\nסהמצ להצצ תפלה פ \" מ\nתרכז ע ' תכא תנח\nתרסו כז\nצבאות ( לציין גם לתהלים פ '\nפ\nי \" א שבט ][\nמענה להנהלת בית חב \" ד קליבלנד אוהיו על מכתבם בקשר לבניית מקוה\nחב \" ד ( מצילום כתי \" ק – קובץ הערות וביאורים אהלי תורה ש \" פ קרח\nתשע \" ו ( גליון א ' קי ). ס ' \" שליחות כהלכתה \" ע ' 140 :)\n(1 ) מתאר מקרה משונה : חב \" ד הודיעו שבונים מקוה , והכל מוזמנים\nלהשתמש בה . – ע \" פ שו \" ע חבד צריכה לבנות ע \" פ פס \" ד רבני חבד\nמכו \" כ שנים המפורסם , ורבבות בנ \" י נוהגים כן כמפורסם . – הציעו\nלהם שיעכבו הבני ' עד שיתדברו . ובתחלת ההתדברות הודיעום\nשמקואות חב \" ד בכל העולם כו ' ( 1)\n(2 ) הרי כבר נענו – אין ענינם להכנס למחלוקת , ולא לפוליטיקא ולא\nלהכריח מי שהוא וכו ' – ולכן ימשיכו כפי שהתחילו יבנו חב \" ד\nהמקואות בעצמם – ואין לאחרים לכפות עליהם רצונם וכו ' – מתוך\nהזמנה בספ \" י ובקשה שכל הרוצה להצטרף תבוא עליו ברכה , וגדול\nהשלום וכו '. וכל הרוצה לבנות בפ \" ע באופן אחר – לא יזלזלו בו און\nפשיטא ניט שרייען וכו ', וכשיטת חב \" ד מתמיד – מיוסדת על הוראת\nחז \" ל : לקיים מה שנאמר האמת והשלום אהבו ( יבמות יד , ב . ולהעיר\nמרמב \" ם הל ' תעניות בסיומן .)\nפ א\nשבט ][\nמענה כללי - פרטי דימים אלו [ בין השאר – למארגני כתיבת ס \" ת הכללי\nלזכות בנ \" י שברוסיא ( ס ' אלבום \" אות בספר תורה \" ע ' 205 . וראה לקמן\nמענה פ ד :])"],[9200210052,"52\nמענות קודש – ה ' תשמ \" ב\nנת ' ות \" ח ודבר בעיתו בסמיכות ליו \" ד שבט , העשירי יהי ' קודש . אזכיר\nעה \" צ .\nפב\nשבט ][\nמענה לר ' אברהם אלתר הלוי הבר – שהכניס את הצעת אביו ר ' ישראל\nצבי הלוי הבר , שו \" ב במדינת רומניא בשליחות כ \" ק אדמו \" ר שליט \" א –\nלזכות את יהודי רומניא ברכישת אותיות בס \" ת הכללי . וציין שבנדו \" ד\nיקשה הדבר לרשום אותם בצורה הרגילה ( היינו ע \" י שכל אחד ירכוש\nבעצמו מכספו הפ רטי , בציון שמו ושם אמו וכו '), הן משום שרובם ככולם\nאינם מודעים למשמעות הענין , וה ן מפאת הקושי הטכני להגיע א ליהם\nמפני היות מדינת רומניא חלק מהגוש הקומוניסטי ( ס ' אלבום \" אות\nבספר תורה \" ע ' 183 :)\nכבר מילתי ' אמורה וכמה פעמים על דבר גודל וחשיבות ורציניות הענין\nוכו ', ואשר ההקדם ישובח , ובמיוחד בנוגע לאחב \" י שמאחורי – הנקר '\nבדברי העולם \" מסך הברזל \", וכמדובר עוד הפעם בהתוועדות דעשתי\nעשר חודש באחד לחודש . אזכיר עה \" צ .\n[ וראה לקמן מענות פ ג , ק עא .]\nפג\nשבט ][\nמענה לר ' אברהם אלתר הלוי הבר שכתב – בקשר לס \" ת הכללי עבור\nהיהודים הנמצאים \" מאחורי מסך הברזל \" במדינת רומניא ( ראה לעיל\nמענה פ ב ) – אשר אין אפשרות להשיג רשימת שמות של כל יהודי המדינה\nס ' אלבום \" אות בספר תורה \" ע '( 183 :)\nודלא בידם לעשות זאת בעצמם ."],[9200210053,"53\nמענות קודש – ה ' תשמ \" ב\nפד\nשבט ][\nמענה לר ' מנחם מענדל פוטערפאס , ר ' מרדכי קוזלינר , ור ' גרשון דו בער\nשיף – שכתבו ע \" ד תכניתם לכתוב ס \" ת כללי לזכות בנ \" י הנמצאים\nמאחורי מסך הברזל \" ברוסיא ( ס ' אלבום \" אות בספר תורה \" ע '\" 205 :)\nשייך להחליט ( להחלטת ) ועד הרבנים דהס \" ת שבאה \" ק .\nוצירף את המענה כללי - פרטי דימים אלו ( לעיל מענה פ א .)\nפה\nשבט ][\nמענה לר ' אפרים וואלף ( ס ' \" ימי תמימים \" ח \" ח ע ' 158 :)\n[1 על מה שכתב ע \" ד דרישות איש מסויים וה \" אולטימטום \" שהציג ,]\nכתב :\nכמפורסם – כל כיוצ \" ב שייך לבי \" ד אנ \" ש שיחי ' שבאה \" ק ולפלא הכי\nגדול הפני ' למעבר לים !?\n[2] על מה שכתב ע \" ד מכתב ממלמדים בתלמוד - תורה מסויים ע \" ד\nהשתדלות בענינם בארצה \" ב , כתב :\nמפורסם שאין המזכירות עוסקת בדי \" ת ולפלא הכי גדול בקשה הנ \" ל .\nפו\nשבט ][\nמענה להרב מרדכי מענטליק על שאלתו בהמבואר בלקו \" ש חט \" ז שיחה\nד לפרשת תשא ס \" ג ( ע ' 409-10 ): \" דער ערב רב גייט ניט אריין אין דעם\nמספר פון ( די ס ' רבוא פון ) בנ \" י \", ובהערה 13 \" וכדמוכח ג \" כ מהמנין דפ ':\nבמדבר ופ ' פינחס שלא נמנו כ \" א בני השבטים \". ושאל הנ \" ל עפ \" ז –\nלהמובא דישראל ר \" ת יש ששים רבוא אותיות לתורה – האם גר יש לו\nאות בתורה ( קובץ הערות התמימים ואנ \" ש 770 ש \" פ משפטים תשמ \" ב\nגליון קלד :))("],[9200210054,"54\nמענות קודש – ה ' תשמ \" ב\nמאין יקח נשמה וחיות אם לא מהס \" ת\nמעין רמז להנ \" ל דעקיבא ( או בה \" א ) מהכתוב או \" ז לצדיק גו '\nפז\nשבט ][\nמענה להשליח ר ' יוסף דוד ווייטמאן שהכניס צרור מכתבים של חברי\nהקבוצה מברזיל שהגיעו לחצרות קדשנו ליום הבהיר יו \" ד שבט ( תשורה\nווייטמאן י \" א אלול תשס \" ו :)\nאזכירם עה \" צ , בל \" נ , לתוכן מכתבם . בהשייכים להמוסדות – כעצת\nההנהלה . בהשאר – כעצת ידידים מבינים שעל אתר . באלו שיש הוספה\n– תבוא במכתב ( או בטלפון ) כשיגיע התור .\nפ ח\nי \" ז שבט ][\nמענה לר ' מיכאל אהרן זליגסון שכתב :\n\" בימים אלו דיבר אתי אדמו \" ר מסקוליע שליט \" א ועורר אותי ע \" ד מה\nשכ \" ק אדמו \" ר שליט \" א דיבר אתו ע \" ד שם הספר של זקנו זצ \" ל – אור\nדוד – ומה שלא נזכר גם שמו השני – יצחק [ יחידות י \" ג תמוז תשמ \" א –\nשיחות קודש תשמ \" א ח \" ד ע ' 777 .]\nושאלני ב \" היום יום \" ( ג ' שבט ) נזכר מכ ' אדמו \" ר הצ \" צ ע \" ד הס ' תו \" א\nוכו ' ושמסיים המכ ': \" ושם המחבר נאה לו שניאור . .\" שמזה רואים\nשהשם תורה אור הוא בעיקר רק עם שם א ' ( שמו הראשון ) ולא ב ' שמות .\nוכמו \" כ רואים במחברים שרמזו רק שם א ' בשם הספר ( ולא כל השם .)\nובכן שואל לכ \" ק אדמו \" ר שליט \" א בהנוגע לפועל – שמכין עתה עוד ספר\n( של זקנו זצ \" ל ) לדפוס ורוצה לברר לאור כל הנ \" ל – הוראת כ \" ק אדמו \" ר\nשליט \" א .\"\nמענה כ \" ק אדמו \" ר שליט \" א ( מצילום כתי \" ק – נדפס לעיל , מתפרסם בזה\nלראשונה באדיבות הנמען שי ' וזכות הרבים תלוי ' בו . ס ' \" נלכה\nבאורחותיו \" ע ' 223 :)"],[9200210055,"55\nמענות קודש – ה ' תשמ \" ב\n[1 סימן בחץ את התיבות \" ולא ב ' שמות \", וכתב :]\nהשם זלמן הוא כינוי ולא שם ( דלה \" ק )\n[2 סימן בחץ את התיבות \" ולא כל השם \", וכתב :]\nבכלל – בעל השם יכול לעשות בהשם כרצונו – לחתום בשם א ' וכו ' –\nונפק \" מ בגיטין וכיו \" ב\nפ ט\nאור לכ \" ב שבט ][\nמענה לא ' מאנ \" ש שביקש ברכת כ \" ק אדמו \" ר שליט \" א עבור זוגתו\nהנכנסת בקרוב לחודש השביעי להריונה ( מהעתקה . המענה מתפרסם\nבזה לראשונה באדיבות הנמען שי ' וזכות הרבים תלוי ' בו :)\nאזכיר עה \" צ\nצ\nכ \" ג שבט ][\nמענה להרב דוד ראסקין שכתב דו \" ח מאסיפת הנהלת ישיבת תו \" ת\nהמרכזית בקשר לכתיבת ס \" ת הכללי השני שלהם , וכתב : \" ומבקשים\nברכה להצלחה בכהנ \" ל \" ( תדפיס מספר \" ועבדי דוד \" – ס \" ת הכלליים\nשע \" י תו \" ת המרכזית – ע ' 54 :)\nברכה להצלחה ][ רבה בכהנ \" ל ][\nאזכיר עה \" צ\nצא\nועש \" ק משפטים , כ \" ו שבט ][\nמענה לא ' מאנ \" ש ( מהעתקה . המענה מתפרסם בזה לראשונה באדיבות\nר ' שניאור זלמן יצחק יהושע שי ' חאנין וזכות הרבים תלוי ' בו :)\nכמובן שיהי ' סיכויים ע \" פ טבע לעמוד בתנאים הכספיים"],[9200210056,"56\nמענות קודש – ה ' תשמ \" ב\nקרן במחנה ישראל הגמ \" ח ישתתפו בגמ \" ח עד סך עשרת אלפים\nלקניית הבית\nאזכיר עה \" צ שיהי ' הצלחה רבה\nצב\nער \" ח אדר ][\nמענה להרב יצחק יהודה ירוסלבסקי ( ס ' \" הרבי ויהדות ספרד \" ע ' 407-8 .\nס ' \" הרב אשכנזי \" ע ' 526 . וחלקו מתפרסם בזה לראשונה , מהעתקת\nהמזכיר , באדיבות הנמען שי ' וזכות הרבים תלוי ' בו :)\nעל מה שכתב ע \" ד ועד רבני אנ \" ש באה \" ק , כתב :\n1 ) ויה \" ר שיהא בהצלחה כהנ \" ל . והנה כ \" ז הזזה היא בערך הרבנות כפי\nשהייתה ברוסיא בפוילין וכו ' לפני המלחמה , שענינה הייתה לעסוק\nבתורה בביתם , וכשבאו לביתם בשאלה ובד \" ת היו עונים לשאלותיהם .\nכשהתחילו לעשות אגוה \" ר , ועד הרבנים וכיו \" ב הייתה הכוונה\nשהרבנים יַראו יזמה יֵעָשו כח פעיל ויתחילו לתַקן הצריך תיקון , לייסד\nחדשות כפי צורך הזמן שמתחדש מזמן לזמן . וכדי להַוות כח שיתחשבו\nבו – צ \" ל איגוד כל הרבנים השייכים למסגרת זו , היינו לחפש און\nאריינציען זיי בהמסגרת וכו .'\nכנראה אין להועד כל ידיעות כלל מהרבנים והמוסמכים דישיבות חב \" ד\nהנמצאים באה \" ק , אף שרבים הם ( ובפרט דמרוקו ), ופשיטא שלא\nנעשה כלום לאגדם ע \" י דברים המתאימים להם – והעיקר שבמשך כל\nהשנים לא נעשה שום דבר בזה , שהפי ' בזה – קיינער האט ניט\nגעטראכט עדכ \" ז במשך כל הזמן ! אף שרואים השתדלות המפלגות עד\nכדי מס \" נ – אריינשלעפען עוד חבר אחד !\n[ ולאידך – אין רוצים כנראה , לשאול דעת מומחה בענינים שצ \" ל ע \" י\nהועד אבל אין הם \" פעולות רבניות \" כלל\nכוונתי בפרט לסידור אופן סיום והכנסת הס \" ת – שהייתה הזדמנות\nיוצאה מן הכלל ויחידה במינה לקירוב ואיחוד כל החוגים , ובאופן\nדפעולה נמשכת בכיון זה וכו ' וכו ' .]\nפשוט שאין כוונתי כלל בכתיבת הנ \" ל – לאמירת מוסר ולא שישלחו\nלכאן הצעות ותכניות וכו ' וכו ' – כי אין מנהלים מוסד מעבר לים , כ \" א\nדוקא על אתר ,"],[9200210057,"57\nמענות קודש – ה ' תשמ \" ב\nכ \" א אך ורק – שאולי ימצא סו \" ס באה \" ק מי שיש לו חוש בהנ \" ל ובעל\nיזמה וכו ' ובחב \" ד – ויתחיל בפו \" מ בהנ \" ל במעשה – שאז בודאי יצליח .\nעל מה שכתב ע \" ד תיקון תקנות בעניני שמחות נישואין , כתב :\n2 ) אין מתחילים פעילות – באיסורים ובפרט – בצמצום . . שמחת חו \" כ !\nלאחרי שהועד ( כמרע \" ה – רש \" י דברים א , ד ) יסדר כו \" כ רבני ומוסמכי\nאנ \" ש במשרות מתאימות , ופעולות בוע \" ט כיו \" ב – יתענין בנוגע לסו \" מ .\n3 אזכיר עה \" צ לכהנ \" ל .)\nמצו \" ב ( הוספה ) לצדקה באה \" ק .\nצג\nתחלת אדר ][\nמענה כללי - פרטי דימים אלו [ בין השאר – לתלמידים השלוחים לישיבת\nליובאוויטש קסבלנקה מרוקו על דו \" ח ( מהעתקה , באדיבות מערכת\nהספר \" שליחות כהלכתה :])\"\nנת ' ות \" ח .\nודבר בעתו –\nבסמיכות לראש החודש בו ליהודים היתה אורה ושמחה וששון ויקר –\nכפשוטו , וככל דחז \" ל בזה – כן תהי ' לנו .\nאזכיר עה \" צ .\nצד\nח ' אדר ][\nמענה לה \" ועד להפצת שיחות \" – על גליון מכתב \" ועד הנחות התמימים ,\"\nבהמשך להמענה שקיבלו ( לעיל מענה ע ) להעלות הצעה להו \" ל לכבוד יום\nהבהיר י \" א ניסן שמונים שנה – בו כתבו הצעה להו \" ל \" קובץ י \" א ניסן ,\"\nופירטו מה בתכניתם לכלול בו ( מצילום כתי \" ק – ס ' \" מאוצר המלך \" ח \" ב\nע ' 195 ליקוט כתי \" ק יום הבהיר י \" א ניסן ע '. 38 :)"],[9200210058,"58\nמענות קודש – ה ' תשמ \" ב\nלהו \" ל הקובץ – שמטרתו תורה\nולכן ועל הסדר :\nמהצ \" צ מיהל אור דקאפ ' פ וגם )( פא עם המזמורים כביהל אור )(\nעה \" פ ימי שנותינו גו '\" ( 6 – דלעיל )\nמאאמו \" ר על מחז \" ל בחולין\nהציונים הנ \" ל ( לדא \" ח שמבואר ענין פ ' שנים .\nהוספה תקנת הבעש \" ט דקאפ ' תהלים דשנותיו .:\nמנהגי יום הולדת\n___\nועוד ועיקר להו \" ל התניא בגודל רגיל , ועה \" ס כנדפס לאחרונה בברוקלין\n. . לאחרי הערות ותיקונים : רשימת הכתי ופאקסימילות שלהם ( כבסוף\nמהד \" ק דתניא שהדפיסו – אבל להשמיט ב ' השערים דזאלקווא\nהנדפסים ! שעורבו באמצע !). רשימת דפוסי התניא מתוקנת ומלאה\n( כולל – שנתקבלו לאחרונה כאן . רשימת ההעתקות וכו .'\nוצילום דכל השערים דכל התניא ' ת שיוכלו להשיגן בגודלן כמו שהן\nלהסתייע בס ' מונדשיין שי ' אבל אָפ טשעקין\nוהדיוק שער א ' 1 ) מכל התניא ' ת 2 ) זה שצויין בו מקום ההדפסה\nכו \" כ תניא ' ת נתקבלו לאחרונה נמצאו בספרי '\nהשערים דוילנא הראשונים הגדולים קצת מגודל תניא הרגיל יצמצמום\n– אבל יציינו הגודל\nבשני בענדליך\nצה\nועש \" ק תצוה , יו \" ד אדר ][\nמענה לר ' צבי מאיר שטיינמעץ על דו \" ח מפורט שכתב – ע \" ד סעודה שערך\nבביתו עבור צאצאי בעל התוספות יו \" ט כפי צוואתו , וע \" ד השתתפותו\nבסעודה לרגל יובל הכ \" ה לבית הכנסת \" פועלי אגודת ישראל \" בשכונת"],[9200210059,"59\nמענות קודש – ה ' תשמ \" ב\nבארא פארק . בסיום מכתבו כתב : \" ועם כ \" ק הסליחה על הלהג הרב\nשבמכתב , כוונתי לטובה \" ( תשורה זלמנוב כ \" ד סיון תשע \" א :)\nכ \" ק אדמו \" ר שליט \" א מחק את התיבות \" על הלהג הרב \", וכתב :\nהתודה על הנח \" ר שע \" י בש \" ט הנ \" ל ועם העשי '\nאזכיר על הציון\nצו\nי \" ג אדר , ערב ימי הפורים ][\nמענה להשליח ר ' יהושע זעליג הכהן ריבקין על מכתבו בו פירט את\nהקשיים שלו בעבודת השליחות ואשר חש \" ריקנות \" כו ', וכתב אשר שמא\nאינו מתאים לעבודת השליחות ( ס ' \" שליחות כהלכתה \" ע ' 829-30 :)\n!? כפשוט – להמשיך – אבל באופן דהוספה ועלי ' ובפשטות מתוך בטחון\nאמיתי שיצליח , ובמרץ ובשמחה .\n?! צריך להיות מתוך שמחה גדולה אשר זכה , ועל ידי שליחותו\nופעולותיו נתקרבו אלפים מבני ישראל לאביהם שבשמים .\nעל ידי מצות מעשיות ( נוסף על הקירוב דידיעת היהדות וכו ') מתפרסמת\nהיהדות ברבים ( באסיפות כמה כינוסים וכו ') שזהו קיום מצות קידוש\nה ' על פי ההלכה ברורה ופשוטה ובכל פעם ופעם בפני עצמו .\nוידועות תורות הבעש \" ט בכל זה ומפורסמת ( און ווען ס ' קומט צו זיך –\nצריך לעורר אַז עם מיינט מען )!\nבהבעיות וקושיים שכותב בם – הרי הם אצל כל השלוחים יותר קצת או\nפחות קצת ומהם ילמד וכן יעשה .\nאזכיר על הציון ( בכל הנ \" ל .)\nצז\nי \" ג אדר , ערב ימי הפורים ][\nמענה לא ' השלוחים שכתב שמרגיש נמיכת הרוח על שלא זכה לקבל\nמכתב מכ \" ק אדמו \" ר שליט \" א במענה על מכתביו ( תשורה חאנין כ \" ג\nאלול תש \" פ . קונטרס ועד הנחות בלה \" ק ראש השנה תשפ \" א :)"],[9200210060,"60\nמענות קודש – ה ' תשמ \" ב\nב \" ה ערב ימי הפורים\nבמענה ( ברור , כבקשתו ) על כהנ \" ל .\nמפורסם ברור שבשנים האחרונות מפני כו \" כ סבות – להקרובים שאין\nמקפידים שיוכלו להראות לאחרים מכ ' וטיטול גדול וכו ', מאשרים\nהמכ ' וכו ' ע \" י טלפון , ושאזכיר עה \" צ ות \" ח על הבשו \" ט . והכנסתיו בסוג\nזה וריבוי פעמים עניתיו באופן כזה ( ולפעמים במיוחד ע \" י הרחמ \" א\nשי )' – באם אינו שייך לסוג זה יודיעני .\n2 בחרתי בו למסור המשקה , ולהשתדל בהשלום ומודיע ששמע פי ')\nשזהו סימן . . . לגריעותא !! באם מקבל פי ' של כל שוטה וכסיל – אין\nלי עצה לזה .\n3 ) בכל עניני אנ \" ש שי ' בעירו – ענוהו וכמה פעמים וברור – שבאם יש\nחילוקי דעות צ \" ל אסיפה על אתר שלהחליט ע \" פ הרוב .\n4 ) מצב הכשרות בעיר וכיו \" ב שייך אליו בתור אחד מתושבי העיר ,\nהיר \" ש וכו ' – ובאופן כזה יפעול . באם רוצה לנהל כ \" ז – ה \" ז שייך להרב .\nאזכיר עה \" צ . וכן המכ ' ופ \" נ שהביא .\nצח\nאדר ][\nמענה כללי - פרטי דימים אלו [ בין השאר : ( 1 ) לא ' מאנ \" ש מתומכי ה \" ועד\nלהפצת שיחות \" ( מהעתקה , באדיבות ר ' שניאור זלמן יצחק יהושע שי '\nחאנין ;) ( 2 ) לר ' שלום יעקב חזן שהכניס עותק של הקובץ שחילק בעת\nחתונתו – הכולל את ההנחה דההתועדות דש \" ק , וההנחה דהיחידות\nכללית לחתנים וכל ות (\" בית משיח \" גליון 390 :])\nנת ' ות \" ח .\nודבר בעתו –\nבסמיכות לימי הפורים אשר ליהודים היתה אורה ושמחה וששון ויקר\n– כפשוטו , וככל דחז \" ל בזה – כן תהי ' לנו .\nאזכיר עה \" צ ."],[9200210061,"61\nמענות קודש – ה ' תשמ \" ב\nצט\nאדר ][\nמענה להת ' אברהם נחום גראס והת ' מרדכי צבי קראסניאנסקי שביקשו\nהסכמת וברכת כ \" ק אדמו \" ר שליט \" א לנסיעתם בשליחות המל \" ח לאיי\nהוואי עבור מבצע פורים ומבצע הרישום לס \" ת הכלליים (\" כפר חב \" ד \"\nגליון 42 :)\nויהיה בהצלחה רבה , אזכיר על הציון . לברר מקודם האפשרות להדפסת\nתניא שם ( באם לא נדפס עדיין .)\nק\nאדר ][\n\" צעטל \" בכתי \" ק שכתב כ \" ק אדמו \" ר שליט \" א למסור לועד רבני חב \" ד\nבאה \" ק בקשר לסכסוך בין שניים מעסקני חב \" ד ( מהעתקה . המענה\nמתפרסם בזה לראשונה באדיבות א ' מאנ \" ש שי ' וזכות הרבים תלוי ' בו :)\nלטלפן בשמי לוועד רבני אנ \" ש שיחיו שבארה \" ק .\nבקשתי שתיכף אחר פורים יזמינו הרב .[ ]. – .[ ]. יבררו טענותיהם\nוהחילוקי דיעות וכו ' ויורום בכתב ובפרטיות וברור בכל הנ \" ל והעתק\nלכאן ות \" ח מראש .\nקא\nכ \" ף אדר ][\nמענה לא ' על מכתבו אליו צירף טיוטת כתבה שכתב , בה כתב על דברי\nכ \" ק אדמו \" ר שליט \" א בנושא \" אתחלתא דגאולה \" ( מצילום כתי \" ק –\nתשורה לוין ג ' ניסן תשס \" ז :)\nבתמהון הכי גדול קראתי הגאַלי ' ס המצו \" ב , בם מייחס אלי דברים\nשמעולם לא אמרתי , היינו ששאלת אתחלתא דגאולה קשורה בהשאלה\nהצ \" ל ניסים בהגאולה , או שאין בין ימוה \" מ לעוה \" ז אלא שעבוד\nמלכיות ."],[9200210062,"62\nמענות קודש – ה ' תשמ \" ב\nולא עוד אלא שבדיבורי הבאתי המקור לדברַי בציון הפרק ברמב \" ם\nוההלכה בדיוק , וכו \" כ פעמים . וגם נדפס – ובאותו הפרק עצמו כתוב\nשאצ \" ל נסים בדוקא ( וא \" צ להביא מפיה \" מ .)\nמה שאמרתי : הרמב \" ם פוסק ברור סדר סיום הגלות בהל ' מלכים פי \" א\nה \" ב - ג : אין שואלים ממנו ( ממלך המשיח ) \" לא אות ולא מופת \" ( כ \" א\nשיהי ' איש \" הוגה בתורה ועוסק במצות כו ' ויכוף כל ישראל לילך בה\nכו ' וילחום מלחמות ה ' ה \" ז בחזקת שהוא משיח ( כצ \" ל – ראה דפוסי\nרמב \" ם שלא קילקלה הצנזורה ) אם עשה והצליח ונצח כל האומות\nשסביביו ובנה מקדש במקומו וקבץ נדחי ישראל ( יעוין הסדר בכ \" ז ) ה \" ז\nמשיח בודאי ואם לא הצליח כו ' בידוע שאינו ( משיח , ולא גאולה וצריך\nלחכות ) עד עת קץ \". עיי \" ש .\nישנו ענין בפ \" ע : כשיתברר שזהו ודאי משיח – שבזה איתא בהמשך\nהרמב \" ם שהבאתי ( רפי \" ב שם ): . . בימוה \" מ . . עולם כמנהגו נוהג\nוזש \" נ בישעי ' וגר זאב עם כבש כו ' משל כו ' שיהיו ישראל יושבין לבטח\nכו ' ובימוה \" מ יודע לכל לאיזה דבר הי ' משל כו .'\nוביאר הרמב \" ם עצמו – דבריו בזה ( מאמר תחה \" מ ס \" ו ): ודע . . שאנו\nאומרים שהן משל אין דברנו זה החלטי כו ' ואם הוא כפשוטו כו .'\nובזה אמרתי – שע \" פ מאמר תחה \" מ להרמב \" ם – שאין הכרח כלל לומר\nשהרמב \" ם פליג על כל אלה ששטתם שגר זאב אינו משל , ולהרבות\nמחלוקת , אלא שלדעתו – ב ' תקופות לאחרי הגאולה דמשיח ודאי וכו .'\nוג \" ז כבר נדפס .\nאבל בכל אופן – כנ \" ל – אין לזה שייכות כלל לבי ' אתחלתא דגאולה .\nקב\nכ \" א אדר ][\nמענה למערכת \" ספר הליקוטים – דא \" ח צמח צדק \" שכתבו : \" מצו \" ב\nערכים . . סיום הערכים דאות ג '\" ( מצילום כתי \" ק – \" לקט מענות קודש\nבקשר להדפסת ספר הליקוטים דא \" ח צמח צדק \" ע ' 45 :)\nכ \" ק אדמו \" ר שליט \" א סימן קו תחת התיבות \" סיום הערכים דאות ג ,\"'\nוכתב :\nלזרז ההול וכו ' בפו \" מ"],[9200210063,"63\nמענות קודש – ה ' תשמ \" ב\nקג\nכ \" א אדר ][\nמענה לר ' יצחק גאנזבורג על מכתבו בקשר להמפתחות למאמרי אדמו \" ר\nהאמצעי שבעריכתו ( מהעתקה . המענה מתפרסם בזה לראשונה באדיבות\nהת ' שלום דובער שי ' הרשקופ וזכות הרבים תלוי ' בו :)\nבודאי ירעיש עולמות שיהיה מזומן להשתמש בו בפועל ממש לא יאוחר\nמשבת הגדול\nקד\nכ \" ו אדר ][\nמענה להחתן הת ' אברהם אבא בלאזענשטיין וב \" ג על בקשת הסכמה\nוברכה לשידוך ( תשורה בלאזענשטיין ה ' אלול תשס \" ט :)\nבטח החליטו שניהם ליסד ביתם על יסודי התורה והמצוה\nויהא השידוך בשטומו \" צ\nאעה \" צ\nקה\nכ \" ח אדר ][\nמענה להרב דוד ראסקין שכתב דו \" ח מאסיפת הנהלת ישיבת תו \" ת\nהמרכזית בקשר לסיום ס \" ת הכללי השני שלהם שיתקיים – ע \" פ המענה\nשקיבלו ( לעיל מענה מד ) – ביום ג ' ל \" ג בעומר . במכתבו כתב :\n\" סיום הס \" ת הא ' היתה בהאטעל בנ . י . הי ' סברות בנוגע הסיום של ס \" ת\nהב ': א ) לעשות בהבנין דתו \" ת באשען פארקוויי , ב ) עוה \" פ בהאטל , ג ) ב -\n770 א . פ .\nהצעתינו לאחר ההתדברות עם כמה עסקנים לסדר הסיום בהבנין דתו \" ת\nבאשען פרקוויי כי כן הי ' גם ההוראה על הס \" ת הא ' \" בהאטל גדול או\nבבנין תו \" ת וכו '\" [ לעיל מענה ס ד ], כי לסדר בהאטל יהי ' קשה יותר בפעם\nהב ', ובפרט שאז הי ' ביום א ' בשבוע .\nוהננו שואלים אם נכון , ובאם נכון מבקשים ברכה להצלחה .\""],[9200210064,"64\nמענות קודש – ה ' תשמ \" ב\nמענה כ \" ק אדמו \" ר שליט \" א ( תדפיס מספר \" ועבדי דוד \" – ס \" ת הכלליים\nשע \" י תו \" ת המרכזית – ע ' 56 :)\n[1 ] סימן בעיגול ובחץ את התיבות \" לסדר הסיום בהבנין דתו \" ת באשען\nפרקוויי .\"\n[2 מחק את התיבות \" והננו שואלים אם \" וסימן בחץ תיבת \" נכון .\"]\n[3 על התיבות : \" ובאם נכון מבקשים ברכה להצלחה \", כתב :]\nלהצלחה ][ רבה\nק ו\nחורף ][\nמענה לבני משפחת גרינגלאס שהכניסו את נוסח המצבה של מרת אסתר\nגרינגלאס ע \" ה ( מצילום כתי \" ק ; ס ' \" ליקוטי סיפורי התועדויות \" ע ' 59 :)\nעל מה שנכתב ב ה נוסח בין השאר : \" אשת יבל \" ח ר ' מנחם זאב הלוי שי '\nגרינגלאס \", כתב :\nהרה \" ח משפיע דתו \" ת התמים\nהנ \" ל כמובן באם הח \" ק של בית החיים זה יסכים\nק ז\nחורף ][\nמענה להמתעסקים בהכנת ס ' המאמרים תרס \" ה היו \" ל ע \" י מערכת\nאוצר החסידים \"\" – שהכניסו את דף - השער דהספר , ושאלו האם לכלול\nבתוארי אדמו \" ר מהרש \" ב את התואר \" הוד \", בהמשך להמענות\nשנתקבלו ( לעיל מענות נה , נו ) בנוגע לציון תואר זה ב \" שלשלת היחס \"\nשבריש ס ' היום יום ( מצילום כתי \" ק – תשורה איידעלמאן י \" ג תמוז\nתשנ \" ט :)\nהרי נשמט ע \" ע ( לבד בבודדים .)"],[9200210065,"65\nמענות קודש – ה ' תשמ \" ב\nקח\nחורף ][\nמענה לר ' שלום דובער לוין שכתב : \" מצו \" ב עלי ההגהה של ה \" מבוא \" לס '\nאגרות - קודש אדמו \" ר מוהרש \" ב נ \" ע . הספר עצמו כבר סודר , כולו ,\nבדפוס , והתחילו בסידור העמודים \" ( מצילום כתי \" ק – \" תחיינו \" גליון 8\nע ' 60 קובץ \" עבודת הקודש אצל הרבי \" ע ' מב :).\nנת ות \" ח על הבשו \" ט [ הספר עצמו כבר סודר , כולו , בדפוס , והתחילו\nבסידור העמודים ]\nיש שעורר – שנכללו מכ ' פרטיים שאינם מתאימים לפרסום כלל\nוכדאי שיעבור עליהם עוה \" פ ובאם ימצא מסוג הנ \" ל ישמיטם ובהערה\nשמפני סיבה נשמט וא \" צ לשנות כל המספרים ולעכב עי \" ז ההו \" ל\nקט\nחורף ][\nמענה לר ' שלום דובער לוין על מכתבו ( ללא תאריך בראשו ) – בהמשך\nלהמענה שקיבל ע \" ד השמטת מכתבים שאינם מתאימים לפרסום\nמאגרות - קודש אדמו \" ר מהרש \" ב , בו כתב : \" מצו \" ב צילום הקטעים\nהמסומנים , שיושמטו מהדפוס , להיותם ענינים פרטיים וכיו \" ב \" ( קובץ\nעבודת הקודש אצל הרבי \" ע ' מב )\" :\nתאריך מצב ההתקדמות בהנ \" ל ..\nק י\nחורף ][\nמענה לא ' שכתב ע \" ד מצב בריאותו ( ס ' \" היכל מנחם \" ח \" א ע ' קצב - ג :)\nיסיח דעת בהחלט מכהנ \" ל לא יחשוב כלל וכלל עדכ \" ז , וכשנופלת\nמחשבה עד \" ז – יתחיל ללמוד באיזה ענין שיהי ' בתורה , ומח ' דוחה\nמח ', ואין כל סיבה כלל ליאוש כפשוט .\nימלא הוראות הרופא שי '\nאזכיר עה \" צ ."],[9200210066,"66\nמענות קודש – ה ' תשמ \" ב\nקי א\nחורף ][\nמענה להנהלת בית הספר \" בית רבקה \" בכפר חב \" ד ב ' על דו \" ח מפעילות\nהרישום לס \" ת הכללי שלהם ( ס ' \" מקדש מלך \" ח \" א ע ' 119 . ס ' אלבום\nאות בספר תורה \" ע '\" 136 :)\nות \" ח ת \" ח על הבשו \" ט ובודאי כשיש מאתיים רוצים ארבע וכו .'\nקי ב\nחורף ][\nמענה לילד מחיפה אה \" ק שביקש ברכת כ \" ק אדמו \" ר שליט \" א ( ס '\nמקדש מלך \" ח \" א ע '\" 119 ס ' אלבום \" אות בספר תורה \" ע '. 114 :)\nאזכיר עה \" צ . האם נרשם לספר תורה ?\nקי ג\nחורף ][\nמענה למשפחה שביקשו ברכת כ \" ק אדמו \" ר שליט \" א ( ס ' \" מקדש מלך \"\nח \" א ע ' 119 ס ' אלבום \" אות בספר תורה \" ע '. 114 :)\nאזעה \" צ . האם נרשם לס \" ת ?\nקי ד\nחורף ][\nמענה לא ' שביקש ברכת כ \" ק אדמו \" ר שליט \" א ( ס ' \" מקדש מלך \" ח \" א ע '\n119 ס ' אלבום \" אות בספר תורה \" ע '. 114 :)\nכעצת רופא ידיד , בדיקת התפילין והמזוזות , ס \" ת ? אזעה \" צ ."],[9200210067,"67\nמענות קודש – ה ' תשמ \" ב\nק טו\nחורף ][\nמענה להנהלת בית הספר \" בית רבקה \" בשכונת קראונהייטס שכתבו ע \" ד\nתכניתם לערוך את סיום ס \" ת הכללי שלהם ביום הבהיר י \" א ניסן\nשמונים שנה ( ס ' אלבום \" אות בספר תורה \" ע ' 132 . תשורה ליפסקער\nכ \" ט אד \" ר תשע \" ט :)\nאין מערבין שמחה בשמחה , וכדאי הוא ס \" ת לעצמו .\nקט ז\nחורף ][\nמענה לא ' מאנ \" ש שכתב ע \" ד רצונו לקנות מכונית חדשה ( ס ' \" מקדש\nמלך \" ח \" ג ע ' סז :)\nלמה דוקא חדש ולא משומש שבמצב טוב שהחילוק במחיר גדול\nכמפורסם !?\nקי ז\nחורף ][\nמענה לר ' שלום דובער לוין שכתב ע \" ד בקשה שנתקבלה לקבל צילום\nמכתב - יד הנמצא בספריית כ \" ק אדמו \" ר שליט \" א בתוך אוסף הכת \" י\nשהגיעו ממרוקו ( קובץ \" עבודת הקודש אצל הרבי \" ע ' קיד :)\nעדיין אין החלטה ב \" קהת \" בנוגע לכת \" י שבאו לעובדי חב \" ד במרוקו\nלרגל עבודתם שם ( מה יעשה בהם וכו '). לכן אין לפרסם אודותם כלל\nעכ \" פ מכאן ולהבא .)(\nקי ח\n[ חורף ( 1 ])\nמענה להרב שמואל פסח באגאמילסקי על מכתבו – בקשר להמבואר\nבלקו \" ש עקב תשמ \" א ( חכ \" ד ע ' 67 ) הערה 1 בקשר ל \" סדר ברכת הנהנין :\"\nכן הוא בדפוסים שראיתי ( ולא \" ברכות \"\" – ל ' רבים .) – ואולי אגב"],[9200210068,"68\nמענות קודש – ה ' תשמ \" ב\nדברכת המזון , שהוא מ \" ע ( וברכה ) אחת מה \" ת \". והעיר הנ \" ל על זה כו \" כ\nהערות , והראשון שבהם : בנוגע למש \" כ \" אגב דברכת המזון \", לכאורה\nהרי מבואר בכו \" כ שיחות אשר שֵם כולל בתוכו את תוכן הענין , ועפ \" ז\nלמה נקראו ההלכות אגב דברכת המזון שהוא פרט אחד מברכות הנהנין ,\nולא \" סדר בר כות הנהנין \" כ מתאים לתוכן ההלכות ( קובץ הערות\nהתמימים ואנ \" ש 770 י \" א ניסן תשמ \" ב ( גליון קלו :))\nראיתי בהתחלתו עכ \" פ ולהעיר הענין \" אגב \" – הובא בכ \" מ וגם להלכה\nבפו \" מ . עדיפא הו \" ל להקשות : ע \" פ תורת הבעש \" ט איך אפשרי שם\nלהכשר מצות וכיו \" ב . בסדר ברה \" נ גופא מדובר בברמ \" ז ובראשו וכו .'\nקי ט\n[ חורף ( 2 ])\nמענה להרב שמואל פסח באגאמילסקי על מכתבו – בהמשך להמענה\nשקיבל – בו ציין שלכאורה לא הביא אדה \" ז ב \" סדר ברכת הנהנין \"\nהלכות שכתב בשולחן ערוך שלו \" הלכות ברכת המזון \". והמדובר\nבהתחלת סדר ברכת הנהנין אודות ברכת המזון ( כבהמענה שקיבל ,)\nהביאו אדה \" ז בשו \" ע \" הלכות בציעת ה פת \". ועד \" ז בשאר המקומות\nשמוזכר ברכת המזון בסדר ברכת הנהנין , שהובאו בשו \" ע אדה \" ז , אבל\nלא בהלכות ברכת המזון ( קובץ הערות התמימים ואנ \" ש 770 י \" א ניסן\nתשמ \" ב ( גליון קלו :))\nוהבי ' פשוט – הל ' הנ \" ל שייכות לב ' מקומות ( או ליותר ). ומובן שצ \" ל\nבפעם הא ' שצריך לדעתם . ובמילא א \" צ להַכפיל לאח \" ז . משא \" כ בסי '\nשאין שם \" הלכות בציעת הפת \" וכיו \" ב .\nקכ\nחורף ][\nמענה לא ' ששאל האם נכונה מחשבתו לבוא לבקר בחודש תשרי הבע \" ל\nאצל כ \" ק אדמו \" ר שליט \" א (\" התקשרות \" גליון תיב :)\nמתוך שמחה וטוב לבב , אזכיר על הציון ."],[9200210069,"69\nמענות קודש – ה ' תשמ \" ב\nקכ א\nחורף ][\nמענה לר ' יעקב יהודה העכט על מכתבו בקשר למבצע ס \" ת הכלליים\nמהעתקה . המענה מתפרסם בזה לראשונה באדיבות א ' מאנ \" ש שי '(\nוזכות הרבים תלוי ' בו :)\nכתיבת ס \" ת הכונה להדגיש האיחוד ולא שכל או \" א יכתוב ס \" ת בעצמו !\nלצרף תלמידות מחנ ה אמונה , ותלמידות דשל \" ה , ומכון חנה ככל העולם\nלס \" ת בית רבקה\nותלמידי של \" ה לתו \" ת\nקכ ב\nר \" ח ניסן ][\nמענה להרב שאול ליברמן על מכתבו ( להמזכיר רחי \" ק ), בו כתב : \" אני\nמתכונן לעלות לאה \" ק בעוד כמה ימים , והנני מצרף כאן המחאה ע \" ס\nאלף דוללר למרכז לענייני חינוך . ובזה הנני מביע את ברכתי להרבי\nשליט \" א שיתברך בברכה שנתברך בה ר ' חגיי \" ( מצילום כתי \" ק – תשורה\nניו כ \" ה אד \" ש ת שס \" ח . ליקוט כתי \" ק יום הבהיר י \" א ניסן ע ' 15 :)\n[1 ] סימן בעיגול את מה שכתב : \" אני מתכונן לעלות לאה \" ק בעוד כמה\nימים \", וכתב :\nויה \" ר שיקויים עי \" ז – כתרי מינן\n[2 סימן בעיגול את מה שכתב : \" ובזה הנני מביע את ברכתי \", וכתב :]\nוכבר מילתי ' אמורה כו '\n[3 ] על התיבות : \" שיתברך בברכה שנתברך בה ר ' חגיי \" [ אשר בזכות\nהתעסקותו בקבורת רב הונא בהיותו בגיל שמונים , נכפלו שניו וחי\nשמונים שנה נוספות ] – כתב :\nאבל ע \" י התעסקות בחיים כפשוטו – הדבקים בה \" א חיים גו ' –\nולא יוצרך כצדיקי כד דמַך שבמיתתן נקראו חיים כעובדא דהנ \" ל )( ( 3 )\nירוש ' כלאים ט , ג . כתובות פי \" ב , ג ."],[9200210070,"70\nמענות קודש – ה ' תשמ \" ב\nקכ ג\nתחלת ניסן ][\nמענה כללי - פרטי דימים אלו [ בין השאר : ( 1 ) להנהלת \" צעירי אגודת\nחב \" ד המרכזית \" בקשר למכתב התעוררות , לקראת יום הבהיר י \" א ניסן\nשמונים שנה , ע \" ד קיום הוראות כ \" ק אדמו \" ר שליט \" א ( תדפיס מספר\nועבדי דוד \"\" – ס \" ת הכלליים שע \" י תו \" ת המרכזית – ע ' 57 ;) ( 2 להת ')\nאברהם לייב שוחא ט ראש ישיבת ליובאוויטש קסבלנקה מרוקו על דו \" ח\nמהעתקה , באדיבות מערכת הספר \" שליחות כהלכתה ;)\"( ( 3 ) לתלמידים\nהשלוחים לישיבת ליובאוויטש קסבלנקה מרוקו על דו \" ח ( מהעתקה ,\nבאדיבות מערכת הספר \" שליחות כהלכתה :])\"\nנת ' ות \" ח\nודבר בעתו –\nבסמיכות לשני בניסן\nחודש הגאולה\nאזכיר עה \" צ\nקכ ד\nח ' ניסן ][\nמענה לר ' הלל דוד קרינסקי על מכתבו בקשר לשידור התועדות יום\nהבהיר י \" א ניסן שמונים שנה ב \" סאטעלייט \" ( מצילום כתי \" ק – תשורה\nקרינסקי ט \" ו אלול תש \" ע :)\nויה \" ר שיהא כהנ \" ל בהצלחה ושיפעול בפנימיות וכו '"],[9200210071,"71\nמענות קודש – ה ' תשמ \" ב\nקכ ה\nלאחר י \" ג ניסן ][\nמענה ל \" ועד הנחות התמימים \" על שאלתם במאמר ד \" ה הא לחמא עניא\nדאור לי \" ג ניסן :\n\" בהמאמר די \" ג ניסן נתבאר שג ' האהבות – בכל לבבך ובכל נפשך ובכל\nמאדך – הם מן הקל אל הכבד . בתחלה בכל נפשך , אח \" כ בכל לבבך ,\nואח \" כ ובכל מאדך . ונתבאר בזה , דענין בכל נפשך הוא בכל כחות הנפש ,\nאבל אעפ \" כ אפשר שזהו רק מצד היצ \" ט אבל היצה \" ר רוצה להיפך ,\nוכמבואר בתניא ( פ \" ט ) שכל אחד משני היצרים ( שתי הנפשות ) רוצה\nלמשול ולשלוט על כל כחות הנפש . וזהו העילוי דבכל לבבך בשני יצריך ,\nשגם היצה \" ר נהפך לקדושה , ועד שנעשה חד עם היצ \" ט ( שלכן שניהם הם\nבאותה התיבה , לבבך ) אתהפכא חשוכא לנהורא ומרירו למיתקא .\nאיך יתאים זה עם הסדר שבפסוק . וגם בחסידות בכ \" מ מבואר כפי הסדר\nשבפסוק , וגם בד \" ה הא לחמא עניא באוה \" ת ( שעליו מיוסד המאמר ) ע '\nתנד : ובכל נפשך הוא אהבה גבוה יותר .\"\nמענה כ \" ק אדמו \" ר שליט \" א ( מצילום כתי \" ק – ריש סה \" מ תשמ \" ב\nברוקלין , תשס \" ב :))(\nאא \" פ ש יתאים זה עם הסדר שבפסוק ][ שה \" ז הפכו .\nוהנ \" ל נאמר \" דלכאורה צ \" ל [ בתחלה בכל נפשך , אח \" כ בכל לבבך , ואח \" כ\nובכל מאדך כו ]' וההסברה כו .'.\nבתקוה שיתרצו ויסבירו ולא רק שיודיעו שבכתוב הסדר כו '\n___\nההסברה דלַמרות פשטות הל ' בד \" ה הא לחמא ובכ \" מ דבכל לבבך היינו\nבכל אדם אתהפכא ( כדלעת \" ל ) דיצה \" ר ( וכנ \" ל ששניהם בתיבה א ) –\nהכוונה שבאותה שעה מקיים ואהבת גם בהתלהבות דנפה \" ב וגופו\nמשכא דחויא )( ההתפשטות דיצה \" ר , אבל מהוע \" צ דיצה \" ר בתקפו\n( אלא שישן ) כו ' ( עיין תניא פי \" ג ) ולכן\nועפ \" ז תבטל הקלאץ קשיא דהבינוני ( מדת כל אדם ) – אינו שייך\nלעבודת בכל לבבך ! ועוד שרק דרגת אברהם ( משא \" כ דוד – שהרגו )\nשמצאת לבבו נאמן לפניך .\nוהבי ' בובכל לבבך ע \" ד בי ' עבודת אמת בפי \" ג שם ."],[9200210072,"72\nמענות קודש – ה ' תשמ \" ב\nקכ ו\nניסן ][\nמענה כללי - פרטי דימים אלו [ בין השאר – למערכת הערות התמימים\nואנ \" ש מאריסטאון שהכניסו את הקובץ דיום הבהיר י \" א ניסן שמונים\nשנה , וכן כרך הכולל את הקובצים שהו \" ל במשך חורף תשמ \" ב ( קובץ\nהערות התמימים ואנ \" ש מאריסטאון ש \" פ תזו \" מ תשמ \" ב ( גליון רנט :]))\nנת ' ות \" ח .\nודבר בעתו\nביום י \" א – נשיא לבני אשר – בניסן\nחודש הגאולה .\nבמוצש \" ק פ ' צו וזירוז ( ונתינת כח )\nמיד ולדורות .\nאזכיר עה \" צ\nקכ ז\nניסן ][\nמענה לה \" ועד להפצת שיחות \" שכתבו : \" מצו \" ב הספר לקוטי שיחות ספר\nבמדבר [ כרך יח ]. קבלנו ז \" ע יותר מ 500 ספרים . ומצו \" ב גם רשימת כל\nהמנדבים את הספר הנ \" ל . . ומבקשים ברכת כ \" ק אדמו \" ר שליט \" א\nלהצלחה רבה ומופלגה בגו \" ר גם יחד \" ( מצילום כתי \" ק – בית משיח \"\"\nגליון 269 :)\nכהנ \" ל נת ' ות \" ח ת \" ח . ויה \" ר שיגדילו תורה ויאדירו ובכל הפי '\nאזכיר עה \" צ"],[9200210073,"73\nמענות קודש – ה ' תשמ \" ב\nקכ ח\nניסן ][\nמענה לא ' על מכתבו בו שאלות בקשר לשיעורי חת \" ת ( ס ' \" היכל מנחם \"\nח \" ב ע ' לז - ח :)\n[1 ] במכתבו שאל האם יוצאים ידי חובת לימוד חומש דחת \" ת ( ביום\nועש \" ק או ש \" ק ) באמירת הפרשה שנים מקרא ואחד תרגום .\nמענה כ \" ק אדמו \" ר שליט \" א :\nלא .\n[2 ] במכתבו שאל האם אמירת פרק תהלים דמנין השנים עולה לתהלים\nדחת \" ת .\nמענה כ \" ק אדמו \" ר שליט \" א :\nלא .\n[3 ] במכתבו שאל האם יוצאים ידי חובת לימוד שיעורי חת \" ת בלימודם\nבליל היום שאליו שייכים .\nמענה כ \" ק אדמו \" ר שליט \" א :\nלא שמעתי בזה .\nקכ ט\nניסן ][\nמענה להרב מנחם מענדל טאוב האדמו \" ר דקאליב על איחוליו לרגל יום\nהבהיר י \" א ניסן שמונים שנה ( ס ' \" ימי תמימים \" ח \" ח ע ' 135 :)\nת \" ח ת \" ח על הברכות ומלתי אמורה בדברי חז \" ל שהבטיחו שכל המברך\nמתברך מהקב \" ה שתוספתו מרובה על העיקר .\nבברכת חג הפסח וכו .'"],[9200210074,"74\nמענות קודש – ה ' תשמ \" ב\nקל\nניסן ][\nמענה לר ' יעקב יהודה העכט שכתב שקיבל הזמנה להשתתף באסיפה\nב \" בית הלבן \" בוואשינגטאן עם יועצי נשיא ארצה \" ב אודות תכניות\nשונות הנעשים ע \" י ארגונים שונים , והאירוע יתקיים בכ \" ף ניסן הבעל \" ט\n( מהעתקה . המענה מתפרסם בזה לראשונה באדיבות מערכת הספר\n\" שליחות כהלכתה \" וזכות הרב ים תלוי ' בהם :)\nגלאטסטער אופן – לא להשתתף כלל , והרי זהו ד ' דחוהמ \" פ , ערב שביעי\nשל פסח – ושם עושים . . סעודה .\nקל א\nניסן ][\nממענות לר ' יעקב יהודה העכט בקשר למוסד \" מכון חנה \" שכ \" ק אדמו \" ר\nשליט \" א הסיר ממנו את השם בעקבות מעשה שהי ' ( מהעתקה . מתפרסם\nבזה לראשונה באדיבות א ' מאנ \" ש שי ' וזכות הרבים תלוי ' בו :)\n[1 ] . . בטח יתקבל אצלו ששם האם יקר אצלי כשם תו \" ת אצל הנהלתה ,\nואולי יותר קצת )( . .\n[2 ] . . יכול לענותם – איפו הי ' וכל שפיץ המקושרים , כביכול אלי , כשלא\nהי ' להתלמידות תחי ' מה לאכול במשך חדשים רבים ? בכלל איני ביישן\nויכול לענות בשמי . .\n[ וראה ליקוט מענות קודש תשמ \" ה מענה יא – שכ \" ק אדמו \" ר שליט \" א\nהחזיר את השם בוא \" ו תשרי תשמ \" ה .]\nקל ב\nכ \" ג ניסן , אסרו חג הפסח ][\nמענה להת ' אברהם קנלסקי שכתב – בהמשך לזה שבעת חלוקת \" כוס\nשל ברכה \" מוצאי אחש \" פ נתן לו כ \" ק אדמו \" ר שליט \" א קנקן יין – שהוא\nסך - הכל בחור הנמצא כאן ב - 770 , ואינו יודע מה לעשות עם הבקבוק\nשקיבל ( יומן ר ' אהרן שי ' קורנט . והעתקה , באדיבות ר ' שניאור זלמן שי '\nליבעראוו :)"],[9200210075,"75\nמענות קודש – ה ' תשמ \" ב\nיעורר חוג מתמידים במיוחד מבין ה בחור ][ ים [ ה נמצא ] ים [ כאן ב 770 ]\n[ וראה לקמן מענות : קל ד , קמ ה , קמ ו , קנ ה .]\nקל ג\nכ \" ו ניסן ][\nמענה לר ' ישראל ברוך בוטמאן ששאל האם להתעניין בהצעה לעבור\nלנהרי ' לשם הפעלת בית חב \" ד , או לחפש עיר אחרת לשליחות או משרה\nבא ' המוסדות הקיימים כבר במרכז הארץ . כמו \" כ שאל האם בינתיים\nלהתעניין בקניית דירה במרכז הארץ או בכפר חב \" ד ( מהעתקת המזכיר .\nהמענה מתפרסם בזה לרא שונה באדיבות הת ' חיים עוזר שי ' בוטמאן\nוזכות הרבים תלוי ' בו :)\nבכ \" ז ( כולל [ הצעתינו לעבור לנהריה לשם הפעלת בית חב \" ד ] ) כעצת\nידידים מבינים באה \" ק .\nאזכיר עה \" צ\nקל ד\nשלהי ניסן ][\nמענה כללי - פרטי דימים אלו [ בין השאר – להת ' אברהם קנלסקי על דו \" ח\nמחוג מתמידים שאירגן ע \" פ הוראת כ \" ק אדמו \" ר שליט \" א ( לעיל מענה\nקל ב ) שלמדו יחדיו את ההנחה דהתועדות אחש \" פ , וכן דאג שיו \" ל הנחה\nפרטית באידיש מההתועדויות ( יומן ר ' אהרן שי ' קורנט :])\nנת ' ות \" ח ודבר בעתו – בסמיכות לחה \" פ זמן חרותינו אזכיר עה \" צ .\nקל ה\nשלהי ניסן ][\nמענה לאנ \" ש דארגנטינא שכתבו ע \" ד המצב במדינתם לאור המלחמה עם\nאנגליא ( יומן ר ' מיכאל אהרן שי ' זליגסון :)\nיוסיפו בקיום התוהמ \" צ ובטחון בה ' שזהו ג \" כ א ' מהמצות אזכיר עה \" צ ."],[9200210076,"76\nמענות קודש – ה ' תשמ \" ב\nקל ו\nתחלת אייר ][\nמענה כללי - פרטי דימים אלו ( יומן ר ' מיכאל אהרן שי ' זליגסון :)\nנת ' ות \" ח ודבר בעתו בסמיכות לב ' אייר – מלכתחילה אריבער ( וראה\nתו \" א ס \" פ נח ) אזכיר עה \" צ .\nקל ז\nלאחר ש \" פ תזו \" מ , בדר \" ח אייר ][\nמענה ל \" ועד הנחות התמימים \" על שאלתם בה \" הדרן \" על ס ' התניא\nשנאמר בהתועדות ש \" פ תזו \" מ ( בקשר לסיום לימוד ס ' התניא בשיעור\nהשבועי על גלי הרדיא :)\nבההדרן על התניא נתבאר בענין מה שמסיים \" כי זה לעומת זה כו \"'\"\nשהפנימיות ( דיבור ) והחיצוניות ( עשי ') הם \" זה לעומת זה ]\"[ – שהחידוש\nבזה ( על ענין \" שנשתלשלו מהן \") הוא , שהגשמי ( עשי ') והרוחני ( דיבור )\nשניהם שוים – זה לעומת זה . ( משא \" כ ענין \" נשתלשלו מהן \" הוא\nשבתחילה הוא הרוחני וממנו נשתלשל אח \" כ הגשמי , היינו שהעיקר הוא\nהרוחני ). ובתיבת \" כו '\" מרמז , דלא רק שהגשמי הוא בשוה להרוחני אלא\nיתירה מזו שיש מעלה בהגשמי על הרוחני , שלכן לע \" ל תהי ' הנשמה\nניזונת מהגוף .\nלא תפסנו : הרי החידוש שבתניא כאן הוא לכאורה ענין הפנימיות , שצ \" ל\nשביתה גם מדיבורים גשמיים , \" שלא לשוח כו '\". ועפ \" ז צריך לומר\nלכאורה שהטעם \" כי זה לעומת זה כו '\" הוא ביאור וטעם על ענין\nהפנימיות , דיבור ( רוחני ). וזהו החידוש במשנ \" ת בהשיחה שכוונת אדה \" ז\nכאן היא להדגיש שהגשמי שוה להרוחני ( ולא רק שנשתלשל ממנו ) וגם\nנעלה מהרוחני ?\nב ) איזה אי הבנה יש בהענין דפנימיות וחיצוניות שבכדי לתרץ זה צריך\nלבאר שהם \" זה לעומת זה \", ועד שצריך לטעם ( על הענין דפנימיות\nוחיצוניות ) – \" כי .\"?\"\nמענה כ \" ק אדמו \" ר שליט \" א ( מצילום כתי \" ק – תשורה פולטורק ג ' כסלו\nתשס \" ה :)"],[9200210077,"77\nמענות קודש – ה ' תשמ \" ב\n[1 מחק את התיבות : \" הרי . . לכאורה . . צריך לומר לכאורה ש \", וכתב :]\n[ החידוש שבתניא כאן הוא ענין הפנימיות , שצ \" ל שביתה גם מדיבורים\nגשמיים , \" שלא לשוח כו '\". ועפ \" ז הטעם \" כי זה לעומת זה כו '\" הוא\nביאור וטעם על ענין הפנימיות , דיבור ( רוחני ]) ופשוט . וא \" צ לביאור\nבהתועדות . – אלא שעפ \" ז קשה להיפך : החיצוניות דוקא בסקילה וכו '\n[2 מחק תיבת \" וזהו \", וכתב :]\nו [ החידוש במשנ \" ת בהשיחה שכוונת אדה \" ז כאן היא להדגיש שהגשמי\nשוה להרוחני ( ולא רק שנשתלשל ממנו ) וגם נעלה מהרוחני ]\n[3 מחק את התיבות : \" איזה אי הבנה . . וחיצוניות . . לתרץ \", וכתב :]\nחלישות יש בהענין ][ דשמור דפנימיות ][ דאינו בסקילה וכו )'( שבכדי ][\nלחזק [ זה צריך לבאר שהם \" זה לעומת זה ] ועוד יותר כו ' \" [ ועד שצריך\nלטעם על הענין דפנימיות וחיצוניות )( – \" כי ]\"\nומהי ההוספה : 1 ששבת כו ,') 2 \" שנבראו בהם כו \"')\n[4 על כללות המכתב , כתב :]\nכדרכם – אין איש שם לב להקלאץ קשיא !\nאיסור \" שיחה בטלה \" מפורש בשו \" ע אדה \" ז בטעמו שנאמר ומדבר\nדבר ! ואפילו לא נרמז כאן ! וכשיתורץ כאן – קשה בשו \" ע . וחוזר חלילה .\nקל ח\nג ' אייר ][\nמענה לא ' מעסקני חב \" ד שכתב : \" בהתאם להסיום היום של המחזור\nהראשון של לימוד התניא ברדיו באידיש הצעתי היא לשדר שידור שבועי\nשל 15 דקות – מטעם איגוד צאצאי כ \" ק אדמו \" ר הזקן נבג \" מ – גם\nבאנגלית . ואני מקבל על עצמי לסדר בעזהשי \" ת כראוי ההכנה , הלימוד\nוההוצאות . אני מבין ש צריך לזה הערנסטקייט והדייקנות המתאימה רק\nשזה יהי ' יותר קל כעת שישנם השיעורים המוגהים באידיש , וגם יצאו\nויצאו עוד בעזהשי \" ת ) בדפוס וגם ישנם תרגומים רשמיים ( והערות )(\nבאנגלית \" ( ס ' \" שליחות כהלכתה \" ע ' 589 . תשורה רובין ט \" ו סיון\nתשס \" ד . והעתקה , באדיבות א ' מאנ \" ש שי )' :"],[9200210078,"78\nמענות קודש – ה ' תשמ \" ב\nרק באם יהיו הערנסטקייט והדייקנות המתאימה ][ ואחד ( עכ \" פ ) מזקני\nחב \" ד יקח ע \" ע האחריות\nאזכיר עה \" צ\n[ וראה לקמן מענות : קל ח , ק מא , ק מב , קמ ד , ק נב , קנ ו , קנ ז , ק פא .]\nקל ט\nג ' אייר ][\nמענה לר ' שמואל פרומר שביקש הסכמת וברכת כ \" ק אדמו \" ר שליט \" א\nלהכנסת \" מחשב \" למשרדו , דבר שיועיל לעבודתו ( מהעתקה . המענה\nמתפרסם בזה לראשונה באדיבות ר ' אסף חנוך שי ' פרומר וזכות הרבים\nתלוי ' בו :)\nהסכמה וברכה\nאזכיר על הציון\nקמ\nאור לה ' אייר ][\nמענה לאחת מנשות אנ \" ש שכתבה שנכנסת בימים אלו לחודש התשיעי\nלהריונה , וביקשה ברכת כ \" ק אדמו \" ר שליט \" א שיהי ' הכל בהצלחה\nוכשורה ( מהעתקה . המענה מתפרסם בזה לראשונה באדיבות משפחת\nהנמענת וזכות הרבים תלוי ' בהם :)\nאזכיר עה \" צ ותבש \" ט\nקמא\nה ' אייר ][\nמענה לא ' מעסקני חב \" ד על מכתבו בקשר לתכנית שידור שיעור בס '\nהתניא באנגלית , בו כתב : \" בהתאם למענה כ \" ק אדמו \" ר שליט \" א\nשזכיתי לקבל אתמול [ לעיל מענה קל ח ] התקשרתי אתמול עם הרב . .\nוקבענו שאבוא לביתו בעזהש \" י מחר ביום ד ' . .\" ( מהעתקה . המענה\nמתפרסם בזה לראשונה באדיבות א ' מאנ \" ש שי ' וזכות הרבים תלוי ' בו :)\nאזכיר עה \" צ"],[9200210079,"79\nמענות קודש – ה ' תשמ \" ב\nקמ ב\nו ' אייר ][\nמענה לא ' מעסקני חב \" ד על מכתבו בקשר לתכנית שידור שיעור בס '\nהתניא , בו כתב :\n\" אחרי שזכיתי לקבל מענה הראשון של כ \" ק אדמו \" ר שליט \" א [ לעיל\nמענה קל ח ] בקרתי את הרב . . בביתו ביום ד ' בערב והראתי לו המכתב\nוהמענה שהואיל כ \" ק אדמו \" ר שליט \" א לענות . אחרי שזכיתי לקבל מענה\nהשני של כ \" ק אדמו \" ר שליט \" א [ לעיל מענה ק מא ] בקרתיו שוב והראתי\nלו המכתב והמענה .\nהרב . . קרא הכל בכובד ראש ובתשומת לב ואמר שרואה מזה אז דער\nרבי שליט \" א האלט פון דעם , און אז מיר גייען אויף דעם ריכטיגן וועג . .\nבנוגע לה \" אחריות \" שכ \" ק אדמו \" ר שליט \" א דרש , הצעתי לו . .\nשאלת הרב . . כעת היא אם במילוי ג ' תנאים הנ \" ל מספיק ה \" אחריות .\"\nואם הי ' הרב . . יודע שבמילוי ג ' תנאים הנ \" ל מספיק , ומכוונים למה\nשכ \" ק אדמו \" ר שליט \" א דורש \" אחריות \" הי ' ניגש לענין בטוב לבב .\"\nמענה כ \" ק אדמו \" ר שליט \" א ( ס ' \" שליחות כהלכתה \" ע ' 589 . תשורה\nרובין ט \" ו סיון תשס \" ד . והעתקה , באדיבות א ' מאנ \" ש שי :)'\nסימן בעיגול את מה שכתב : \" שאלת הרב . . היא כו '\", וכתב :\nזוהי פעם הא ' ששואל לא בעצמו !!\nלהראדיא באידית יש ועד דשלשה – הטעם שבהנ \" ל רק יחיד ?\nחוו \" ד רב דאנ \" ש שיחי ' ( בכתב ) שאין בהנ \" ל השגת גבול .\nקמ ג\nו ' אייר ][\nמענה לר ' אלתר לוי רייטער על מכתבו בקשר לקנין בית בשכונת\nקראונהייטס ( מהעתקת המזכיר . המענה מתפרסם בזה לראשונה\nבאדיבות הת ' מנחם מענדל שי ' הכהן העכט וזכות הרבים תלוי ' בו :)\nויהא בשטומו \" צ\nאזכיר עה \" צ"],[9200210080,"80\nמענות קודש – ה ' תשמ \" ב\nקמ ד\nו ' אייר ][\nמענה לא ' מרבני אנ \" ש על מכתבו בקשר לתכנית ( ראה לעיל מענה קל ח )\nדשידור שיעור בס ' התניא באנגלית ( ס ' \" שליחות כהלכתה \" ע ' 589 .\nתשורה רובין ט \" ו סיון תשס \" ד . והעתקה , באדיבות א ' מאנ \" ש שי :)'\n[1 במכתבו כתב : \" להיות אחראי . . ע \" י גלי הראדיו בשפת אנגלית .\"]\nכ \" ק אדמו \" ר שליט \" א סימן קו תחת התיבות \" בשפת אנגלית \", וכתב :\nלכן כדאי שיצרף אליו מומחה בשפה זו\n[2 ] במכתבו כתב : \" בדיוק ובסגנון . . עפ \" י המתורגם בספר התניא . .\".\nמענה כ \" ק אדמו \" ר שליט \" א :\nלברר אם מתאים לשומעים מבינים רק באנגלית\n[ כ \" ק אדמו \" ר שליט \" א הוסיף בע \" פ : צריכים לברר אם אין כאן השגת\nגבול .]\nקמ ה\nי \" א אייר ][\nמענה להת ' אברהם קנלסקי על מכתבו – בקשר להוראה שקיבל ( לעיל\nמענה קל ב ) לארגן חוג מתמידים מבין הבחורים הלומדים ב - 770 – בו\nכתב שרוצה לפנות במכתב לכו \" כ ישיבות שיארגנו במקומם \" סדר\nשיחות \" ע \" ד ה \" חוג \" שאירגן ב - 770 ( מהעתקה . המענה מתפרסם בזה\nלראשונה באדיבות ר ' שניאור זלמן שי ' ליבעראוו וזכות הרבים תלוי '\nבו :)\nמכ ' צ \" ל מהנהלת תו \" ת המרכזית אלו שיכול לדבר עמם עד כ \" ז – מהיר\n– אזכיר עה \" צ"],[9200210081,"81\nמענות קודש – ה ' תשמ \" ב\nקמ ו\nאייר ][\nמענה כללי - פרטי דימים אלו [ בין השאר – להת ' אברהם קנלסקי על דו \" ח\nמחוג מתמידים שאירגן ע \" פ הוראת כ \" ק אדמו \" ר שליט \" א ( לעיל מענה\nקל ב הלומדים יחדיו את ההנחות מההתועדויות ( יומן ר ' אהרן שי ')\nקורנט :])\nנת ' ות \" ח ודבר בעתו בסמיכות לי \" ד אייר – פסח שני , אזכיר עה \" צ .\nקמ ז\nאייר ][\nמענה לא ' על שאלתו במכתב כללי ימי הסליחות תשמ \" א ( לקו \" ש חכ \" ד\nע ' 605 ואילך ) שנתבאר שבהנהגת האדם ע \" פ תורה ישנם לכאורה שני\nניגודים – בכל מאדך \" וביחד עם זה \" לא תוסף עליו ולא תגרע ממנו ,\"\"\nוכן הוא בבריאת העולם – ש \" אמר לעולמו די \" וביחד עם זה \" לא חסר\nבעולמו דבר \", וכ ן הוא בבריאת האדם – שנברא במספר מסויים של\nאברים וגידים וביחד עם זה הכל במדה וגבול . ושאל הנ \" ל , דבהדוגמא\nדהנהגת האדם ובהדוגמא דבריאת האדם נתבארו הניגודים שבהם , גבול\nובלי גבול , אבל בהדוגמא דבריאת העולם לכאורה צריך ביאור איפוא\nרואים ניגוד זה ( קובץ הערות וביאור ים אהלי תורה ש \" פ בהו \" ב תשמ \" ב\nגליון קלג :))(\nבההמשך – שהאדם עושה אותו א \" ס\nלשיטתו – האדם א \" ס – תיכף כשנכנס בו נפה \" א וא \" צ עבודה כלל !!\nקמ ח\nאייר ][\nמענה לר ' נפתלי הכהן כהן שהכניס פנקס הגרלות לטובת מחנה \" גן\nישראל \" באנגליא , ושאל האם כ \" ק אדמו \" ר שליט \" א מאשר זאת ( ס '\nנלכה באורחותיו \" ע '\" 224 :)"],[9200210082,"82\nמענות קודש – ה ' תשמ \" ב\n[1 בקשר להפנקס שהכניס , כתב :]\nנת ' ות \" ח בסמיכות לת \" ת שבת \" ת .\nמצו \" ב השתתפות להראפעל .\nאזכיר עה \" צ .\n[ כ \" ק אדמו \" ר שליט \" א צירף שני שטרות של חמש פונט - שטרלינג בתור\nהשתתפות .]\n[2 ] סימן תיבת \" Approval [= מאושר ] שבמכתבו , וכתב :\"\n– לבד שכללו בהפרסים ... בקבוקי יי \" ש ?! ובפרט שמדובר בענין דחינוך\nוכו !'\nקמ ט\nאייר ][\nמענה לר ' ראובן מטוסוב על מכתבו בקשר להצעת שליחות בפאריז צרפת\nס ' \" שליחות כהלכתה \" ע '( 303 והעתקה :),\n[1 ] במכתבו כתב : \" הרבא \" ג שיחי ' מציע לנו שליחות כ \" ק אדמו \" ר\nשליט \" א בפריז , לי – לעבוד אצלו בלשכה המרכזית , ולה – להיות מורה\nבהבית רבקה ב \" ייער .\"\"\nכ \" ק אדמו \" ר שליט \" א סימן בעיגול את התיבות : \" לעבוד אצלו בלשכה\nהמרכזית , ולה – להיות מורה בהבית רבקה ב \" ייער \"\", וכתב :\nונכון וטוב ( 1)\n[2 ] במכתבו כתב : \" בנוגע להעבודה בהלשכה אמר לי שדבר עם כ \" ק\nאדמו \" ר שליט \" א בענין , ומדובר בעיקר אודות התעסקות במבצע ספר\nתורה וכן בשאר המבצעים ועוד כמה דברים ששייכים להלשכה – ובמשך\nהזמן וכו ' כל העבודות השייכים להלשכה .\"\nכ \" ק אדמו \" ר שליט \" א סימן בעיגול את התיבות \" התעסקות במבצע ספר\nתורה \", וכתב :\nכבר מתעסקים שם במרץ ( 2 )"],[9200210083,"83\nמענות קודש – ה ' תשמ \" ב\nק נ\nאייר ][\nמענה להשליח ר ' משה שמואל אוירכמן על מכתבו – בהמשך לסיום ס \" ת\nהכללי הראשון דאה \" ק , שהתקיים בל \" ג בעומר בעיר מירון – בו שאל\nהאם להמשיך בכתיבת ספרי התורה ( קובץ \" חב \" ד קריות \" ע ' 41 ,\nוהעתקה :)\nכ \" ק אדמו \" ר שליט \" א הורה להמשיך , וכתב :\nובתנאי שלא יפסיק כל זמן שישנו יהודי אחד שאין לו אות בספר התורה\nקנא\nאייר ][\nמענה כללי - פרטי דימים אלו [ בין השאר – להרב דוד ראסקין על דו \" ח\nממעמד סיום ס \" ת הכללי השני שע \" י ישיבת תו \" ת המרכזית ( תדפיס\nמספר \" ועבדי דוד \" – ס \" ת הכלליים שע \" י תו \" ת המרכזית – ע ' 23 :])\nנת ' ות \" ח ודבר בעתו בסמיכות לל \" ג בעומר , יום שמחתו גדולה\nדהרשב \" י . אזכיר עה \" צ .\nקנ ב\nח \" י אייר , ל \" ג בעומר ][\nמענה לא ' מרבני אנ \" ש על מכתבו בקשר לתכנית ( ראה לעיל מענה קל ח )\nדשידור שיעור בס ' התניא באנגלית ( ס ' \" שליחות כהלכתה \" ע ' 589 .\nתשורה רובין ט \" ו סיון תשס \" ד . והעתקה , באדיבות א ' מאנ \" ש שי :)'\n[1 ] במכתבו כתב : \" נתברר ע \" י הרב דווארקין שליט \" א וגם ע \" י שאין שום\nהשגת גבול בהנ \" ל לגבי אחרים .\"\nכ \" ק אדמו \" ר שליט \" א סימן קו תחת התיבות \" שאין שום השגת גבול .\"\n[2 ] במכתבו כתב : \" שאלתי אם נכון להגיש בהענין בפועל , כי בדעתנו\nאי \" ה להתחיל הלימודים בערך י \" ב תמוז הבעל \" ט .\"\nכ \" ק אדמו \" ר שליט \" א סימן קו תחת תיבת \" נכון .\""],[9200210084,"84\nמענות קודש – ה ' תשמ \" ב\n[3 על כללות המכתב , כתב :]\nאם ישתמשו בהשיעורים מהרב ר ' יוסף הלוי שיחי ' וויינבערג כדאי\nלצרפו בתורת יועץ אף שאינו חבר באיגוד הנ \" ל .\nאזכיר עה \" צ .\nקנ ג\nי \" ט אייר ][\nמענה למערכת \" ספר הליקוטים – דא \" ח צמח צדק \" שכתבו : \" בקשר\nלמה שעורר כ \" ק אדמו \" ר שליט \" א , שכדאי שכל ספרי הליקוטים – דא \" ח\nצ \" צ יהי ' מודפסים לחג השבועות \", ופירטו את המצב והקצב שיכולים\nלעמוד בו בתי - הדפוס ( מצילום כתי \" ק – \" לקט מענות קודש בקשר\nלהדפסת ספר הליקוטים דא \" ח צמח צדק \" ע ' 42 :)\nעפכ \" ז – כרך אחד לחה \" ש\nהשאר ליב תמוז .\nובלבד בהגהה ויופי וכו '\nקנ ד\nכ \" ף אייר ][\nמענה להרב יהושע הוטנר מנהל מכון האנציקלופדיא תלמודית ( מצילום\nכתי \" ק – תשורה טלזנר כ \" ט שבט תשנ \" ז :)\n[1 ] במכתבו כתב : \" הגעתי הנה לרגלי מלאכתי , מלאכת זבולון למען\nמושכים בעט סופר של יששכר חמור גרם , הממיתים עצמם על תורת\nהאנצקלופדיה התלמודית ומכון הש \" ס וכו .\"'\nמענה כ \" ק אדמו \" ר שליט \" א :\nויה \" ר שיהא בהצלחה וכו '\n[2 ] במכתבו כתב : \" והנה נתרצו עתה כמה מטובי ק \" ק . . להקדיש כרך\nאחד מכרכי האנצקלופדיה , שיש להוציאם מחדש , כי כבר אזל ואפס מן\nהשוק , לכבודו של האי גברא רבא הגאון הבקי העצום . . שליט \" א . . בכדי\nלתת למפעל זה חיזוק רוחני ומוסרי ארשה לי לבקש ממעכ \" ת מכתב"],[9200210085,"85\nמענות קודש – ה ' תשמ \" ב\nהמלצה ועידוד על שבחו של מקום ושבחו של חתן - התורה הדגול והנעלה\nעם כלת - התורה הכלולה באנצקלופדיה התלמודית .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\nלאחרי בקשת סליחה –\nאין זה נהוג כלל בבית הרב , כמפורסם .\nועוד – ואולי זהו א ' מטעמי המנהג מדורות :\nה \" ז מחייב :\n1 ) טעם להעדר השבח לכל אלו שהוקדש לכבודם ע \" ע – בעתם .\n2 ) מכ ' עידוד וכו ' לכל אלו שבעתיד ( 2)\n[3 את מכתבו חתם : \" בדחילו ורחימו וכט \" ס .\"]\nמענה כ \" ק אדמו \" ר שליט \" א :\nוכל המברך מתברך בבר ' של הקב \" ה כו ' ולקה \" ת בשמובפ \" נ ( 3)\nקנ ה\nועש \" ק בהו \" ב , כ \" א אייר ][\nמענה להת ' אברהם קנלסקי על מכתבו בו כמה שאלות בקשר להוראה\nשקיבל ( לעיל מענה קל ב ) לארגן חוג מתמידים מבין הבחורים הלומדים\nב - 770 ( יומן ר ' אהרן שי ' קורנט ( תוכן המענה ). המענה מתפרסם בזה\nלראשונה , מהעתקה , באדיבות ר ' שניאור זלמן שי ' ליבעראוו וזכות\nהרבים תלוי ' בו :)\n[1 ] במכתבו שאל האם להדפיס \" בלאנק \" שעליו יהי ' רשום \" חוג\nמתמידים נוסד ע \" י כ \" ק אדמו \" ר שליט \" א בשנת השמונים .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\nכפשוט הכוונה ביסוד הייתה להרבות ולהוסיף בתורה ולא במוסדות ,\nועל החוג להעשות סניף מאחד המוסדות הקיימים בחב \" ד כאן\n[2 במכתבו כתב שרוצה להו \" ל קובץ \" הערות התמימים \" ע \" י החוג .]\nמענה כ \" ק אדמו \" ר שליט \" א :"],[9200210086,"86\nמענות קודש – ה ' תשמ \" ב\nהרי יש כבר כו \" כ קובצים\n[3 ] במכתבו כתב שאינו יכול ללמוד ( ע \" פ הוראת כ \" ק אדמו \" ר שליט \" א\nאליו לשבת וללמוד ), כיון שצריך להדפיס שיחות חדשות , להשיג כסף\nוכיו \" ב .\nמענה כ \" ק אדמו \" ר שליט \" א :\nזה צ \" ל ע \" י ועד ולא ע \" י יחיד כבכל החוגים והמוסדות\n[4 ] על מה שכתב ( כדלעיל 3 שמדפיס שיחות חדשות , כתב :)\nיש ללמוד מספרים הנדפסים ולא לבזבז ממון ישראל\nקנ ו\nמוצש \" ק בהו \" ב , כ \" ב אייר ][\nמענה לא ' מרבני אנ \" ש על מכתבו בקשר לתכנית שידור שיעור בס ' התניא\nבאנגלית ( ראה לעיל מענה קל ח ), בו כתב : \" בזה הנני להודיע כי . .\nנתקשרו עם הרב יוסף הלוי שי ' וויינבערג ע \" פ עצת כ \" ק לצרפו בתור יועץ\nבהשיעורים [ לעיל מענה ק נב ], והוא הסכים להשתתף בשביעת רצון . גם\nנודע לי כי כבר הכינו השיעור הראשון ללימוד , והשי \" ת יעזור להמשיך\nבהצלחה \" ( תשורה רובין ט \" ו סיון תשס \" ד :)\nנתקבל בתשואות חן\nודבר בעתו מה טוב\nקנ ז\nכ \" ג אייר ][\nמענה לא ' מרבני אנ \" ש על מכתבו – בקשר לתכנית שידור שיעור בס '\nהתניא באנגלית ( ראה לעיל מענה קל ח בו כתב :),\n\" אי נעים לי להטריד את כ \" ק עוד , אך לאחר שהכניסו אותי בהענין\nהעומד על הפרק הנני מוכרח למלאות תפקידי .\nכידוע לכ \" ק התקשרתי עם . . כדי שיצטרף בתור מומחה בשפת אנגלית\n– והציע לפני הוועד אולי נכון בעת הלימוד לדלג את הלשון בפנים בספר"],[9200210087,"87\nמענות קודש – ה ' תשמ \" ב\nהתניא , בהפרקים יותר יוקשה ההסברה והביאור בהמילים , ורק לבאר\nבעל פה , וללמוד בפנים כל השורות אשר יתקבלו להשומעים .\nלא הי ' לנו ההמשכה לבא לכ \" ק בהצעה זו , אך אתמול בש \" ק הי ' לו\nהתראות עם חברי הוועד ושאל עוד הפעם , אם כתבו לכ \" ק ע \" ד הצעתו\nהנ \" ל .\nוהנה מדרכי הנימוס , וגם לטובת הענין שכל אחד יעסוק בשביעת רצון\nהנני כותב הצעתו , וכהוראת כ \" ק כן נעשה .\"\nמענה כ \" ק אדמו \" ר שליט \" א ( ס ' \" שליחות כהלכתה \" ע ' 589 . תשורה\nרובין ט \" ו סיון תשס \" ד :)\nכ \" ק אדמו \" ר שליט \" א סימן את התיבות : \" לדלג את הלשון בפנים בספר\nהתניא \", וכתב :\n1 ) מופרך בהחלט .\n2 ) כנראה עלול שתבא הצעה שהשיעור ( עכ \" פ ) הראשון ילומד ע \" י\nסענאטאר גוי דווקא , ולמעט טרחות שפיץ חב \" ד לדון באריכות על דבר\nזה , – וה ' יודע מה תהי ' החלטתם , שהרי ע \" י הגוי יתוסף בחוצה ,\nובקיומו ז ' מצוות דבני נח , הנני שולל \" גם \" את זה .\nאולי יצרפו להוועד א פשוטן חסידישן איד שאינו עוסק בציבור ולא רב\nכו .'\nקנ ח\nכ \" ה אייר ][\nמענה לר ' לוי גאלדשטיין שכתב : \" בקשר לימי הקיץ הבעל \" ט , קבלנו ב '\nהצעות במשרות מלמדות : א ) במחנה גן ישראל , קרית גן ישראל נ . י . . .\n( אגב , בקיץ העבר היינו שם , והי ' ב \" ה בהצלחה ). ב ) ב \" היילאנד - פארק\nבאנגאלא קאלאני \" . . והננו לבקש עצת כ \" ק אדמו \" ר שליט \" א בזה , האם ,\nואיזה הצעה לקבל \" ( מהעתקת המזכיר . המענה מתפרסם בזה לראשונה\nבאדיבות הנמען שי ' וזכות הרבים תלוי ' בו :)\nכ \" ק אדמו \" ר שליט \" א סימן שני קווים תחת התיבות \" והי ' ב \" ה\nבהצלחה \" ( שבהצעה הראשונה ), וכתב :\nקדימה\nאזכיר עה \" צ"],[9200210088,"88\nמענות קודש – ה ' תשמ \" ב\nקנ ט\nועש \" ק במדבר , כ \" ח אייר ][\nמענה לר ' צבי מאיר שטיינמעץ על מכתבו בו ביקש הסכמת כ \" ק אדמו \" ר\nשליט \" א לנסיעתו לאה \" ק . וכן כתב : \" ובשולי היריעה אבא כעני המהפך\nבמנחתו , מנחת עני : בערב י \" א ניסן הגשתי שי את קובץ שירי החדש \" בין\nהבאים \", בין עשרות ספרי קדש אשר עלו אז על שולחן המלך . ( בשער\nהספר : הקדשת כל הספר לשם כ \" ק ובתוך הספר שירי \" צבי לצדיק .\"\nבשיר \" פסוקי דזמרה \" זכיתי להכניס המלים \" יחיד ומיוחד \" מעטו של\nכ \" ק [ צילום כתי \" ק – תשורה דלקמן ] ואמנם את ה \" השתתפות \" הזאת\nאני מחשיב לההישג הכי גדול שבכל הספר ...). ואמנם לא אדע אם כבר\nהספיק כ \" ק אד \" ש להעיף עינו על תשו רתי , כי \" לאו אורחא דמלכא\nלאשתעי במלין דהדיוטא \". ולאות לטובה על הפקת רצון קדשו עיני צופי -\nה ...\" ( תשורה זלמנוב כ \" ד סיון תשע \" א . \" בית חיינו \" תשנ \" ב גליון 114 :)\nויהא בשעטומ \" צ ומצורף לצדקה שם . ת \" ח על הבשו \" ט הנ \" ל וכפשוט\n– על ספר השירים לי \" א ניסן – ולא הארכתי במילין על דבר זה – ואפי '\nלא בקיצור – כי ( כסיום מכתבו ) \" לאו אורחא דבר נש לאשתעויי במילין\nדתושבח ת א דילי '\". ות \" ח ת \" ח על המצו \" ב אזעה \" צ .\nקס\nד ' סיון ][\nמענה לר ' כתריאל ברוך קסטל על מכתבו בו בקשת ברכה לכמה\nמקורבים , ביניהם א ' החוגג את יום הולדתו ( מהעתקת המזכיר . המענה\nמתפרסם בזה לראשונה באדיבות הנמען שי ' וזכות הרבים תלוי ' בו :)\nמנהגי יום הולדת\nבדיקת התפילין והמזוזות דכהנ \" ל\nאזכיר עה \" צ"],[9200210089,"89\nמענות קודש – ה ' תשמ \" ב\nקסא\nח ' סיון , אסרו חג השבועות ][\nמענה להרב מרדכי שמואל אשכנזי שכתב – בקשר לספרו על הלכות\nתלמוד תורה לאדה \" ז : \" היות ובדעתי איה \" ש להדפיס בתחילת הספר\nאת פנים השולחן - ערוך דאדמו \" ר הזקן כמו שהוא , אם נכון קריאת שם\nהספר \" הלכות תלמוד תורה לאדמו \" ר הזקן עם הערות וציונים \"\", וכן\nהציע את השם \" הערות וציונים להלכות תלמוד תורה \" ( מבוא לס '\nהלכות תלמוד תורה עם הערות וציונים \" פרק א ( הוצאת קה \" ת , תש \" ס )\"\nכרך א . ס ' \" הרב אשכ נזי \" ע ' 531 , 534 :)\nכ \" ק אדמו \" ר שליט \" א סימן את התיבות \" הלכות תלמוד תורה לאדמו \" ר\nהזקן עם הערות וציונים .\"\nקסב\nי \" ב סיון ][\nמענה לבני משפחה מאנ \" ש שכתבו – בקשר לאביהם שאינו בקו\nהבריאות : \" ושאלתינו אם : א ) לקבל את הצעת ד \" ר . . ולעשות ניתוח , ב )\nלקבל את הצעת ד \" ר פרופסר . . ונטיית אחינו – ולעשות הקרנות . גם\nאבינו אומר שאינו רוצה ניתוח , ויסכים להקרנות \" ( מהעתקה . המענה\nמתפרסם בזה לראשונה באדיבות א ' מאנ \" ש שי ' וזכות הרבים תלוי ' בו :)\nכ \" ק אדמו \" ר שליט \" א סימן בעיגול את התיבות \" אבינו אומר שאינו\nרוצה ניתוח , ויסכים להקרנות \", וכתב :\nכן יעשו וכדאי שישאלו עוד רופא מומחה אחד\nאזכיר עה \" צ\n[ וראה לקמן מענות ק ע , ק פב .]\nקס ג\nלאחר ש \" פ נשא , י \" ד סיון ][\nמענה להמזכיר ריל \" ג על מכתבו בקשר להמבואר בהתועד ות ב ' דחג\nהשבועות ו המשכו בהתועדות ש \" פ נשא – שנתבאר ההפרש בהסיפור\nהמובא בסיום מסכת סוטה , בין הלשון בבבלי \" יש בכם אדם אחד ש ראוי\nשתשרה שכינה עליו \", והלשון בירושלמי \" יש ביניכם שנים ראוין ל רוח"],[9200210090,"90\nמענות קודש – ה ' תשמ \" ב\nהקודש \", ש \" השראת ה שכינה \" המדוברת בבבלי היא במדריגה עליונה\nלגבי \" רוח הקודש \" המדובר בירושלמי , ו ראי ' לדבר מפרקי אבות ( פ \" ג\nמ \" ו ) : \" עשרה שיושבין ועוסקין בתורה שכינה שרוי ' ביניהם . . ומנין\nאפילו חמשה . . שלשה . . שנים . . אחד כו ' \", ומכאן שיש דרגות באופן\nהשראת השכינה במכתבו כתב :.\nלכאורה בפרקי אבות שם מדובר ע \" ד שכינה שרוי '\" ביניהם – שזה שייך\nאפילו אצל אחד שיושב ועוסק בתורה ( ובטח הי ' זה אצל כאו \" א\nמהתנאים ), אף אצל איש ואשה שזכו ששכינה שרוי ' ביניהם \"? .\nמענה כ \" ק אדמו \" ר שליט \" א תשורה לוין י \" ט אד \" ר תשס \" ה :)(\nוהוא ע \" ד ושכנתי בתוכם – השראת השכינה שהי ' במשכן ובביהמ \" ק ,\nוראו עשרה נסים שנעשו בביהמק \" ד ,\nאבל כאן מדובר ע \" ד השראת שכינה עליו – הגדר וע \" ד דנבואה , שבזה\nע \" ד שכינה מדברת מתוך גרונו של משה .\nוכמו שיש חילוק בין רוה \" ק דישעי ' ויחזקאל , יש חילוק בדרגת השכינה\nשהי ' מדברת מתוך גרונו של משה , וזה שאי ' בברכות נז , א הקורא ק \" ש\nראוי שתשרה עליו שכינה .\nקס ד\nסיון ][\nמענה לאחת ששאלה בקשר לעשיית נקב באזניים בשביל נזם האוזן\nלקו \" ש ח \" כ ע '( 568 :)\nע \" ד לעשות נקב באזנים , בשביל נזם אוזן ( קישוט נשים – המוזכר\nבתנ \" ך בנשי ישראל כדבר הרגיל ובשו \" ע או \" ח סש \" ג )\n– בטח העונג הממושך מקישוט הנ \" ל – גדול שלא בערך לגבי הצער\nדהגוף ברגע הנקיבה .\nולכן מותר הוא אף 1 בגדולה ,) 2 ) שיש מתקשטות בהנ \" ל מבלי עשיית\nנקב ( כיון שאינו רגיל כ \" כ . ועוד ועיקר – שאז יש צער קצת בכל פעם פון\nקוועטשן האוזן .)\nוי \" א שנוהגין לנקוב האוזן ע \" ד ורצע אדוניו את אזנו ( ראה רד \" ל לפדר \" א\nפי \" ד , הגה ט .)\nבכ \" ז – תשאל רב מורה הוראה ."],[9200210091,"91\nמענות קודש – ה ' תשמ \" ב\nקס ה\n[ סיון ( 1 ])\n\" צעטל \" בכתי \" ק שכתב כ \" ק אדמו \" ר שליט \" א – בקשר למכתב ט ' אלול\nתש \" ג ( הנדפס בלקו \" ש חט \" ז ע ' 492-3. אגרות - קודש ח \" א ע ' קפ ) בענין\n\" מה שבשמות עב סג מה מספר המרובה קודם , משא \" כ בשם בן \" ( קובץ\nעבודת הקודש אצל הרבי \" ע ' יז :)\"\nלאחרי זמן מצאתי עד \" ז בכמה ביכלאך דא \" ח , וז \" ל בביכל . . .\nלהררשד \" ב שי ' לוין\nלהעתיק מ \" מ הביכלאך ולהדפיס ביגדיל תורה הבע \" ל ובקובץ המצו \" ב\nקס ו\n[ סיון ( 2 ])\nמענה לר ' שלום דובער לוין שכתב – בהמשך להמענה שקיבל : \" לע \" ע לא\nמצאנו בהביכלאך ע \" ד שם ב \" ן , שאות בי \" ת הוא לפני אות נו \" ן . . העירו\nעד \" ז בהערות ובאורים – בשלח תשמ \" א , ובהערות הת ' ואנ \" ש\nמוריסטאון – בא תשמ \" א . ומצו \" ב \" ( קובץ \" עבודת הקודש אצל הרבי \"\nע ' יז :)\nבעצמי ראיתי בהביכלאך ][ להחזיר המצו \" ב ..\nקס ז\n[ סיון ( 3 ])\nמענה לר ' שלום דובער לוין – בהמשך להמענות שקיבל ע \" ד המבואר\nבביכלאך דא \" ח בענין \" מה שבשמות עב סג מה מספר המרובה קודם ,\nמשא \" כ בשם בן \". לאחר שמצאו אודות ענין זה בביכלאך דא \" ח , והכניסו\nאת עלי - ההגהה לכ \" ק אדמו \" ר שליט \" א , מצאו בנושא זה גם בכת \" י\nספרדי מאת הרב משה רביבו מפאס ( קובץ \" עבודת הקודש אצל הרבי \"\nע ' יז :)\nלהדפיס .[ ]. דהספרדי"],[9200210092,"92\nמענות קודש – ה ' תשמ \" ב\nקס ח\nסיון ][\nמענה לר ' שלום דובער לוין שכתב ע \" ד תשובת הרב יוסף תומארקין\nשעומד להדפיס בבטאון \" יגדיל תורה \" חוברת מח , וציין שגם אדמו \" ר\nמהר \" ש דן בנושא המדובר בתשובותיו ( קובץ \" עבודת הקודש אצל הרבי \"\nע ' סז :)\nמעולם לא נשמע ע \" ד שו \" ת [ כ \" ק אדמו \" ר מוהר \" ש נ \" ע ] לבד ע \" ד\nתרנגולי כו .'\nקס ט\nסיון ][\nמענה לר ' ישראל לייבוב יו \" ר \" צעירי אגודת חב \" ד \" באה \" ק ( מהעתקה :)\n[1 על מה שכתב ע \" ד עיתון \" כפר חב \" ד \", כתב :]\nמצו \" פ שעק השתתפות ע \" ס אלף דולר\n[2 על מה שכתב : \" תקותי שכ \" ק אדמו \" ר שליט \" א מרוצה מהעיתון ,\"]\nכתב :\nביותר\nאבל כדאי לגוון אותו\n( ולא שיהי ' רובו – ע \" ד איש אחד ובכל חוברת )!!\nועיקר – מדור דפתגמים קצרים מדא \" ח\nקע\nט \" ז סיון ][\nמענה לבני משפחה מאנ \" ש שכתבו – בהמשך להמענה שקיבלו ( לעיל\nמענה ק סב ) בקשר להטיפול באביהם שאינו בקו הבריאות : \" לפי דעת\nהרופא דכאן יכולים להתחיל את הטיפול באה \" ק מיד ולהביא את אבינו\nשיחי ' אליו אחרי החתונה של נכדו . . ט ' תמוז הבעל \" ט . שאלתינו היא\nאם להביא את אבינו שיחי ' לכאן אחרי ט ' תמוז הבעל \" ט \" ( מהעתקה ."],[9200210093,"93\nמענות קודש – ה ' תשמ \" ב\nהמענה מתפרסם בזה לראשונה באדיבות א ' מאנ \" ש שי ' וזכות הרבים\nתלוי ' בו :)\nב אם ][ רב מורה הוראה באה \" ק יסכים – ע \" פ כהנ \" ל להביא כו ]'[\nקעא\nי \" ז סיון ][\nמענה לר ' אברהם אלתר הלוי הבר על דו \" ח בקשר להכנות לסיום ס \" ת\nהכללי עבור בנ \" י הנמצאים \" מאחורי מסך הברזל \" במדינת רומניא ( ראה\nלעיל מענות פ ב , פ ג ), הנערך בנחלת הר חב \" ד ( ס ' אלבום \" אות בספר\nתורה \" ע ' 68 , 183 :)\nהרבנית שתליט \" א תשלם עבור מעיל שיעשו כדרכם באה \" ק .\nקעב\nח \" י סיון ][\nמענה לאחת שביקשה הסכמת כ \" ק אדמו \" ר שליט \" א לנסיעתה לאה \" ק\nבניירות לא - חוקיים ( ס ' \" הבית החסידי במשנתו של הרבי \" ח \" ב ע ' 75 :)\nה \" ז בלתי חוקי ולא תעשה זה , אזכיר עה \" צ .\nקע ג\nי \" ט סיון ][\nמענה להנהלת \" צעירי אגודת חב \" ד \" המרכזית על דו \" ח שכתבו ע \" ד\nהמקומות שצלצלו להם ומסרו מהמדובר בההתועדות דחג השבועות :\"\nא ) להדפיס קובצי חידושי תורה , ב ) לעשות כינוסים מצבאות ה ' עד י \" ב\nסיון הבעל \" ט , ג ) להשתדל עוד יותר לרשום בהס \" ת הכלליים \" ( מצילום\nכתי \" ק – תדפיס מספר ועבדי דוד \"\" – ס \" ת הכלליים שע \" י תו \" ת\nהמרכזית – ע ' 63 :)\nסימן בעיגול ובשני חיצים את התיבות \" ב \" ה ט ' סיון תשמ \" ב \" שבראש\nהמכתב , וכתב :"],[9200210094,"94\nמענות קודש – ה ' תשמ \" ב\nנת ' בעתו . ות \" ח .\nיט סיון\nנת ' המצו \" ב . . ( מב ' מקומות )! – גם ע \" פ טבע כפשוטו – צ \" ל קנאת\nסופרים תרבה חכמה . אולי יבררו אצל הסופרים שברשימתם הנתקיים\nאצלם במעשה בפועל . ומתי יו \" ל בפועל ( 1)\nלהחזיר לי המצו \" ב ( 2)\nומצוה גוררת מצוה – ע \" ד אותיות בס \" ת הכלליים . ( 3)\nאזכיר עה \" צ ( 4 )\n[ בקשר להדפסת קובצי חידושי תורה – ראה גם לקמן מענות : קצ ט , ר לא ,\nדלר , ר במ .]\nקע ד\nאור לועש \" ק בהעלותך , כ \" ף סיון ][\nמענה לא ' מאנ \" ש על פ \" נ שכתב עבור בנו הנולד למז \" ט לפני כמה שבועות ,\nשעדיין לא נכנס בבריתו של אברהם אבינו מפני ה \" צהיבות \", וכן ביקש\nברכה עבור שאר בני המשפחה ( מהעתקה . המענה מתפרסם בזה\nלראשונה באדיבות הנמען שי ' וזכות הרבים תלוי ' בו :)\nאזכיר עה \" צ\n[ וראה לקמן מענות : קע ו , קע ז , קע ח , קע ט , קפ ז .]\nקע ה\nועש \" ק שלח , כ \" ף סיון ][\nמענה לר ' שמואל יהודה הלוי וינפלד בקשר לספר סימנים לשינון ס '\nהתניא שברצונו לערוך ( ריש ס ' \" סימני האמרים :)\"\n1 ) בחרוזים – בכל אופן לא כדאי ( כי יוסיף קושי וכו ' בההבנה וכו .)'\n2 מצו \" ב לצדקה בירושלים .)\n3 ) בכללות הענין – יתייעץ באנ \" ש שי ' שהם משפיעים , מחנכים וכיו \" ב ."],[9200210095,"95\nמענות קודש – ה ' תשמ \" ב\nולהעיר דכמה וכמה סוגים בסימנים : רק ראשי תיבות דענינים\nהמסומנים , תיבת - רמז דכל אחד ואחד , ( או החשבון : רמ \" ח מ \" ע\nואיברים ) וכיוצא בזה – הסימנים בש \" ס ומדרשים , תיבת - תוכן דכל\nאחד ואחד ( ספר המצוות להרס \" ג וכיוצא בזה .)\nובמאמרי חז \" ל בנוגע לסימנים – צריך עיון בכל אחד ואחד השייכים\nלכל הנ \" ל או רק לאחדים .\nחזרת ק - קא פעמים – הרי זה \" בימיהם \" כשלא היתה תורה שבעל פה\nכתובה כו ' ( הלכות תלמוד תורה לאדמו \" ר הזקן פרק ב ' הלכה ג .)'\nקע ו\nכ \" ב סיון ][\nמענה לא ' מאנ \" ש על מכתבו בקשר למצב ו ( ראה לעיל מענה קע ד ) של בנו\nהתינוק ( מהעתקה . המענה מתפרסם בזה לראשונה באדיבות הנמען שי '\nוזכות הרבים תלוי ' בו :)\n[1 ] במכתבו כתב : \" במוצש \" ק בקרנו ד \" ר . . שי ', שהוא טיפל בו בבית\nהרופאים כשנולד . . לדעתו . .; הבוקר , היות שעדיין הי ' לו חום , בקרנו\nד \" ר Benjamin שי ' ( ד \" ר הילדים שיחיו שלנו מכבר ) . . ולדעתו . .\".\nמענה כ \" ק אדמו \" ר שליט \" א :\nויעשו בכ \" ז וכן להבא כעצת [ ד \" ר Benjamin שי ]'\n[2 במכתבו כתב : \" מוסג \" פ : דמי פ \" נ עבור בננו שליט \" א . ח \" י שקלים .\"]\nמענה כ \" ק אדמו \" ר שליט \" א :\nלמל \" ח\nאזכיר עה \" צ\nקע ז\nכ \" ג סיון ][\nמענה על פתק שכתב המזכיר ריב \" ק עבור א ' מאנ \" ש בקשר למצב בנו\nהתינוק ( ראה לעיל מענה קע ד ) , בו כתב : \" מבקשים למסור כי ע \" פ הצעת\nד \" ר בנג ' מין מכניסים בנם שי ' לביה \" ח לעשות בדיקות ומבקשים ברכת"],[9200210096,"96\nמענות קודש – ה ' תשמ \" ב\nכ \" ק אדמו \" ר שליט \" א לרפוש \" ק \" ( מהעתקה . המענה מתפרסם בזה\nלראשונה באדיבות הנמען שי ' וזכות הרבים תלוי ' בו :)\nאזכיר עה \" צ\nקע ח\nכ \" ג סיון ][\nמענה לא ' מאנ \" ש על מכתבו בקשר למצב בנו התינוק ( ראה לעיל מענה\nקע ד ) , בו כתב : \" עפ \" י עצת ד \" ר בנג ' מין שי ' הבאנו בננו שליט \" א לבית\nהרופאים לבדיקות . . והרשו לבננו שליט \" א לחזור הביתה , ב \" ה . . ויה \" ר\nשנוכל מכאן ולהבא לבשר אך טוב תכה \" י \" ( מהעתקה . המענה מתפרסם\nבזה לראשונה באדיבות הנמען שי ' וזכות הרבים תלוי ' בו :)\nאזכיר עה \" צ\nקע ט\nועש \" ק קרח , כ \" ז סיון ][\nמענה לא ' מאנ \" ש על מכתבו בקשר למצב ו של בנו התינוק ( ראה לעיל\nמענה קע ד ,) הנמצא בבית - הרופאים ( מהעתקה . המענה מתפרסם בזה\nלראשונה באדיבות הנמען שי ' וזכות הרבים תלוי ' בו :)\n[1 ] במכתבו כתב : \" והננו לבקש עצת כ \" ק אדמו \" ר שליט \" א האם הוא\nכדאי שאשתי תי ' תשאר במשך כל הש \" ק בביה \" ר להשגיח וכן להיות\nאצל בננו שליט \" א . .\".\nכ \" ק אדמו \" ר שליט \" א סימן בעיגול קטע זה , וכתב :\nבזה ובכל כיו \" ב כעצת רופא ידיד\n[2 ] במכתבו כתב : \" היום נתמלאו ד ' שנים לבננו הבכור . . שליט \" א , והננו\nלבקש ברכת כ \" ק אדמו \" ר שליט \" א . .\".\nכ \" ק אדמו \" ר שליט \" א סימן בעיגול את התיבות \" היום נתמלאו \", וכתב :\nמנהגי\n[3 ] במכתבו כתב : \" אגב , כמעט בכל פעם שמבקרים בננו שליט \" א בביה \" ר\nרושמים כו \" כ יהודים בס \" ת הכלליים .\""],[9200210097,"97\nמענות קודש – ה ' תשמ \" ב\nכ \" ק אדמו \" ר שליט \" א סימן שני קווים תחת התיבות \" רושמים כו \" כ\nיהודים בס \" ת הכלליים .\"\n[4 במכתבו כתב : \" מוסג \" פ ה ' שקלים , דמי פ \" נ עבור בננו . . שיחי .\"']\nכ \" ק אדמו \" ר שליט \" א סימן בעיגול קטע זה , וכתב :\nלמל \" ח ( 4 )\nאזכיר עה \" צ\nקפ\nשלהי סיון ][\nמענה לחתן שביקש עצה כיצד לעודד את כלתו שתהי ' בשמחה ביום\nהחתונה , לאחר פטירת אם אמה בשבוע שלפני החתונה ( מצילום כתי \" ק\n– תשורה קניבסקי ז ' תמוז תשס \" ח . לקו \" ש חי \" ט ע ' 511 :)\nיספר לה מחז \" ל – שרגע אחד לאחרי החורבן נולד גואלן של ישראל\n( באם היו זוכין להגאל בדור ההוא ). ואחד הטעמים – שכמאיזה טעם\nשיהי ' יש ענין בלתי רצוי , הקב \" ה מביא בהקדם עידוד חזק שלא יפלו\nח \" ו ברוחם וכו ' . ואשריהם שבחתונתם תומ \" י מתחילים בהמשכת\nברכות השם גם לכל המשפחה , כיון שהתורה מצווה אותם להיות\nשמחים בשמחת החו \" כ שי '. ומקרבת גאולת ושמחת כל בנ \" י וכהל '\nבבר ' נישואין : מהרה ישמע כו ' שמחה כו '\nקפ א\nבדר \" ח תמוז ][\nמענה לא ' מעסקני חב \" ד על מכתבו בקשר להתקדמות תכנית שידור\nשיעור בס ' התניא באנגלית ( ראה לעיל מענה קל ח ), בו כתב שעומד בקשר\nהדוק עם הרב מאנ \" ש שאיתו מתייעצים בנושא ( ס ' \" שליחות כהלכתה \"\nע ' 590 :)\nכנראה מכל הסגנון הוא היוצר ובמילא הוא המבין הוא הדיין וכו ' בדומה\nכביכול כו ' אבות סוף פרק ד ' – כיון שלדעתי אינו דומה , לכן יבטל כל\nהענין מעיקרו ובהקדם ויודיעני תיכף ."],[9200210098,"98\nמענות קודש – ה ' תשמ \" ב\nהמדובר והתנאי הי ' שהם יהיו ועד ההנהלה היינו שינהלו ולא\nשיתייעצו עמהם \" בקשר הדוק \" וכל הענין יהי ' בידיו של יחיד ויהי '\nהגדול בכל ישראל .\nקפב\nבדר \" ח תמוז ][\nמענה לבני משפחה מאנ \" ש על מכתבם – בהמשך להמענות שקיבלו ( לעיל\nמענות ק סב , ק ע ) בקשר להטיפול באביהם שאינו בקו הבריאות\nמהעתקה . המענה מתפרסם בזה לראשונה באדיבות א ' מאנ \" ש שי '(\nוזכות הרבים תלוי ' בו :)\n[1 על מה שכתבו שקבעו תור לטיפול באביהם ליום ראשון הבע \" ל , כתב :]\nויהא בשעטומו \" צ\n[2 ] במכתבם שאלו האם לתת לאביהם את הטיפולים שהציע ד \" ר\nמסויים באה \" ק .\nכ \" ק אדמו \" ר שליט \" א סימן בעיגול את התיבות \" באה \" ק \", וכתב :\nכעצת רופא ידיד באה \" ק .\n[3 על כללות המכתב , כתב :]\nאזכיר עה \" צ\nקפ ג\nועש \" ק חוקת , ד ' תמוז ][\nמענה לא ' השלוחים על מכתבו ע \" ד המצב במקומו ( מהעתקה . המענה\nמתפרסם בזה לראשונה באדיבות א ' מאנ \" ש שי ' וזכות הרבים תלוי ' בו :)\nנתקבל ות \" ח ודבר בעתו\nכפשוט – כ \" ז שייך להב \" ד דרבני אנ \" ש שי '"],[9200210099,"99\nמענות קודש – ה ' תשמ \" ב\nקפ ד\nתחלת תמוז ][\nמענה כללי - פרטי דימים אלו [ בין השאר – להרב דוד ראסקין על דו \" ח\nמהתועדויות שערך – בהמשך להוראת כ \" ק אדמו \" ר שליט \" א בהתועדות\nש \" פ שלח ( מהעתקה , באדיבות מערכת הספר \" ועבדי דוד :])\"\nנת ' ות \" ח\nודבר בעתו –\nבסמיכות לר \" ח תמוז – חודש הגאולה\nויה \" ר שיהא בכהנ \" ל – מלכתחילה אריבער\nאזכיר עה \" צ\nקפ ה\nט ' תמוז ][\nמענה לא ' מאנ \" ש ( מהעתקה . המענה מתפרסם בזה לראשונה באדיבות\nא ' מאנ \" ש שי ' וזכות הרבים תלוי ' בו :)\n[1 ] במכתבו כתב : \" מצו \" ב י \" ג שקלים לרגלי הכנסו של בננו . . שיחי ' היום\nלשנת הי \" ג לאיוש \" ט .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\nמנהגי יום הולדת\n[2 ] במכתבו כתב : \" עשינו היום חנוכת הבית לשני חדרים בביתינו . .\nאספנו צבאות ה ' ועשינו תורה – י \" ב הפסוקים וכו ', תפילה – ברכות על\nמיני מתיקה ושיבנה בית המקדש , וצדקה – מטבעות לצדקה לכאו \" א .\nונבקש ברכת כ \" ק אדמו \" ר שליט \" א שיהי ' בהצלחה .\"\nכ \" ק אדמו \" ר שליט \" א סימן בעיגול קטע זה , וכתב :\nוגדול הזכות וכו '\n[3 על כללות המכתב , כתב :]\nאזכיר עה \" צ"],[9200210100,"100\nמענות קודש – ה ' תשמ \" ב\nקפ ו\nט ' תמוז ][\nמענה לא ' מאנ \" ש שביקש ברכה עבור מקורב שלו שחש בעינו ( מהעתקה .\nהמענה מתפרסם בזה לראשונה באדיבות א ' מאנ \" ש שי ' וזכות הרבים\nתלוי ' בו :)\nאזכיר עה \" צ\nקפ ז\nט ' תמוז ][\nמענה לא ' מאנ \" ש על מכתבו בקשר למצב בנו התינוק ( ראה לעיל מענה\nקע ד ,) שע \" פ הצעת הרופא ד \" ר בנג ' מין מחזיקים אותו עוד כמה ימים\nבבית - הרופאים , ואשר הכנסתו לבריתו של אברהם אבינו – ע \" פ הוראת\nהרב זלמן שמעון דווארקין – תהי ' ביום א ' כ \" ף תמוז ( מהעתקה . המענה\nמתפרסם בזה לראשונה באדיבות הנמען שי ' וזכות הרבים תלוי ' בו :)\nאזכיר עה \" צ\nקפ ח\nט \" ו תמוז ][\nמענה להרב דוד ראסקין שכתב דו \" ח מאסיפת הנהלת ישיבת תו \" ת\nהמרכזית בקשר לסיום ס \" ת הכללי השלישי שלהם ( תדפיס מספר \" ועבדי\nדוד \" – ס \" ת הכלליים שע \" י תו \" ת המרכזית – ע ' 66 :)\n[1 במכתבו כתב : \" הדיבור עם הסופר ר ' אליעזר שי ' צירקינד הי ', שיהי ']\nנגמר כתיבת הס \" ת הג ' לט \" ו - ח \" י אלול , ט \" ו אלול חל ביום ו ' בשבוע , ח \" י\nאלול ביום ב ' בשבוע ואז יהי ' הפאראד שלהם על איסטערן פארקוויי ,\nומשו \" ז יהי ' קשה הנסיעה ביום זה , בי \" ז אלול שחל ביום א ' בשבוע ,\nשי הי ' כאלו הנמצאים בנאות דשא לא יחזרו עדיין . או לסדר בי \" ט אלול\nשאז חל ביום ג ' בשבוע . וכן הי ' סברא שאפשר נוגע שיהי ' הסיום בהקדם\nהא פ שרי מאחר שהסופר אמר שיכול לגמור הס \" ת הג ' איזה ימים לפני\nט \" ו מנ \" א , ואז השאלה אם לעשות הסיום בט \" ו מנ \" א או בי \" ד מנ \" א שחל\nביום ג ' בשבוע .\""],[9200210101,"101\nמענות קודש – ה ' תשמ \" ב\nמענה כ \" ק אדמו \" ר שליט \" א :\nטוב שיהי ' הסיום בהקדם האפשרי ] [ בט \" ו מנ \" א ][\n[2] במכתבו כתב : \" וגם השאלה באיזה מקום לעשות הסיום , או ב - 770\nא . פ ., או ב - 885 בהבנין של הישיבה ( חובבי תורה ), והשאלה באיזה מקום ,\nובאיזה זמן , לעשות הסיום של הס \" ת הג ' והתחלת כתיבת ס \" ת הד .\"'\nכ \" ק אדמו \" ר שליט \" א סימן בחץ את התיבת \" בהבנין של הישיבה ( חובבי\nתורה )\", וציין : (2)\n[3 על כללות המכתב , כתב :]\nאזכיר עה \" צ\nקפ ט\nתמוז ][\nמענה כללי - פרטי דימים אלו [ בין השאר : ( 1 ) לפעילי \" צעירי אגודת\nחב \" ד \" בצפון אה \" ק על דו \" ח מפעילותם עם חיילי צה \" ל במהלך מלחמת\nלבנון (\" כפר חב \" ד \" גליון 59 ;) ( 2 ) לר ' ראובן הלמן על מכתבו ( תשורה\nדייטש כ \" ה סיון תשע \" א ;) ( 3 ) לר ' דוד ראסקין בקשר לנסיעת ר ' מנחם\nשמואל דוד הלוי רייטשיק לכמה מקומות לגיוס כספים לטובת ה \" מרכז\nלעניני חינוך \" ו \" צעירי אגודת חב \" ד \" ( מהעתקה , באדיבות מערכת הספר\nועבדי דוד :])\"\"\nנת ' ות \" ח\nודבר בעתו –\nבסמיכות לי \" ב - י \" ג תמוז\nאזכיר עה \" צ\nקצ\nתמוז ][\nמענה להשליח הרב יוסף העכט שכתב שהיות שנפתחה לאחרונה בעירו\nאילת קונסלי ' מצרית המטפלת בבקשות לביקור במצרים , אולי כדאי\nלנצל זאת לשיחה עם הקונסול ע \" ד אפשרות הדפסת ס ' התניא בקהיר"],[9200210102,"102\nמענות קודש – ה ' תשמ \" ב\nובאלכסנדריא , שני ערי מצרים שבהם יש קהילה יהודית גדולה ( תשורה\nהעכט כ \" ט אדר תשס \" ב :)\nהו \" ל של התניא בקהיר ובאלכסנדריא נכון במאוד מאד . לכאורה הייתה\nצריכה להיות הכנה מתאימה של הקונסול שבעירו קודם שידברו איתו\nרשמית ושלא יחשוש שיש בזה משהו נסתר וכו ' ובטח ישנם כמה שהם\nביחסי ידידות איתו יסבירוהו גודל העיר שפעל בה הרמב \" ם , שדר בה\nוכו .'\n[ וראה לקמן מענה ר מב ליקוט מענות קודש תשמ \" ג מענות לא , קלא ,.\nקלג . תשד \" מ מענה רז .]\nקצא\nתמוז ][\nמענה להשליח ר ' מנחם מענדל חיים ברוך הלוי וולפא על מכתבו בו ביקש\nברכה בקשר ליום הולדתו , בצירוף בקשות ברכה של אנ \" ש ומקורבים\nבעירו נתני ' אה \" ק ( תשורה גליצנשטיין ט ' תמוז תשע \" ד :)\nאזכיר עה \" צ כאו \" א שי ' להמצטרך ולבשו \" ט\nקצב\nכ \" ב תמוז ][\nמענה למערכת \" ספר הליקוטים – דא \" ח צמח צדק \" שכתבו : \" בקשר\nלהוראת כ \" ק אדמו \" ר שליט \" א לערוך השלמה לספר הליקוטים – מספרי\nדא \" ח דהצ \" צ שיצאו לאור לאחרי הדפסת החלקים הראשונים דסה \" ל –\nמצו \" ב השלמה זו . .\" ( מצילום כתי \" ק – \" לקט מענות קודש בקשר\nלהדפסת ספר הליקוטים דא \" ח צמ ח צדק \" ע ' 43 :)\n[1 ] במכתבם כתבו : \" ההשלמה כוללת הוספות לערכים דאותיות מ \" ם ( מ\n– מצורע ), נו \" ן – תי \" ו .\"\nעל התיבות : \"( מ – מצורע )\", כתב :\nהאין בנתים עוד – עד נו \" ן ?\n[2 ] במכתבם כתבו : \" שנלקטו מביאורי הזהר כרך ב '. ומאוה \" ת דברים\nכרך ה ' ( להערכים דאותיות שי \" ן – תי \" ו .\")"],[9200210103,"103\nמענות קודש – ה ' תשמ \" ב\nסימן בעיגול את התיבות : \" מביאורי הזהר כרך ב '. ומאוה \" ת דברים כרך\nה '\", וכתב :\nרק זה נדפס מאז ?\nובפרט נוסף בנוגע לאות ת , ש , ר כו '\nבאם עוד – צריך לצרפם\n[3 ] במכתבם כתבו : \" ובסוף ההשלמה יבואו : א ) לוח התיקון לכל\nהכרכים דספר הליקוטים . ב ) רשימת ראשי תיבות שבסה \" ל .\"\nעל התיבות : \" ובסוף ההשלמה \", כתב :\nכדאי להוסיף לוח ( רשימת ) הערכים שבכל הכרכים\nכולל גם דהנמצא בדפוס : א - ג\n[4 ] במכתבם כתבו : \" השלמה זו – הכוללת לערך 250-300 עמודים –\nיודפס בכרך בפ \" ע , ואולי בשם : \" ספר הליקוטים – דא \" ח צ \" צ –\nמילואים \". האם נכון לעשות כן .\"?\nכ \" ק אדמו \" ר שליט \" א מחק תיבת \" האם \", וכתב :\nנכון לעשות כן ][ ולהתחיל תיכף במילואים לשאר האותיות\nקצ ג\nכ \" ב תמוז ][\nמענה למערכת \" ספר הליקוטים – דא \" ח צמח צדק \" על מכתבם בהמשך\nלהמענה שקיבלו . בין השאר כתבו : \" שאר ספרי דא \" ח דהצ \" צ ( שיו \" ל עד\nעתה ) נכללו בכל הכרכים דסה \" ל ( אותיות ת , ש , וכו '), כולל גם : א )\nמקומות בספרי דא \" ח דהצ \" צ שאינן מצוינות בהמפתחות לספרי דא \" ח\nדהצ \" צ ; ב ) הספרי דא \" ח דהצ \" צ שלא היו להם מפתחות כלל \" ( מצילום\nכתי \" ק – \" לקט מענות קודש בקשר להדפסת ספר הליקוטים דא \" ח צמח\nצדק \" ע ' 44 :)\nכ \" ק אדמו \" ר שליט \" א סימן קו תחת התיבות : \" מקומות . . שאינן\nמצוינות בהמפתחות \", וכתב :\nהפי ?'"],[9200210104,"104\nמענות קודש – ה ' תשמ \" ב\nקצ ד\nלאחר ש \" פ מטו \" מ , כ \" ו תמוז ][\nמענה ל \" ועד הנחות התמימים \" על מכתבם בקשר להמדובר בהתועדות\nש \" פ מטו \" מ : \" בנוגע למה שדובר ע \" ד יום כ \" ו תמוז ( הקביעות דש \" מ\nמנ \" א ש . ז ). – אם יש להעיר מ \" התמים \" חוברת ו ' ע ' כד יש שני מכתבים\nמהבעש \" ט ותלמידיו , שביום זה נצחו את הפראנקיסטן ולכן \" קבלנו\nעלינו ועל זרענו . . מעתה ועד עולם לעשות יום זה יום טוב יום משתה\nושמחה \"\" ( מצילום כתי \" ק – \" יחי המלך \" גליון שכ . התועדויות תשמ \" ב\nח \" ד ע ' 1909 :)\n[ יש שני מכתבים ] 1 מכו ') 2 ) מכ \" ז – למחרתו עוה \" פ ! וההוספה\nבהראשון מיום ה ' בהשני יום א ' שלפניו . ועוד ועיקר : הקביעות דכ \" ו\nתמוז אז ( תקי \" ט ) הי ' בש \" ק !\nקצ ה\nלאחר ש \" פ מטו \" מ , כ \" ו תמוז ][\nמענה להסופר ר ' אליעזר צבי זאב צירקינד ( מצילום כתי \" ק – \" בית\nמשיח \" גליון 174 תשורה צירקינד כ \" ח מנ \" א תשע \" ה :).\nעל מה שכתב ע \" ד ס \" ת הכללי השלישי של ישיבת תו \" ת המרכזית ,\nשעוסק בכתיבתו , ועומד עתה בחומש דברים – כתב :\nנת ' ( והמצו \" ב ) ות \" ח על הבשו \" ט . ( 1)\nחומש דברים – שהזמ \" ג . ובודאי יסויים כמוכרז ליום דיו \" ט לישראל\nכו ' כמפורסם . ( 2 )\nעל מה שכתב ע \" ד המדובר בהתועדות ש \" פ מטו \" מ בקשר לצורת קני\nהמנורה , וצירף את הספר \" מעשה חושב \" שכתב עד \" ז – כתב :\nבנוגע לצורת קני המנורה – ודעת בעהמ \" ס מ \" ח :\nבעצמו כותב יסודותיו 1 ) אף שדעת רש \" י באלכסון , 2 ) מדלא הזכיר\nהרמב \" ם זה בחיבורו ( וכן לא בברייתא דמלהמ \" ש ובש \" ס ) \" כתב בעל\nחכמת המשכן ( מקובל וכו )' שנראה \" שהיו \" כמעט בעיגול \" \" והכי\nמסתברא \" ( שעי \" ז דומים לגלגלי הרקיע ."],[9200210105,"105\nמענות קודש – ה ' תשמ \" ב\nלאחרי שנמצא כתי \" ק פיה \" מ להרמבם ובו ציורו באלכסון ובפי ' בנו\nעה \" ת שהרמב \" ם צייר \" ביושר כו ' לא בעיגול כמו שצייר אותה זולתו \"\nבודאי כשבטל היסוד כו .'\nבכלל לא זכיתי לפענ \" ד להבין כלל וכלל הראי ' דמדסתים נראה שהי '\nכמעט בעיגול \"\" – שהרי תיבת \" קנה \" מובאה בכו \" כ מקומות בתושב \" כ\nובכ \" מ מוכרח שהוא קו ישר ואין אף פ \" א שמוכרח שזהו באופן אחר ..\nודעת הראב \" ע ( תצוה כז , כא ) [ וי \" מ כן דעת הספרי זוטא ] צ \" ע מקורו .\nוראה תו \" ש סוף כרך כב דש \" נ .\n___\nהס ' ישנו בספרי ' ולכן מצו \" ב .\nקצ ו\nלאחר ש \" פ מטו \" מ , כ \" ו תמוז ][\nמענה להרב שמואל פסח באגאמילסקי על שאלותיו בהמדובר בהתועדות\nש \" פ מטו \" מ – שנתבאר ש הטעם שכתב הרמב \" ם ( הלכות בית הבחירה\nפ \" ג ה \" א ) \" המנורה מפורשת צורתה בתורה \", הוא דבא להשמיענו הלכה\nדלא חל על זה דין זקן ממרא , מכיון שהאומר היפך מש \" כ בתורה שבכתב\nאין לו דין זקן ממרא ( קובץ הערות התמימים ואנ \" ש מאריסטאון ש \" פ\nתרומה , ש \" פ תצוה , וש \" פ ויק \" פ – תשמ \" ג ( גל יונות רצט , ש , שב :))\n[1 ] במכתבו שאל דלפי ביאור זה מדוע כתב הרמב \" ם ד \" מפורשת צורתה\nבתורה \" דוקא בנוגע להמנורה , ולא כתב עד \" ז בנוגע להשלחן וכו .'\nמענה כ \" ק אדמו \" ר שליט \" א :\n– כמדובר ובכ \" פ – הפשוט ביותר אין שמים לב לזה : [ ולא כתב עד \" ז\nבנוגע להשלחן וכו ]' כי אינם מפורשים ( צורתם ) בתורה .\n[2 ] במכתבו שאל מדוע הוצרך הרמב \" ם לכתוב \" המנורה מפורשת צורתה\nבתורה \" בכדי לאשמועינן שלא חל על זה דין זקן ממרא , והרי זה ידוע\nלכל ד \" מפורשת צורתה בתורה \", וכיון דידעינן הכלל שעל דין המפורש\nבתורה ליכא דין זקן ממרא , במילא ידעינן שלא חל על המנורה דין של\nזקן ממרא .\nכ \" ק אדמו \" ר שליט \" א סימן קו תחת התיבות \" זה ידוע לכל \", \" דידעינן\nהכלל \", \" במילא ידעינן \", וכתב :"],[9200210106,"106\nמענות קודש – ה ' תשמ \" ב\nעפי \" ז הול \" ל להשמיט ( הרמב \" ם ) ריבוי ענינים בספרו !\n[3 ] במכתבו שאל דלכאורה בכל אופן אין חל בנוגע המנורה דין זקן\nממרא , גם לולי ש \" מפורשת צורתה בתורה \", כיון ש \" אין זקן ממרא חייב\nמיתה עד . . ( ש ) יחלוק על בית דין הגדול בדבר שזדונו כרת ושגגתו חטאת\nאו בתפלין \" ( רמב \" ם הלכות ממרים פ \" ג ה \" ה .)\nמענה כ \" ק אדמו \" ר שליט \" א :\nהרי אמרתי גדר דין של זקן ממרא ולא \" עונש \" וכיו \" ב .\n[4 ] במכתבו כתב שאולי יש לבאר בדוחק עכ \" פ כוונת הרמב \" ם במש \" כ\nהמנורה מפורשת צורתה בתורה \", דבמנורה , אף אם חסר רק מ \" ציור \"\"\nהמנורה ה \" ז מעכב אף בדיעבד .\nכ \" ק אדמו \" ר שליט \" א סימן בעיגול את התיבות \" לבאר בדוחק \", וכתב :\nלמה יכניס עצמו לדוחק !!\n[5 על כללות המכתב , כתב :]\nכדרכי כ \" פ – איני מזכיר זה שתקותי שכאו \" א יבין מעצמו : ובנדו \" ד\nהרמב \" ם מדגיש חידוש גדול במנורה צורתה מפורשת בתורה ובכ \" ז )(\nבד \" א כו ' ( ה \" ד ) ( כמובן ע \" ע אף אחד לא העיר עד \" ז .)\nקצ ז\nר \" ח מנ \" א ][\nמענה להשליח ר ' חיים יהודה ג ' ייקובס ( לקו \" ש חכ \" ג ע ' 476-7 . \" בית\nמשיח \" גליון 67 :)\nכותב שב \" ה כל הענינים גיין מיט הצלחה ורואים ישועת השם בכל רגע .\nובמכ ' של טו \" ב ימים לאח \" ז – בהיפך מן הקצה אל הקצה ממש !\nובמענה עליו ( עכ \" פ בקיצור ): בבואם לגלסקו – התחילו \" מא \" ב \" בכל\nהענינים – עתה מצבם : ה ' ברכם בבנים ובנות שליט \" א הולכים בדרך\nהתומ \" צ מקור לנח \" ר אמתי רב . יש להם בית משלהם , הקימו בעיר\nמוסדות וכו ' עד שנתהפכה למצב שאפילו אחרים הקימו שם כולל וכו ,'\nהפיצו שם כו \" כ מיליונים דעניני תומ \" צ , שמם מפורסם וחשובים הם\nאצל שלטונות העיר וכו ' ואפילו הגוים וכו .'"],[9200210107,"107\nמענות קודש – ה ' תשמ \" ב\nואחר כ \" ז שואלים למה ישנם כאלה שמקנאים אותם ( בלי עה \" ר )? והם\nמתאוננים שמזלם \" אינו טוב \" וכו !?'\nמצב הכספי – כו \" כ פעמים הי ' כיו \" ב וסו \" ס נסתדר , וגם עתה יהי ' כן\n– אלא שצ \" ל התייעצות בלונדון כמש \" כ וכמה פעמים , ועשי ' בדרך\nהטבע , ועוד ועיקר – בטחון בהשם .\nכמה גדול כל החובות לאחרי עבודה של ריבוי שנים ופעולות ?\nהקס \" ד \" המוזר \" – לעזוב , ר \" ל , כהנ \" ל ולהתחיל מחדש ומא \" ב\nבמק \" א ? האומנם זהו ענין הזקוק למענה ?\nכמובן ופשוט צ \" ל תפלה להשם למלאות כל הצרכים ומידו המלאה כו ,'\nתפלה עוה \" פ ועוה \" פ , אבל ופשוט שביחד עם זה צ \" ל הקדמת תודה על\nחסדיו המרובים שאחת תוצאותיהם – שמחה אמתית וגם דנפה \" ב .\nיקבל גמ \" ח ( לשלמו לא יאוחר מסוף ג ' שנים ) ע \" ס אלף לירות דאנגליא\nלכיסוי החובות .\nאזכיר עה \" צ ויבש \" ט .\nקצ ח\nה ' מנ \" א ][\nמענה להשליח ר ' מנחם מענדל חיים ברוך הלוי וולפא על דו \" ח שכתב\nמביקורו במאנטרעאל למען המוסדות בנתני ', בו כתב : \" בשבוע שעבר\nהייתי במונטריאול וב \" ה הצלחתי \" ( תשורה גליצנשטיין ט ' תמוז תשע \" ד .\nתשורה וולפא י \" ט טבת תשע \" ט :)\nכ \" ק אדמו \" ר שליט \" א סימן קו תחת התיבות \" וב \" ה הצלחתי \", וכתב :\nואזכיר עה \" צ שתומשך הצלחתו בכ \" ז\nקצ ט\nתחלת מנ \" א ][\nמענה כללי - פרטי דימים אלו [ בין השאר : ( 1 ) להרב דוד ראסקין על דו \" ח\nמאסיפת הנהלת ישיבת תו \" ת המרכזית בקשר לתכנית מעמד סיום ס \" ת\nהכללי השלישי שלהם ( תדפיס מספר \" ועבדי דוד \" – ס \" ת הכלליים שע \" י\nתו \" ת המרכזית – ע ' 68 ;) ( 2 ) להנהלת \" צעירי אגודת חב \" ד \" המרכזית על"],[9200210108,"108\nמענות קודש – ה ' תשמ \" ב\nרשימת המקומות אליהם צלצלו לעורר ע \" ד : הו \" ל קובצי חידושי תורה ,\nלימוד הלכות בית הבחירה , עריכת \" סיומים \" בתשעת הימים ,\nוהשתדלות יתרה ברישום בס \" ת הכלליים ( מהעתקה , באדיבות מערכת\nהספר \" ועבדי דוד ;)\" ( 3 ) להת ' שמואל מנחם מענדל גרוזמן על דו \" ח\nמ \" מבצעים \" שערכו בשבועות הא חרונים במסגרת ביקורי בית\nמהעתקה , באדיבות הנמען שי :])'(\nנת ' ות \" ח .\nודבר בעתו –\nבסמיכות לחמשה עשר באב\n– קיימא סיהרא באשלמותא –\nולא היו יו \" ט לישראל כטו באב כו .'\nאזכיר עה \" צ .\nר\nתחלת מנ \" א ][\nמענה לר ' אפרים וואלף על מכתבו בקשר להאלבום מכינוס נשי ובנות\nחב \" ד באה \" ק שמו \" ל ע \" פ הוראות כ \" ק אדמו \" ר שליט \" א ( ס ' \" ימי\nתמימים \" ח \" ח ע ' 148 , 150 :)\nכמדומה שעניתי מאז שצריך להיות בהגה \" ה מעולה ( ועוד הסתייגויות\nמכיוון שהאחריות מרובה , צע \" ג אם מקה \" ת .)\nבכל אופן לבקש העתק מדוייק מכל ההוראות שנמסרו מקודם ובפירוט\nמה נעשה .\nרא\nתחלת מנ \" א ][\n\" צעטל \" בכתי \" ק שכתב כ \" ק אדמו \" ר שליט \" א לר ' שלום הלוי דוכמאן\nחבר הנהלת \" כולל חב \" ד \" (\" כפר חב \" ד \" גליון 1678 :)\nזה עתה קיבלתי פתקה עם בקשת ברכה עבור נסיעת .[ ]. בענייני הכולל\nלטורונטו . היש טעם שהוא אינו נוסע בעצמו ?\n[ וראה לקמן מענות רב , ר ג ליקוט מענות קודש תשמ \" ג מענה ד .]."],[9200210109,"109\nמענות קודש – ה ' תשמ \" ב\nרב\nו ' מנ \" א ][\nמענה לר ' שלום הלוי דוכמאן על מכתבו – בהמשך להמענה שקיבל – בו\nכתב :\n\" הנני לברר לכ \" ק אדמו \" ר שליט \" א למה נסע הרב . . לטורונטו ולבופעלא\nלטובת הכולל ולא אני בעצמי .\nהנסיעה הי ' נסיעה טכנית לסדר ענינים טכניים ביותר וכו ' וכמו \" כ לראות\nמקרוב איך הולך הענין של העמדת הקופות של הכולל בטורונטו והיות\nשר ' . . הוא הממונה בענינים אלה וכו ' של העמדת קופות וכו ' ובכן חשבתי\nשכדאי שהוא יסע לשם .\nעד \" ז בבופעלא שעוברים שם בדרך לטורונטו יש הזדמנות להתחיל שם\nהענין של הפצת הקופות ור ' . . אמר כשהי ' כאן לאחרונה שיש מקום לזה\nוכו ' והוא יעזור בזה וכו ' והיות שר ' . . הוא הממונה בענינים אלה וכו '\nובכן חשבתי שכדאי שהוא יסע לשם .\nמובן שכל הנעשה שם הרי \" ז בידיעתי ובהסכמתי . .\nהאם כדאי שאני יסע לשם בעצמי היום ? כדי לסדר בעצמי כהנ \" ל .\"\nמענה כ \" ק אדמו \" ר שליט \" א (\" כפר חב \" ד \" גליון 1678 :)\n[1 סימן קו תחת התיבות : \" הוא הממונה בענינים אלה וכו ' של העמדת ,\"]\n\" הענין של הפצת הקופות \", \" מובן שכל הנעשה שם הרי \" ז בידיעתי\nובהסכמתי \"; ועל מה שכתב : \" האם כדאי שאני יסע לשם בעצמי היום ?\nכדי לסדר בעצמי כהנ \" ל \" – כתב :\nהרי כבר נסע הנ \" ל ובהסכמתו ובשליחותו ולמה יקח מכספי הכולל גם\nעל נסיעת איש מנ . י !?.\n[2 סימן בעיגול את חתימת הנמען , וכתב :]\nמטובו לשלוח דו \" ח מפעולותיו הוא – במשך חודש תמוז\nות \" ח מראש"],[9200210110,"110\nמענות קודש – ה ' תשמ \" ב\nרג\nח ' מנ \" א ][\nמענה לר ' שלום הלוי דוכמאן שהכניס – בהמשך להמענה שקיבל – דו \" ח\nכספי ממשך חודש תמוז ( מצילום כתי \" ק – \" כפר חב \" ד \" גליון 1678 :)\n[1 ] על מה שכתב ע \" ד משכורת שני עובדים – כתב :\nהאומנם הכנסות הכולל גדולות ומסובכות כ \" כ , שמכריחות פעולות\nדשני משרות ושלימות !?\nמהו סדר פעולות דהיום – דשני אלה ?\n[2 ] על מה שכתב ע \" ד משכורת עובדת , שני מזכירות , ועובד – סימן בעיגול\nאת שם העובדת , תיבות \" מזכירה . . מזכירה \", ותיבות \" עבודה במשרד \"\n– וכתב :\nפעולתה – נוסף על שני הנ \" ל ושני מזכירות ועובד\n[3 ] על מה שכתב ע \" ד הוצאות משרד הכולל , שבו חמשה חדרים – כתב :\nמה עושה משרד דמוסד ב חמשה חדרים וכו ]'[\nכמה חדרים במשרד המלח , בי \" ר וכיו \" ב\n[4 על כללות הדו \" ח , כתב :]\nכו \" כ כוללים בניו יארק\nהַחקר להנהגתם בכ \" ז ?\nרד\nי \" ב מנ \" א ][\nמענה לר ' חיים הלוי בנימיני על מכתבו בעניני ישיבת \" מחנה ישראל \"\nבפטרופוליס ברזיל ( ס ' \" ישיבה של מעלה \" ע ' 434-5 :)\n[1 במכתבו כתב :]\n\" בדרך הטבע נראים קשיים מסויימים – בעצם רגילים – השגת תלמידים\nותלמידות לישיבה ולמכללה , השגת תקציבים , יחס עם ההורים והציבור\nוכו ' וכו '. נוסף לכך גם צוות העובדים הלא יהודיים שעבדו בעבודות"],[9200210111,"111\nמענות קודש – ה ' תשמ \" ב\nטכניות ומזכירות , יוצאים בגלל זקנה וכו ' ונראה שעלינו להמשיך\nלהתמודד במצב מיוחד .\nאמנם תקוותנו חזקה בברכת כ \" ק אדמו \" ר שליט \" א ולנתינת כוח שנוכל\nלהמשיך וביתר שאת כמקדם בכל הפעולות החינוכיות על טהרת הקודש\nובעיקר הפצת המעיינות חוצה .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\n1 לחזק ולפתח ביתר שאת ועוז ..\n[2 במכתבו כתב :]\nיש תוכנית של ארגון שכונה מסביב לישיבה שזה ממש הכרח ,\"\nבפטרופוליס כמעט ואין משפחות יהודיות והישיבה נשארת עם כמה\nמשפחות המגידי שיעור 3 משפחות , והילדים אין להם חברת ילדים אע \" פ\nשיש כמין חדר ומנסים כמין גן אבל לזה צריכים ציבור ילדים יותר גדול .\nלכן זה זמן הנני חושב וגם תכננו בנין בתים משפחתיים מסביב לישיבה\nולנסות להביא אולי מהתלמידים שלמדו אי פעם ויכולים להקים\nמפעלים מסויימים בעיר פטרופוליס , שהיא השני ' בחרושת טכסטיל ועוד\nבבראזיל אחר העיר ס . פאולו , או אולי מורים יהודיים שיעבדו בהוראת\nהחלק התיכוני – כי עד היום עובדים רק לא יהודים כי אין לנו שם\nיהודים .\nכמו כן יש בהכנה פיתוח עבודת תלמידי ואולי גם מורי הישיבה בריו\nבבתי ספר היהודיים השונים ובשני המועדונים וכו '. לכל זה יש לנו צורך\nבנתינת כוח מאת כ \" ק אדמו \" ר שליט \" א ואז נלך לבטח דרכינו .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\n2 בכלל נכון במאד מאד . מאיזה סוג דבני ישראל וכו '. – להתחיל בהקל\nיותר בעתיד הקרוב ואח \" כ ירחיב וה ' יצליחו .\n[3 במכתבו כתב :]\n\" לכאורה בימים כאלה כאשר כל העולם עדים שמתרחש משהו שאין לו\nדוגמא בתולדות האנושות בעצם הנני מתבייש לבוא לפני ק ' כ \" ק אדמו \" ר\nשליט \" א עם ענינים של מה בכך של עוד כמה עשרות תלמידים ותלמידות\nוחדר וכו ', אמנם מי כמו כ \" ק אדמו \" ר שליט \" א יודע שקיום היהדות\nבמדינה ההיא תלו י ' גם בזה , ולכן הנני מבקש ברכת ק ' ונתינת כוח מאת\nכ \" ק אדמו \" ר שליט \" א שגם אנו נזכה להיות ממזכי הרבים של מחנכים\nלתורה הקדושה וקיום מצוותיה .\""],[9200210112,"112\nמענות קודש – ה ' תשמ \" ב\nעל מה שכתב : \" לבוא לפני ק ' כ \" ק אדמו \" ר שליט \" א עם ענינים של מה\nבכך של עוד כמה עשרות תלמידים ותלמידות \", כתב :\n3 שכל אחד מהם עולם מלא ..\n[4 על כללות המכתב , כתב :]\n4 מצו \" ב לצדקה ( החילוף ) שם ..\n5 נת ' ות \" ח ..\n6 אזכיר עה \" צ ..\nרה\nט \" ו מנ \" א ][\nמענה להרב דוד ראסקין על דו \" ח ממעמד סיום ס \" ת הכללי השלישי\nוהתחלת כתיבת ס \" ת הרביעי , שהתקיים ביום ד ' ט \" ו מנ \" א בבנין ישיבת\nחובבי תורה \" ( תדפיס מספר \" ועבדי דוד \"\" – ס \" ת הכלליים שע \" י תו \" ת\nהמרכזית – ע ' 74 :)\nנל ' והמצו \" ב ות \" ח\nוצירף את המענה כללי - פרטי דימים אלו ( לקמן מענה ר ז .)\nרו\nלאחר ט \" ו מנ \" א ][\nמענה לשאלה – בהמשך להמדובר בהתועדות ט \" ו מנ \" א בענין אמירת\n\" ותן טל ומטר \" במדינת אוסטרליא וכיו \" ב , שיש בזה תשובות מגדולי\nישראל לאמרו בחורף שלהם – ושאלו כיצד לנהוג בפועל ( קובץ הערות\nהתמימים ואנ \" ש מלבורן כ \" ף מנ \" א תשמ \" ב ( גליון י :))\nלא ישנו ממנהגם עד עתה כפשוט\nולא יתחילו ח \" ו וח \" ו במחלוקת חדשה\nוישקיעו מרצם במבצע אהבת ישראל"],[9200210113,"113\nמענות קודש – ה ' תשמ \" ב\nרז\nמנ \" א ][\nמענה כללי - פרטי דימים אלו [ בין השאר : ( 1 ) להרב דוד ראסקין על דו \" ח\nממעמד סיום ס \" ת הכללי השלישי והתחלת כתיבת ס \" ת הרביעי ,\nשהתקיים ביום ד ' ט \" ו מנ \" א בבנין ישיבת \" חובבי תורה \" ( תדפיס מספר\nועבדי דוד \"\" – ס \" ת הכלליים שע \" י תו \" ת המרכזית – ע ' 74 . וראה לעיל\nמענה ר ה ;) ( 2 ) להנהלת \" צעירי אגודת חב \" ד \" המרכזית על דו \" ח מלימוד\nברבים ב יום ההילולא כ \" ף מנ \" א ב \" תורת לוי יצחק \", ב \" ספריית לוי\nיצחק \" שע \" י צאגו \" ח ( מהעתקה , באדיבות מערכת הספר \" ועבדי דוד :])\"\nנת ' ות \" ח .\nודבר בעתו –\nבסמיכות לכף מנחם אב\nעיין תענית בסופה )(\nאזכיר עה \" צ\nרח\nמנ \" א ][\nמענה לר ' יוסף ישראל בלוי מנהל \" בית ספר למלאכה \" בכפר חב \" ד שכתב\nע \" ד 65 בוגרי בית הספר , שמתוכם 20 ממשיכים בצה \" ל בנח \" ל הדתי , ו -\n5 ממשיכים בישיבת חב \" ד בצפת עיה \" ק ( ס ' \" ימי תמימים \" ח \" ח ע ' 161 ,\nוהעתקה :)\nדהיינו 7.5% ימשיכו בחב \" ד !! אכן פחות משליש במסגרת דתית\nכלשהיא .\nרט\nמנ \" א ][\nמענה לה \" ארגון גג למוסדות חב \" ד באה \" ק \" שכתבו ע \" ד החלטתם – ע \" פ\nהצעת עו \" ד מסויים בניו יארק – לפתוח בניו יארק משרד של הארגון\nלמטרת גיוס כספים ( ס ' \" ימי תמימים \" ח \" ח ע ' 161 :)"],[9200210114,"114\nמענות קודש – ה ' תשמ \" ב\n( נוסף על שאין להם איש מסוגל לזה ) הרי \" ז מקום לסכסוכים תמידיים\nבהשגת גבול דהמוסדות כאן , תלונות אנשים וכו ', ולכן מופרך\nההתעניין ומוכן מי מהמחליטים שי ' לקחת ע \" ע האחריות משמו הטוב\nשל העו \" ד ? ההתעניין לכה \" פ – לברר הפתוח משרדו בשבת ויו \" ט ?\nרי\nמנ \" א ][\nמענה לר ' אפרים וואלף על מכתבו ( להמזכיר רחמ \" א חדקוב ), בו כתב :\n\" לשאלת כת \" ר שיחי ' מי נתן ההוראה להר \" י שי ' מונדשיין להתעסק\nבהוצאת הספר \" תורת חב \" ד \", לדברי הר \" י מונדשיין היה זה לאחר חג\nהשבועות בשנת תשל \" ז או תשל \" ח , כאשר כ \" ק אדמו \" ר שליט \" א ביקש\nמהאברכים שיו \" ל כתבי יד של אדמוה \" ז , התניא מהדו \" ק , וכן החלו\nלהו \" ל אז את ספרי הליקוטים , והתקשר כת \" ר שיחי ' טלפונית אל הר \" י\nמונדשיין והטיל עליו להתעסק בהו \" ל של הספר \" תורת חב \" ד \" וכמו \" כ\nבענין השו \" ע אדמוה \" ז , ומאז התחיל ר \" י מונדשיין להתעסק בזה , ולאחר\nמכן התקשר גם כת \" ר שיחי ' אליו לדעת מהתקדמות עבודתו \" ( ס ' \" ימי\nתמימים \" ח \" ח ע ' 147 , 161 :)\n[1 על מה שכתב : \" ומאז התחיל \", כתב :]\nהקרוב לגמר , או שקודם התחלה\n[2 על מה שכתב : \" ולאחר מכן התקשר גם כת \" ר שיחי ' אליו \", כתב :]\nהתקשרות דכו \" כ פעמים\nריא\nמנ \" א ][\nמענה לר ' אפרים וואלף שהכניס שאלת שידוך מסויים ( ס ' \" ימי תמימים \"\nח \" ח ע ' 151 :)\n[1 על עצם השידוך , כתב :]\nבאם החליטו שניהם לייסד ביתם על יסודי התורה והמצוות בחיי היום\nיום ויהא השידוך בשעה טובה ומוצלחת אזכיר על הציון ."],[9200210115,"115\nמענות קודש – ה ' תשמ \" ב\n[2] על שאלתם האם העובדה שהמדובר והמדוברת הם בני - דודים יש בה\nכדי למנוע השידוך – כ \" ק אדמו \" ר שליט \" א שלל שאלה זו , שאין בזה\nמניעה .\nר בי\nמנ \" א ][\nמענה להת ' חיים רפופורט על שאלתו בלקו \" ש ואתחנן שנה זו ( חכ \" ד ע '\n28 ואילך ) שנתבאר שיש שני אופנים ב בקשת מתנת חנם \"\" , ובזה נחלקו\nהמדרש רבה והספרי בפירוש \" ואתחנן :\" ( 1 ) אופן הבקשה – שאפ \" ל\nבתחנונים , או בתביעה ( ולאופן זה מבואר במד \" ר ;) ( 2 ) הסיבה שבגללה\nמבקש – שאפ \" ל מפני שמגיע לו , או במתנת חנם ( ולאופן זה מבואר\nבספרי .) ובהערה 28 : \" ואולי יש לומר , שב ' אופנים במתנת חנם\nהמבוארים בפנים , הם כנגד ב ' הבחי ' שבכתר : מצד חיצוניות הכתר\n( אריך ) שיש חשיבות לנבראים ועבודתם , הענין דמתנת חנם הוא רק\nבלשון המתפלל ; משא \" כ מצד פנימיות הכתר ( עתיק ) דכולא קמי ' כלא\nחשיב ממש , אפשר לבקש רק בתורת מתנת חנם באמת \". במכתבו כתב :\n\" לא זכיתי להבין , שהרי אם נאמר שגם האופן של בקשת מתנת חנם\nשבמדרש הרי הוא כנגד ספירת הכתר ( – חיצוניות הכתר ) קשה , שהרי\nכתר הוא למעלה מי ' ספירות – שהם כנגד הי ' לשונות של תפלה ( כמבואר\nבאוה \" ת הנסמן בההערה ) – וא \" כ איך יתאים זה עם המבואר בהשיחה\nשרק לפי הספרי איז ואתחנן \" ניט פון די לשונות של תפלה \" משא \" כ לפי\nהמדרש .\nואולי הכוונה ע \" פ המבואר בכ \" מ ש \" כשאין הדעת נמנה הכתר נמנה \" –\nומבואר בלקו \" ת שלח דף מ \" ט ובכ \" מ שהכוונה ל \" חיצוניות הכתר דהיינו\nהרצון נמנה בכלל י ' ספירות אבל בבחי ' פנימיות אין הכתר נמנה \" . .\nובענין זה – לכאו ' סותר להנ \" ל מכ \" מ מ \" ש בלקו \" ת פ ' בחוקותי ( מו , ג )\nשאפי ' בחי ' תחתונה שבכתר היא רק שורש לנאצלים ולמעלה\nמהספירות .\"\nמענה כ \" ק אדמו \" ר שליט \" א ( קובץ הערות התמימים ואנ \" ש מאריסטאון\nש \" פ עקב תשמ \" ב ( גליון רדע :))\nחיצוניות הכתר כמפורסם מקיף ( הקרוב ) ויתירה מזו – מתלבש בי \" ס .\nעדיפא מהנ \" ל הול \" ל : כל תפלה ה \" ז \" יהי רצון \" חדש – כתר , ובמילא\nמובן שצ \" ל באופן של כתר ( בכל מאדך .)"],[9200210116,"116\nמענות קודש – ה ' תשמ \" ב\nר יג\nמנ \" א ][\nמענה לר ' אהרן חיטריק על מכתבו בקשר לליקוט פירושים וכו ' לתניא\nשבעריכתו ( תשורה גראס ח ' תמוז תשע \" ט :)\nאמרו חז \" ל : יש לו מנה רוצה מאתיים הראה קונ סט – ואיפכא\nמסתברא , מליקוט – א לחבירו – מכפיל ההפסק שביניהם : באם ילך\nמחיל אל חיל בזה – יכנס לאלף השביעי ומתוך שמחה וזריזות וטוב לבב\nריד\nט \" ז מנ \" א ][\nמענה להנהלת \" צעירי אגודת חב \" ד \" המרכזית על מכתבם בקשר\nל \" ספריית לוי יצחק \" הממוקמת בקומה הראשונה של בנין \" ופרצת \"\nשברשות צאגו \" ח , שהציעו להם להכשיר את הקומה השני ' להרחבת\nהספרי ' ( מהעתקה . המענה מתפרסם בזה לראשונה באדיבות מערכת\nהספר \" ועבדי דוד \" וזכות הרבים תלוי ' ב הם :)\nכעצת מבינים דכהנ \" ל\nאזכיר עה \" צ\nר טו\nט \" ז מנ \" א ][\nמענה להרב דוד ראסקין שכתב שבמימון האחים ר ' אלתר אליעזר והת '\nיהושע ליין קונים \" מחשב \" חדש לשימוש \" ספריית לוי יצחק \", וביקש\nברכה עבורם ( תשורה ניו י \" ג מנ \" א תשע \" ט . והעתקה , באדיבות מערכת\nהספר \" ועבדי דוד :)\"\nאזכיר עה \" צ"],[9200210117,"117\nמענות קודש – ה ' תשמ \" ב\nרטז\n[ לאחר ש \" פ ראה , כ \" ה מנ \" א ( 1 ])\nמענה להרב יואל הכהן כהן על שאלותיו בהמדובר בהתועדות ש \" פ ראה\n( מצילום כתי \" ק – \" תחיינו \" גליון 6 ע ' 11 :)\nא . במכתבו כתב :\n\" בענין \" עלה ארי זה נבוכדנאצר כו ' על מנת שיבוא ארי - ה כו ' ויבנה\nאריאל \", נאמר בהשיחה שב \" עלה ארי כו '\" (\" עלה ארי מסובכו \") כתיב\nארי \" בלא ה '\" – כי בבית שני שנבנה לאחרי חורבן ב \" ר ( ע \" י \" עלה ארי זה\nנבוכדנאצר )\" חסרו ה ' דברים , משא \" כ בענין ד \" יבוא ארי - ה זה הקב \" ה ,\nדכתיב בי ' ארי ' שאג מי לא יירא \", כתיב \" ארי - ה \" בה ' – כי \" יבוא ארי - ה\nכו ' ויבנה אריאל \" קאי על ביהמ \" ק השלישי שבו יהיו הה ' דברים .\nלכאורה : בפסוק ( ירמי ' ד , ז ) נאמר \" עלה ארי - ה מסבכו \" – \" ארי - ה \" בה .'\nוגם הלשון בילקוט : \" עלה ארי - ה \" – בה '. ומהי הכוונה בשיחה .\"?\nמענה כ \" ק אדמו \" ר שליט \" א :\n[1 ] על מה שכתב : \" נאמר בהשיחה שב \" עלה ארי כו '\" (\" עלה ארי\nמסובכו \") כתיב \" ארי \" בלא ה '\", כתב :\nנאמר בהשיחה שב \" עלה ארי כו '\" (\" עלה ארי מסובכו ])\"[ לכאורה צ \" ל\nכתיב \" ארי \" בלא ה ]'[\n[2 סימן בעיגול את כל השאלה , וכתב :]\nנקודת הבי ': כשעלה נ \" נ להחריב כו ' הי ' צ \" ל \" חסר ( ה \" א ) כתיב \"\nבמכש \" כ מעפרון ( רש \" י ר \" פ ח \" ש ) –\nוי \" ל : חורבן נ \" נ פגע ביותר בה ' דברים , שאפילו הגאולה דגלות בבל לא\nגאלה אותם ולא חזרו – ולאום מלאום גו ', כשעלה מסובכו הי ' בכחו –\nה , להבנות מחורבן ( חסרון ) ה ' דביהמ \" ק\n___\nויומתק – עפמשנ \" ת באוה \" ת ( עה \" פ ארי ' שאג ) דארי ' אור י \" ה – עפ \" ז\nה ראשונה\nובלקו \" ת בענין דר \" ה בחל בשבת ( כהשתא ) – דבינה חסר כו '\n[ בקה \" י – ה ' דארי ' – ספי ' מלכות וג \" ז מתאים ע \" פ אוה \" ת לאיכה\nבתחלתו .]"],[9200210118,"118\nמענות קודש – ה ' תשמ \" ב\nבאדר \" נ נ \" ב ספמ \" ג : ארי ' בנערותו ארי בזקנותו . ובאחרונים י \" מ –\nמפני שבזקנותו נחלש .\nולהעיר מנער חסר ה ' עד דלא קבילת דכר ( זח \" ב לח , ב )\nלברר במדרש משלי ( באבער ?) כ , ב .\nב . במכתבו כתב :\n\" בענין מ \" ש בספרי גדולי ישראל מגליצי ' ש \" חמשה עשר באב \" בגימטריא\n\" לשנה טובה תכתב \", שנאמר על זה בהשיחה דהגם שהגימטריא אינו\nמתאים הרי העיקר שהענין הוא נכון – אולי יש איזה ט \" ס בספרים הנ \" ל ,\nוצ \" ל : חמשה עשר באב הוא בגימטריא \" כתיבה וחתימה טובה .\"\nוגימטריא זו היא בדיוק .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\n[3 על מה שכתב : \" בספרי גדולי ישראל מגליצי '\", כתב :]\nצ \" ל :\nמונקאטש ( דרכי חו \" ש סתרפ \" ד מס ' שערי ישכר )\n[4 מחק את מה שכתב : \"\" לשנה טובה תכתב \" . . הוא בגימטריא \", וכתב :]\n[ ש \" חמשה עשר באב \" בגימטריא ] [\" כתיבה וחתימה טובה \". וגימטריא זו\nהיא בדיוק ] – כמדומה כך נרשם כשנדבר עד \" ז לפני זמן\nרי ז\n[ לאחר ש \" פ ראה , כ \" ה מנ \" א ( 2 ])\nמענה ל \" ועד הנחות התמימים \" שכתבו :\n\" מצו \" ב חלק משיחת ש \" פ ראה – שנרשם ע \" פ מענה כ \" ק אדמו \" ר\nשליט \" א בכתי \" ק . האם נרשם נכון ? [ כ \" ק אדמו \" ר שליט \" א הגי ' את חלק\nהשיחה שצירפו ( צילום כתי \" ק – תחיינו \" דלקמן .])\"\nבמדרש משלי באבער כ , ב נמצא רק ההתחלה דהמאמר באדר \" נ ( נ \" ב )\nבנוגע להז ' שמות דארי ', אבל לא ההמשך \" ארי ' בנערותו , ארי בזקנותו .\"\nובהערת באבער למדרש משלי שם מעתיק באבער האדר \" נ ( נ \" ב ) עם\nההוספה דארי בזקנותו כו '. ואולי לציין בהערה אחר הציון לאדר \" נ\nשאדר \" נ הועתק ג \" כ בה ערה במדרש משלי באבער כ , ב ?"],[9200210119,"119\nמענות קודש – ה ' תשמ \" ב\nהענין דארי ' הוא \" אור י \" ה \" ( שכ ' באוה \" ת עה \" פ ארי ' שאג ) – כ ' ג \" כ\nבלקו \" ת אחרי כט , ב ( אבל לא בנוגע לנדו \" ד – ארי ' שאג כו '. כ \" א בקשר\nעם קרבנות בדמות ארי ' כו .\")'\nמענה כ \" ק אדמו \" ר שליט \" א ( מצילום כתי \" ק – \" תחיינו \" גליון 6 ע ' 14 :)\n[1 מחק את הקטע \" במדרש משלי באבער . . כ , ב .\"]\n[2 על מה שכתבו : \" הענין דארי ' הוא \" אור י \" ה \" ( שכ ' באוה \" ת עה \" פ ארי ']\nשאג ) – כ ' ג \" כ בלקו \" ת אחרי כו '\", כתב :\nמהיכא תיתא יעירו עד \" ז [ בלקו \" ת אחרי . ].\nריח\nלאחר ש \" פ ראה , כ \" ה מנ \" א ][\nמענה להמזכיר ריל \" ג על שאלתו בהמדובר בהתועדות ש \" פ ראה –\nשנתבאר פרש \" י עה \" פ ( ראה יב , כח ) \" שמור ושמעת את כל הדברים האלה\nאשר אנכי מצוך \" , \" שמור זו משנה , שאתה צריך לשמרה בבטנך שלא\nתשכח כענין שנאמר כי נעים כי תשמרם בבטנך כו ,\"' שכוונתו בזה לבאר\nשמש \" כ \" שמור \" קאי במיוחד על ה \" משנה \" דבי ' עסקינן , שהם מצ ו ת\nהקשורות עם הכניסה לארץ , ומכיון שמדובר בענין שיש בו \" נעימות \"\nמיוחדת צ \" ל בזה \" שמירה \" מיוחדת . במכתבו כתב :\nלהמבואר בפרש \" י שמור זו משנה וכו '\" – בפ ' ואתחנן ( ד , ו ): ושמרתם\nועשיתם ( וקאי על הפסוק לפני זה ): ראה למדתי אתכם חקים . . לעשות\nכן בקרב הארץ אשר אתם באים שמה לרשתה . ועל התיבה ושמרתם\nפרש \" י : זו משנה , ושם לא הביא כל האריכות שכתב בפ ' ראה , אעפ \" י שפ '\nואתחנן לפני ראה .\nב ) עפ \" י הכלל שרש \" י אינו סומך על הנאמר או נתבאר לאחרי זה ובפרט\nבספר אחר וכו ', למה לא הוסיף רש \" י כאן בבטנך בלבך .\"\nמענה כ \" ק אדמו \" ר שליט \" א ( מצילום כתי \" ק – תשורה גראנער ח ' כסלו\nתשע \" ד :)\nעל מה שכתב : \" עפ \" י הכלל שרש \" י אינו סומך על הנאמר או נתבאר\nלאחרי זה ובפרט בספר אחר וכו '\", כתב :\n– מלבד כשבעצמו על אתר מציין לשם"],[9200210120,"120\nמענות קודש – ה ' תשמ \" ב\nריט\nכ \" ו מנ \" א ][\nמענה להת ' דוד אבא מאצקין והת ' מנחם מענדל ראסקין – מקבוצה\nהראשונה דתלמידים השלוחים לישיבת ליובאוויטש קסבלנקה מרוקו –\nשכתבו : \" בהיות שזכינו להמשיך את שליחותנו במרוקו ( ע \" פ ההוראה\nשקיבלו ההנהלה ) הננו באנו לבקש הסכמת וברכת כ \" ק שליט \" א לזכות\nלנסוע לחודש תשרי להיות אצל כ \" ק שליט \" א . ומצד ההוראה שקבלנו\nאשתקד שלא יהי ' הפסק בשליחות הרי כמה בחורים נשארים בכאן\nבחדש תשרי עד שיגיעו השלוחים החדשים \" ( תשורה מאצקין כ \" ב אד \" ר\nתשע \" ט :)\nבטח דיברו בזה עם ההנהלה שעל אתר ולמה אין מזכירים חוו \" ד .\nאזכיר עה \" צ .\nרכ\nאור לער \" ח אלול ][\nמענה להשליח ר ' יצחק גאלדשטיין שכתב :\n\" אנו רוצים לבא לכ \" ק אדמו \" ר שליט \" א לתשרי הבעל \" ט . הרה \" ח א \" י\nשי ' גליק אמר שעלי לבקש מאת כ \" ק אדמו \" ר שליט \" א להסכמה וברכה\nלהנסיעה . .\nאם נקבל הסכמת וברכת כ \" ק אדמו \" ר שליט \" א , נוכל לקנות כרטיסים\nוכו ' ( יותר זול לפני 21 יום של הנסיעה ,)\nהגם שאין לנו כסף , נבקש ברכה שיהי ' בע \" ה . אבל אם התורה חס על\nממונם של ישראל ( געלט = \" בלאטע \") עאכו \" כ על נשמותיהם והחיות\nשמקבלים ומאספים בחגים אלו להיות בצל כ \" ק אדמו \" ר שליט \" א . .\nמיר ווילען זיין ביים רבי שליט \" א אנא .\"!\nמענה כ \" ק אדמו \" ר שליט \" א ( מצילום כתי \" ק – קונטרס ועד הנחות\nבלה \" ק ש \" פ תולדות תשע \" ח :)\n[1 ] על מה שכתב : \" הרה \" ח א \" י שי ' גליק אמר שעלי לבקש מאת כ \" ק\nאדמו \" ר שליט \" א להסכמה וברכה להנסיעה \", כתב :\nכמפורסם כהוראת הרה \" ח א \" י שי ' גליק ][ (1 )"],[9200210121,"121\nמענות קודש – ה ' תשמ \" ב\n[2 על מה שכתב : \" הגם שאין לנו כסף \"] – סימן בעיגול את התיבות \" שאין\nלנו כסף \", וכתב :\nא \" כ ה \" ז סימן ומהי השאלה !?\nוימשיכו בעבוה \" ק במקומם עתה , ובפרט שהמלך בשדה ולאח \" כ סגולת\nחודש תשרי כו ' ( 2)\n[3 ] על מה שכתב : \" אם התורה חס על ממונם של ישראל . . עאכו \" כ על\nנשמותיהם \" – סימן בעיגול תיבת \" נשמותיהם \", וכתב :\nמאין יודע איפוא טוב יותר להנשמה !? ( 3)\n[4 על מה שכתב : \" מיר ווילען זיין ביים רבי שליט \" א אנא \"!] – סימן\nבעיגול תיבות אלו , וכתב :\nהבעש \" ט אומר שכשיהודי חושב ע \" ד מאדריד הוא נמצא במדריד (3)\n[5 סימן בחץ את מספר הטלפון שציין הנמען .]\nרכא\nאור לבדר \" ח אלול ][\nמענה לא ' השלוחים על מכתבו ע \" ד המצב במקומו ( מהעתקה . המענה\nמתפרסם בזה לראשונה באדיבות א ' מאנ \" ש שי ' וזכות הרבים תלוי ' בו :)\nמפורסם שאין המזכיר ' עוסקת בד \" ת ופס \" ד\nשאין המזכירות עוסקת ביסוד מוסדות\nשאין המזכירות עוסקת בשליחות שלוחים\nבודאי ידוע גם לו כהנ \" ל ( וגם לאלה שנתנו לו אדרעס המזכירות –\nשהמזכירות תעזרוהו איך עליו להתנהג שאין בזה אלא מהתחמקות\nאחריות שלהם ואפי ' במקום חשש חורבן , ח \" ו , דמוסדות חינוך חב \" ד\nוד \" ל ), ואחזור עוד הפעם ועוד הפעם על מה שאמרתי כמה פעמים\n( והלואי שעכ \" פ עתה יספיק ): יאמר ברור לשולחיו כהנ \" ל ( יכול לאמר\nגם בשמי ) ויתדבר ביניהם מה לעשות . ואם צורך בד \" ת וכיוצא בזה –\nשייך לב \" ד רבני אנ \" ש שי ' ( ובפרט שכבר עסקו בזה )\nבאם יאמרו לו שהמזכירות הורה כך ובמילא יעשה כו \" כ – ה \" ז היפך –\nהכתוב ברור לעיל . וד \" ל ."],[9200210122,"122\nמענות קודש – ה ' תשמ \" ב\nרכב\n[ לאחר בדר \" ח אלול (1) ]\nמענה ל \" ועד הנחות התמימים \" על שאלתם בהמדובר בהתועדות אור\nלבדר \" ח אלול :\n\" בנוגע למה שנזכר בהשיחה שהסדר דנקודות בסידור תהלת ה ' צריך\nלהיות מלאופם ( וא \" ו ) קודם השורק ( ג ' נקודות באלכסון ), ע \" פ מ \" ש\nבפרדס ( שער הנקודות ), ולא כפי שנדפס ע \" ע בהסידור השורק לפני\nהמלאופם –\nבתקו \" ז ת \" ע קכט , סע \" א איתא : תשע נקודין אינון חד ( הוי ') בקמץ ,\nתניינא בפתח , תליתאה בצירי , רביעאה בסגול , חמישאה בשבא ,\nשתיתאה בחולם , שביעאה בחירק , חמינאה בשלש נקודות , תשיעאה\nבשורק ( וא \" ו ). ע \" כ . וא \" כ ה \" ז בדיוק כפי הסדר שנדפס עתה בסידור\nתהלת ה ' ( רק שבתקו \" ז לא מנה הג ' נקודות אחרונות ( מורכבים ), חטף\nקמץ , חטף פתח וחטף סגול .)\nולאידך , מה שנאמר בהשיחה הסדר ע \" פ הפרדס – הרי בלאה \" כ אין\nהסדר בהסידור כפי מ \" ש בפרדס :\nבתחלה כ ' הפרדס ( שם פ \" א ) שהנקודות מחולקים לה ' מלכים וד ' ( ה )'\nעבדים : שורק ( בוא \" ו ), חירק ( ביו \" ד ), צירי , חולם וקמץ – מלכים .\nוהעבדים הם – ( תחת חירק – חירק בלי יו \" ד ), תחת חולם – ש בא קמץ\n( ביחד ), תחת קמץ – פתח , תחת צירי – סגול , תחת שורק – שורק של ג '\nנקודות . ואח \" כ בא השבא – שהיא \" עבד ל עבדים \". ואח \" כ בא השבא\nפתח ושבא סגול .\nולפי \" ז צ \" ל הסדר שכ ' הפרדס אח \" כ ( בפרק זה ) – שהנקודות הן ט '\nפשוטות וג ' מורכבות , והסדר הוא : קמץ , פתח , צירי , סגול , שבא , שורק ,\nשרק וקוראי ' אותו קבוץ שפתים ( היינו של ג ' נקודות באלכסון ), חולם ,\nחירק ( ע \" כ הט ' פשוטות ). ואח \" כ ג ' מורכבות – שבא קמץ , שבא פתח ,\nשבא סגול – אינו כהסדר בהסידור , שהחולם והחירק באים תיכף אחר\nהשבא .\nועיקר : גם את \" ל שלפי ביאור הפרדס צ \" ל כהסדר שנת ' בההתוועדות\nהכל כפי שנדפס בהסידור , רק לשנות הסדר דשורק ומלאופם )( – מ \" מ ,\nמכיון שבתקו \" ז מפורש כהסדר שנדפס בהסידור , מהו הדיוק לשנות\nמהסדר שבתקו \" ז לסדר הנ \" ל .\"?"],[9200210123,"123\nמענות קודש – ה ' תשמ \" ב\nמענה כ \" ק אדמו \" ר שליט \" א ( מצילו ם כתי \" ק – נדפס לעיל . המענה\nמתפרסם בזה לראשונה באדיבות ר ' שניאור זלמן יצחק יהושע שי ' חאנין\nוזכות הרבים תלוי ' בו :)\n[1 ] על מה שכתבו : \" בנוגע למה שנזכר בהשיחה שהסדר דנקודות בסידור\nתהלת ה ' צריך להיות מלאופם ( וא \" ו ) קודם השורק ( ג ' נקודות באלכסון ,)\nע \" פ מ \" ש בפרדס ( שער הנקודות )\", כתב :\nבתחלתו בנוגע למלכים ועבדים – ( תנועות גדולות וקטנות – כאו \" א למלך\nשלו )\n[2 על מה שכתבו : \" בתקו \" ז ת \" ע קכט , סע \" א איתא כו '\", כתב :]\nכמדומה הזכרתי בפי ' שמדובר עד \" ז בתקו \" ז\n[3 ] על מה שכתבו : \" רק שבתקו \" ז לא מנה הג ' נקודות אחרונות\nמורכבים ), חטף קמץ , חטף פתח וחטף סגול \", כתב :(\nכי אינם כלל – ביו \" ד הנ \" ל\n[4 סימן בעיגול את מה שכתבו :] \" ועיקר : גם את \" ל שלפי ביאור הפרדס\nצ \" ל כהסדר שנת ' בההתוועדות ( הכל כפי שנדפס בהסידור , רק לשנות\nהסדר דשורק ומלאופם ) – מ \" מ , מכיון שבתקו \" ז מפורש כהסדר שנדפס\nבהסידור , מהו הדיוק לשנות מהסדר שבתקו \" ז לסדר הנ \" ל ?\", וכתב :\n(3 ) תוכן ה \" קושיא \": תמורת ( סדר ) הא \" ב ע \" פ פשט והברת הנקודות\nתיכף משמתחיל לדבר ב ' שנים לערך )( –\nלסדרו ע \" פ קבלה ( כיון . . שספירת ההוד קודמת – ליסוד ) – היפך\nההברה והדקדוק וכו !!'\nובסידור השווה לכל נפש וגם בטבלת א \" ב ללומדי א \" ב !!\nרכג\n[ לאחר בדר \" ח אלול (2) ]\nמענה ל \" ועד הנחות התמימים \" שכתבו :\nבהמשך למה שכתבנו ביום ועש \" ק בנוגע לסדר הנקודות ( מתקו \" ז וכו )'\"\n–"],[9200210124,"124\nמענות קודש – ה ' תשמ \" ב\nבערה \" כ ( לבעל סדה \" ד ) ערך נקודות ובקה \" י ערך נקודות התורה – הסדר\nהוא כבתקו \" ז וכפי שנדפס בסידור תהלת ה .'\nבע \" ח שאר דרושי הנקודות פ \" א הסדר הוא : קמץ , פתח , צירי , סגול ,\nשבא , חולם , שורק , חירק [ כנראה מלמעלמ \" ט : חולם – נקודה למעלה\nמהוא \" ו , שורק – באמצע הוא \" ו , חירק – למטה מהאות . כמו שמבאר שם\nלאח \" ז ובפ \" ג . ולא מצאנו שם ביאור בשאר פרטי הנקודות ], קיבוץ .\nאבל שם פ \" ו ( בציור אות אל \" ף עם נקודות ) הסדר הוא כבתקו \" ז ( וכפי\nשנדפס בסידור ) עם שינוי א ' – החירק בא בין השבא והחולם .\"\nמענה כ \" ק אדמו \" ר שליט \" א ( מצילו ם כתי \" ק – נדפס לעיל . המענה\nמתפרסם בזה לראשונה באדיבות ר ' שניאור זלמן יצחק יהושע שי ' חאנין\nוזכות הרבים תלוי ' בו :)\n(4 ) לאחרי כל השקו \" ט – דוקא תקו \" ז קלה , ב , ובעיקר – שערי זוהר\n( למרגלית ) לנדרים נשמטו מהם אף ששם נאספו כו !'\nרכד\n[ לאחר בדר \" ח אלול ( 3 ])\nמענה ל \" ועד הנחות התמימים \" שכתבו :\n\" מצו \" ב חלק מהשיחה ( דאור לבדר \" ח אלול ) ע \" ד סדר הנקודות – שנרשם\nע \" פ מענה כ \" ק אדמו \" ר שליט \" א . האם נרשם נכון ?\nעדיין צריך ביאור מדוע השבא בא ( בהסידור ) בין המלכים ועבדים ,\nתנועות גדולות וקטנות ( בין הסגול והחולם ), דלכאורה הרי השבא ( ע \" פ\nהברה ע \" ד הפשט ) הוא בלי תנועה כלל ( כפי שנזכר בהשיחה ) וצריך לבוא\nאחרי המלכים ועבדים , היינו לפני החטף קמץ .\"?\nמענה כ \" ק אדמו \" ר שליט \" א ( מצילום כתי \" ק – \" צדי \" ק למלך \" חוברת א\nע ' 140 :)\nההתחלה הייתה באופן דהוק אפ –\nובל \" נ – ההמשך ג \" כ \" \" \" ( אור לחי אלול )?"],[9200210125,"125\nמענות קודש – ה ' תשמ \" ב\nרכ ה\nח ' אלול ][\nמענה לא ' התמימים שכתב : \" הנני מבקש מכ \" ק אדמו \" ר שליט \" א עצה\nוברכה בנוגע ללימודי בשנה הבאה , שנת ה ' תשמ \" ג \" ( מצילום כתי \" ק –\n\" כפר חב \" ד \" גליון 1001 :)\nכמפורסם – כעצת ההנהלה דהמקום בו למד ע \" ע\nרכ ו\nאלול ][\nמענה כללי - פרטי דימים אלו [ בין השאר : ( 1 ) להנהלת \" צעירי אגודת\nחב \" ד \" המרכזית על רשימת המתנדבים ב \" מבצע חינוך \" ( מהעתקה ,\nבאדיבות מערכת הספר \" ועבדי דוד ;)\" ( 2 ) לתלמידים השלוחים לישיבת\nליובאוויטש קסבלנקה מרוקו על דו \" ח ( מהעתקה , באדיבות מערכת\nהספר \" שליחות כהלכתה \" :])\nנת ' ות \" ח .\nודבר בעתו –\nבימים שהמלך בשדה ומקבל את כולם\nבסבר פנים יפות ומראה פנים שוחקות לכולם כו .'\nאזכיר עה \" צ .\nרכ ז\nאלול ][\nמענה למארגני כינוס רבני אנ \" ש בצפון אה \" ק (\" כפר חב \" ד \" גליון 67 :)\nאזכיר על הציון במיוחד"],[9200210126,"126\nמענות קודש – ה ' תשמ \" ב\nרכ ח\nאלול ][\nמענה לחברי \" כולל אברכים \" שע \" י המזכירות על מכתבם בהמשך\nלמאורע בלתי - רצוי שאירע (\" התקשרות \" גליון תקצט :)\nהתנהגות מתאימה לחברי הכולל\nולימוד כמתאים וכו '\nאזכיר עה \" צ .\nרכ ט\nאלול ][\nמענה לר ' מרדכי בארון שהכניס כרזה שהפיק לרגל יום הבהיר י \" א ניסן\nשמונים שנה , הכוללת את רבותינו נשיאינו עם קיצור תולדותיהם , עשרת\nהמבצעים , ועוד (\" בית משיח \" גליון 598 :)\nנת ' ות \" ח ת \" ח 1 רושם טוב וחזק וכו .') 2 ) אזכיר עה \" צ לכהנ \" ל\nולבשו \" ט . 3 ) במהדורא בתרא : והתגלותו – להשמיט הוא \" ו . הילולא\nדבעש \" ט – ו ' סיון . העתקת הכתוב בדניאל ותהילים חסר ? בהכתר\nלהשמיט התיבות \" זהב טהור \". נש \" ק להוסיף ויום - טוב . בתפילין של\nראש – קוים לסימון ד ' בתים .\nרל\nאלול ][\nמענה להנהלת \" צעירי אגודת חב \" ד \" המרכזית על דו \" ח ( בתאריך ח \" י\nאלול ) בו ציינו את רשימת המתנדבים ל \" מבצע חינוך \" ( מהעתקה ,\nבאדיבות מערכת הספר \" ועבדי דוד :)\"\n[ הרשימה ממבצע חינוך . ]. וב ' הרשימות המצו \" ב נת ' ות \" ח ובסמיכות\nל ח \" י אלול ]["],[9200210127,"127\nמענות קודש – ה ' תשמ \" ב\nר לא\nכ \" ף אלול ][\nמענה להנהלת \" צעירי אגודת חב \" ד \" המרכזית שכתבו – בקשר לההכנות\nלועידה השנתית שתתקיים בחול המועד סוכות – ע \" ד נואמים חדשים\nבועידה , וע \" ד הקדשת הועידה לנושאים : ( 1 ) זיכוי ואיחוד כל בנ \" י בס \" ת\nהכלליים ; ( 2 מבצע \" צבאות השם ;\") ( 3 ) הו \" ל קובצי חידושי תורה\n( מהעתקה . המענה מתפרסם בזה לראשונה באדיבות מערכת הספר\nועבדי דוד \" וזכות הרבים תלוי ' בהם :)\"\nכמפורסם שייך לההנהלה\nאזכיר עה \" צ להצלחה רבה\nרלב\nכ \" ב אלול ][\nמענה להרב דוד ראסקין על מכתבו בקשר להכנות ל \" דינר \" של ידידי\n\" צעירי אגודת חב \" ד \" המרכזית שתתקיים בחג החנוכה הבע \" ל\n( מהעתקה . המענה מתפרסם בזה לראשונה באדיבות מערכת הספר\n\" ועבדי דוד \" וזכות הרבים תלוי ' ב הם :)\nפנ \" נ\nאזכיר עה \" צ\nרלג\nלאחר ש \" פ נצו \" י , כ \" ג אלול ][\nמענה ל \" ועד הנחות התמימים \" על שאלתם בהמדובר בהתועדות ש \" פ\nנצו \" י :\n\" בההתועדות דש \" פ נצו \" י דובר בענין שגם מצות שכליות ( משפטים ) צריך\nלקיימם בדרך קבלת עול כמו חוקים , חוקה חקקתי גזירה גזרתי כו '. ואין\nסתירה לזה ממ \" ש הרמב \" ם ( שמונה פרקים פ \" ו – הובא גם בסהמ \" צ\nלהצ \" צ פד , ב ) דענין \" אפשי ואבי שבשמים גזר עלי \" הוא בחוקים דוקא ,\nמשא \" כ במצ ות שכליות צריך לומר אי אפשי – כי זהו בצדיק דוקא ,\nמשא \" כ בעל תשובה , מכיון שסורו רע אינו יכול לסמוך על מה שאינו"],[9200210128,"128\nמענות קודש – ה ' תשמ \" ב\nרוצה (\" אי אפשי \") בדברים הרעים להיותם רע מצד השכל , והעצה\nהיחידה צו באווארענען שלא יעשה אותם היא רק מצד זה שאבי\nשבשמים גזר עלי , קבלת עול . ונתבאר דמכיון דגם בצדיקים צ \" ל העבודה\nדתשובה , לאתבא צדיקיא בתיובתא , לכן גם בצדיקים צ \" ל גם הקיום\nדמשפטים מצד חוקה חקקתי גזירה גזרתי .\nלכאורה : בלקו \" ת ואתחנן ט , ד מובא מהמגיד דבע \" ת צריך שמירה\nמעולה שלא יחזור לסורו , והשמירה היא ש \" צ \" ל כל מיני רע ואיסורים\nמאוסים אצלו ושיאמר אי אפשי .\"\nמענה כ \" ק אדמו \" ר שליט \" א ( מצילום כתי \" ק – \" פרדס חב \" ד \" גליון 3 ע '\n30 :)\n[ העירותי כמה פעמים , וכנראה שאינו מספיק , ואע \" פ שבלא הערתי –\nג \" כ פשוט ]\nשבמילתא שבסברא שאומרים ונמצא כתוב ההיפך – אינו מספיק\nלשלול ה \" מילתא \" כ \" א צריך להפריך היסוד - הסברא ( ע \" י סברא\nאחרת )\nבבעל תשובה פשוט שיש כו \" כ דרגות , ועד לשלימותה – שאז נהפך\nסורו - טבעו . ובמילא בהנ \" ל גם הוא כצדיק מעיקרו ,\nוי \" ל שזהו ב ' הגירסאות לשנות טבע מדותיו או ( רק ) לשנות מדותיו\nהטבעיות ( גם אתכפיא מספיק )\nודרגא הכי פחותה [ מכיון שסורו רע אינו יכול לסמוך על מה שאינו רוצה\n(\" אי אפשי \") בדברים הרעים להיותם רע מצד השכל , והעצה היחידה צו\nבאווארענען שלא יעשה אותם היא רק מצד זה שאבי שבשמים גזר עלי ,\nקבלת עול ]\n[ ונתבאר דמכיון דגם בצדיקים צ \" ל העבודה דתשובה , לאתבא צדיקיא\nבתיובתא , לכן גם בצדיקים צ \" ל גם הקיום דמשפטים מצד חוקה חקקתי\nגזירה גזרתי ] ומצד שאינם מנוסים בנסיון צ \" ל התחלה בזהירות הכי\nגדולה מכיון שסורו רע אינו יכול לסמוך על מה שאינו רוצה (\" אי אפשי )\"[\nבדברים הרעים להיותם רק מצד השכל , והעצה היחידה צו באווארענען\nשלא יעשה אותם היא רק מצד זה שאבי שבשמים גזר עלי , קבלת עול ]\nובתכלית השלימות דהלאתבא שאינו שייך בכלל למדות אומר אפשי\nמפני אי שייכותו .\nהעירוני ז \" ע שיש הערה בנדו \" ד בס ' הה \" מ ( בהוספות )"],[9200210129,"129\nמענות קודש – ה ' תשמ \" ב\nרלד\nכ \" ט אלול , ערב ראש השנה ][\nמענה להרב דוד ראסקין על דו \" ח ( בתאריך י \" א אלול ) בו ציין את רשימת\nהמקומות אליהם צלצל לעוררם ע \" ד הו \" ל קובצי חידושי תורה ( מצילום\nכתי \" ק – נדפס לעיל . המענה מתפרסם בזה לראשונה באדיבות מערכת\nהספר \" ועבדי דוד \" וזכות הרבים תלוי ' בהם :)\nמהיר\nלציין הבפו \" מ דכהנ \" ל\nער \" ה תשמ \" ג\nרל ה\nקייץ ][\nמענה למנהל מוסד - חינוך בערי השדה על דו \" ח שכתב ( להמזכיר רחמ \" א\nחדקוב ) בו תיאר את היחס הבלתי - נסבל מאת השליח האיזורי אליו ואל\nהמורים במוסד , והקשיים הרבים שמערים בדרכם , המקשים עליהם\nלמלאות שליחותם ( ס ' \" שליחות כהלכתה \" ע ' 277 :)\nבאם אין לו חוזה המחזיק אותו שם , יכול להתעניין להצעות אחרות .\nרל ו\nקייץ ][\nמענה לר ' שלום דובער הלוי וולפא שכתב ע \" ד משפחת מקורבים שלו\nאשר האשה כמעט ואיבדה כליל את מאור עיני ', וכתב שרופאים מומחים\nטיפלו בה ולא הצליחו להציל הראי ', ואומרים שאין סיכוי שתוכל לראות\nאי - פעם ר \" ל (\" כפר חב \" ד \" גליון 104 :)\nעל כללות המכתב , כתב :\n1 הפ \" נ נתקבל ..\nסימן קו תחת התיבות \" ולא הצליחו \", וכתב :\n2 אם כן , יפנו למומחים גדולים יותר ( עפ \" י עצת רופא ידיד .)."],[9200210130,"130\nמענות קודש – ה ' תשמ \" ב\nבדיקת התפילין והמזוזות .\n3 תשתדל בטעימה מיין קידוש דשבת ויום טוב ..\nאזכיר על הציון .\nרל ז\nקייץ ][\nמענה לרבני העיר מלבורן אוסטרליא (\" צדי \" ק למלך \" חוברת ז ע ' 226-7 .\nתשורה גארדאן ד ' תמוז תשע \" ג :)\nמפורסמת דעתי שבדורנו זה איש או ארגון שמתחשבים אתו העושה\nעירוב ויודע שסוף סוף יתפרסם הדבר – הרי זה תקלה איומה , כי אי\nאפשר שלא יארע שבת קודש אחד והעירוב פסול – וע \" פ טבע שיתרגלו\nפעמים אחדים בהוצאה בשבת קודש לא תועיל כל הכרזה והודעה\nשהעירוב נפסל ואסור וכו ' שיפ סיקו להוציא\nואין לעשות עירוב אלא בסודיות .\nרל ח\nקייץ ][\nמענה להשליח הרב יוסף העכט על מכתבו – בקשר לרעיון הדפסת ס '\nהתניא בערי מצרים ( ראה לעיל מענה ק צ ) – בו כתב ע \" ד תשובת הקונסול\nהמצרי שמסר את תשובת משרד החוץ המצרי שברצונם לראות את\nהספר המדובר , ולאחר שיראוהו יחליטו אם לאשר את ההדפסה . וכתב\nשלכאורה צריכים לשלוח את ס ' התניא עם תרגום , ושאל האם לשלוח\nעם תרגום אנגלי , או עם תרגום ערבי ( תשורה העכט כ \" ט אדר תשס \" ב :)\nכ \" ק אדמו \" ר שליט \" א סימן את התיבות \" תרגום ערבי \", וכתב :\nהרי \" ז רק בחלקו"],[9200210131,"131\nמענות קודש – ה ' תשמ \" ב\nרל ט\nקייץ ][\n\" צעטל \" בכתי \" ק שכתב כ \" ק אדמו \" ר שליט \" א בצירוף לחבילה ששלח\nהרב יעקב לנדא הכוללת צילומי תשובות שקיבל מאת הגאון מרוגצ ' וב\nז \" ל ( קובץ \" עבודת הקודש אצל הרבי \" ע ' יח :)\nכדאי להדפיסם . בהערה ת \" ח שנתן להו \" ל כו .'\nרמ\nקייץ ][\nממענה בקשר לבחירות ליו \" ר \" ועד כפר חב \" ד \" ( ס ' \" הרב אשכנזי \" ע '\n630 והעתקה :),\n1 ) כו \" כ עניני דפירוד הלבבות ( ואפילו מחלוקת בפועל ) בכחב \" ד\nובעוה \" ר אינם מתמעטים וד \" ל . ושינוי בתפקיד זה – יוסיף בהנ \" ל כהנה\nוכהנה ר \" ל . ההיפך בהחלט מרצון מייסד הכפר כ \" ק מו \" ח אדמו \" ר . .[\n].\nר מא\nתשמ \" ב ][\nמענה לנערה ששאלה ע \" ד מקום לימודי ' בשנה הקרובה – האם יהי '\nבמוסד תורני , או לדחות זאת לשנה הבאה ( מצילום כתי \" ק – ס ' \" מאוצר\nהמלך \" ח \" א ע ' 37 :)\nבכלל – פשוט שצ \" ל לימודי ' במוסד שמלמדים יהדות תומ \" צ וכו '\nובאוירה דיר \" ש וכו ', ואין מקום לומר בכיו \" ב שידחו כ \" ז לשנה הבאה .\nבפרט – תספר כהנ \" ל לרב מורה הוראה ויורה דעת תורה . –\nאזכיר עה \" צ"],[9200210132,"132\nמענות קודש – ה ' תשמ \" ב\nרמב\nתשמ \" ב ][\nמענה להרב גבריאל ציננער שהכניס את שאלת ידידו הרב יצחק אהרן\nגולדברגר – ר \" מ בישיבת פאפא בברוקלין – המתלבט האם להדפיס את\nהחידושי - תורה אשר באמתחתו , בהתאם להמקובל בשם גדולי ישראל\nמהונגריא אשר הדפסת חידושי תורה בחיי המחבר עלול ח \" ו להביא\nלהיפך אריכות ימים ( מצילום כתי \" ק – ס ' \" מאוצר המלך \" ח \" א ע ' 372 .\nקובץ הערות וביאורים אהלי תורה חג השבועות תשס \" ה ( גליון תתקא :))\nישתדל בתור ר \" מ בישיבה בברוקלין ][ שיו \" ל קובצי תורה ויבחון\nהתוצאות בפועל ( 1 )\nכדברַי שכבר נתפרסמו – באריכות קצת :\nבחינת דבר שבספק – התוצאות בפו \" מ , ובנדו \" ד בנוגע לתומ \" צ ויהדות\nבכלל , וחינוך הנוער בפרט – מה ניתוסף בכ \" ז ע \" י אי הדפסת כהנ \" ל\nבעבר ? ( 2 )\nהנ \" ל מענה בקיצור נמרץ , כי אינו נוגע כלל לזמה \" ז , לפענ \" ד ( לאחרי\nהשמדת סלתה ושמנה דמחברי דור שלפנינו הי \" ד והמחנכים שבו ) ( 3 )\nלהעיר ממעשה רב עד \" ז בזמן ראשוני הראשונים ( ברכות כח , רע \" א ) ( 4)\nרמג\nתשמ \" ב ][\nמענה לא ' השלוחים ( מצילום כתי \" ק – ס ' \" מבית המלכות \" ח \" א ע ' 281 :)\nהודעתי וכו \" כ פעמים\n(1 ) שצ \" ל דעת כו \" כ , ולא דעת יחיד ( הגדול ביותר ג \" כ – כי אין דן יחידי\nאלא השם ) שהרי המדובר בנכסי ציבור\n(2 אין לחב \" ד להכנס לשותפות עם מי שיהי ')\n(3 לפלא הכי גדול שאינו יודע מכ \" ז !!)"],[9200210133,"133\nמענות קודש – ה ' תשמ \" ב\nרמד\nתשמ \" ב ][\nמענה לאחת שכתבה שנולדה לאם יהודי ', ואח \" כ עברה שמד ר \" ל , וכעת\nהחליטה לחזור ליהדותה ; וכתבה ששאלה בעצת כו \" כ , ויש אומרים\nשצריכה לעבור גיור , ויש אומרים שאין צריכה ( מצילום כתי \" ק – תשורה\nטלזנר כ \" ט שבט תשנ \" ז :)\nתשאל רב אורטודוקסי ותעשה כהוראותיו .\nוכמובן – ההקדם ישובח .\nכל השמות\nמהיר\nח\nרמ ה\nתשמ \" ב ][\nמענה לר ' שלום דובער לוין שכתב – בקשר לזה שהעבירו את ארונות\nהספרים וכתבי - יד – מחלק הספרי ' שבו שוהה כ \" ק אדמו \" ר שליט \" א\nבשויו \" ט , לקומה העליונה של הספרי ' – וכ \" ק אדמו \" ר שליט \" א הגיב באי\nשביעות רצון :\n\" ראיתי את מענה כ \" ק אדמו \" ר שליט \" א בקשר להספריה , ותקותי חזקה\nשאינו קשור לזה מה שהחלטנו להעביר את כתבי - היד לקומה העליונה ,\nשהי ' בעיקר כדי להקל על העובדים בהו \" ל של כתבים אלו . ושלכן העברנו\nאת הספרים יקרי - הערך מהחדר שינה לחדר האוכל , ושופץ מחדש החדר\nשינה . עוד יש כמה תיקונים הנצרכים בספרי ', שתקותינו שגם זה אינו\nקשור למענה הנ \" ל .\"\nמענה כ \" ק אדמו \" ר שליט \" א ( מצילום כתי \" ק – שיעורי ר ' שלום דובער\nשי ' לוין מספר 488. קובץ \" עבודת הקודש אצל הרבי \" ע ' קל - א :)\nבאם נצרכים בספרי ]'[ [ אינו קשור למענה הנ \" ל ] כמובן\nח"],[9200210134,"134\nמענות קודש – ה ' תשמ \" ב\nרמ ו\nתשמ \" ב ][\nמענה לעסקניות שכונת קראונהייטס בקשר עם בנין המקוה ( ס ' \" מקדש\nמלך \" ח \" א ע ' 55 :)\nבכל ניו יארק וכיו \" ב – בנו ובונים מקוואות ורובן ע \" י נשים עסקניות\nומאספות את הממון הדרוש בפועל ממש בעצמן , ולפלא שלאחרי יותר\nמשנה של עסקנות בזה – אין ידוע להן עד \" ז ואיך שהנ \" ל עושות זה .\nהדרך למצוא מי שהוא שיאסוף בשבילן הכסף לא הצליח עד עתה .\nוראה ליקוט מענות קודש תשמ \" ג מענות יא , מח , נב .][\nרמ ז\nתשמ \" ב ][\nמענה להשליח ר ' יהודה ליב ראסקין שכתב : \" יהודי אחד בעיר אגאדיר\nמטפל הרבה בענין לרשום את כל היהודים לס \" ת , ופתאום נפל לו רעיון\nלרשום את כל הצדיקים שהוא יודע , ושלח לי רשימה של כ - 270 צדיקים ,\nומתחיל באדם הראשון , האבות והשבטים , הנביאים והתנאים , אדמו \" רי\nחב \" ד , צדיקי מרוקו וכו '. ומשלם דולר בעד כל שם . ומבקש ממני\nלהכניסם בהרשימה . אני חשבתי שאולי כדאי , כיון שרושמים גם לעילוי\nנשמת . מכל מקום אינני רוצה לעשות על דעת עצמי , והנני מציע את הענין\nלפני כ \" ק שליט \" א \" ( ס ' אלבום \" אות בספר תורה \" ע ' 140 :)\nוימלא בקשתו .\nרמ ח\nתשמ \" ב ][\nמענה לר ' יהושע יחזקאל סופר בקשר לספר שערך \" תמרורים בפאתי\nמשיח \", ובו דברי רקע אודות מבצע כתיבת ס \" ת לילדי ישראל ( ס ' \" ימי\nתמימים \" ח \" ח ע ' 154 :)\nכפשוט ע \" י וועד וכיוצ \" ב ."],[9200210135,"135\nמענות קודש – ה ' תשמ \" ב\nרמ ט\nתשמ \" ב ][\nמענה לר ' ישראל לייבוב שכתב ע \" ד סכסוך המתנהל בין \" צעירי אגודת\nחב \" ד \" באה \" ק לבין מוסד חב \" די מסויים בארצה \" ב , בנוגע לכספים\nשלטענת צאגו \" ח חייב לו המוסד . בשלב מסויים נתברר שיהי ' צורך לנהל\nדין תורה בנידון בארצה \" ב , ובהמשך לזה כתב שהוא נוטה לוותר על\nהכסף ולחסוך מעצמ ו את המאבק ( ס ' \" צעירי אגודת חב \" ד \" ע ' 148 :)\nשומר אינו יכול לוותר .\nפשוט ומפורסם .\nכשיהיו כאן יכנסו לבי \" ד חב \" ד ויבררו כל הנ \" ל ויבקשו מהם כתב\nויכניסו העתקה לכאן .\nכל החשבונות וכו .'\nרנ\nתשמ \" ב ][\nמענה לא ' הבעלי - בתים המקורבים לחב \" ד ניו דזשערזי על מכתבו בענין\nבעי ' בריאותית במשפחתו ( ס ' \" והאר עינינו בתורתך \" ע ' רעו :)\nכיון שדר . טענדלער שי ' עוסק בכהנ \" ל ( במחקר ) – יבקש הרב הערסאן\nשי ' שיברר דעתו בכ \" ז ואולי יש לו גם עוד הצעות .\nאזכיר עוה \" פ עה \" צ\nר נא\nתשמ \" ב ][\nמענה לר ' שלום דובער לוין שכתב ע \" ד בקשה שנתקבלה מ \" מכון\nירושלים \" לקבל כתבים של הרב יצחק אלחנן מקאוונא . למכתבו צירף\nשני מכתבים של הנ \" ל ושאל האם לשלוח ( קובץ \" עבודת הקודש אצל\nהרבי \" ע ' קטו :)"],[9200210136,"136\nמענות קודש – ה ' תשמ \" ב\nכ \" ק אדמו \" ר שליט \" א ענה לחיוב , וכתב :\nוצ \" ל עוד מכ ' ( אליו .)?\nרנב\n[ תשמ \" ב ( 1 ])\nמענה לר ' שלום דובער לוין שהודיע ע \" ד ביקור מר בנימין ריטשלער –\nמנהל מכון תצלומי כת \" י שבספרי ' הלאומית בירושלים – בספריית כ \" ק\nאדמו \" ר שליט \" א ( קובץ \" עבודת הקודש אצל הרבי \" ע ' קכב :)\nהיש אצלם קטלוג ?\nרנג\n[ תשמ \" ב ( 2 ])\nמענה לר ' שלום דובער לוין ששאל – בהמשך להמענה שקיבל – האם\nלבקש מהנהלת המכון תצלומי כת \" י שבספרי ' הלאומית העתק מהקטלוג\nשל כל תצלומי כתבי - היד שבידם ( קובץ \" עבודת הקודש אצל הרבי \" ע '\nקכב :)\nהכוונה היתה שבאם ישנו קטאלוג רשמי ולא בחשאי לקנותו , אבל לא\nלבקש \" יוצא מן הכלל \" וכו ' לבקש טובה וכו .'\nרנד\nתשמ \" ב ][\nמענה לר ' שלום דובער וואלף שכתב שנתבקש ע \" י אישיות מסויימת\nלכתוב בשמו אשר לדעתו כדאי שיסתכל כ \" ק אדמו \" ר שליט \" א על\nהנעשה באה \" ק , ולא על העולם כולו (\" כפר חב \" ד \" גליון 100 :)\nכ \" ק אדמו \" ר שליט \" א מחק תיבת \" ולא \", וכתב :\nעל הנעשה בישראל ][ וכן על העולם כולו ][ ובפרט שזה בזה תלוי , ומעורב ,\nוערבים זה בזה ."],[9200210137,"137\nמענות קודש – ה ' תשמ \" ב\nרנ ה\nתשמ \" ב ][\nמענה לר ' יצחק ידגר שכתב ע \" ד בוגרת בית הספר חב \" ד בתענך הסובלת\nמכאבים חזקים בבטנה והרופאים נלאו למצוא את מקור הכאבים , והיא\nמיואשת מכך (\" כפר חב \" ד \" גליון 105 :)\nדיוק בכשרות האכילה והשתיה , הפרשת תרומות ומעשרות אזכיר\nעה \" צ .\nרנ ו\nתשמ \" ב ][\nמענה להזמר הת ' אברהם שבתי הכהן פרידמן ( אברהם פריד ) שהכניס\nאת הקלטת השלישית שהפיק (\" כפר חב \" ד \" גליון 615 :)\nבוודאי מתייעץ בכל זה עם מומחים וכיו \" ב .\nרנ ז\nתשמ \" ב ][\nמענה לא ' שכתב ע \" ד בנו שנחשד במעשים לא טובים ועמד למשפט\nתשורה אלטיין ט \" ו סיון תשע \" ח :)(\nיעשו כעצת עורך דין מומחה , הנהגה יומית דבנם שי ' ( עכ \" פ – מכאן\nולהבא ) עפ \" י התוה \" מ , כולל כמובן כשרות האו \" ש , הנחת תפילין\nבדוקות ). אזכיר עה \" צ .(\nאי \" צ כלל לדבר אתי פא \" פ עדכ \" ז .\nרנ ח\nתשמ \" ב ][\nמענה לר ' מיכאל אלוש שכתב ע \" ד רצונו לעקור מקום מגורי משפחתו\nמטולוז צרפת ולעלות לאה \" ק ( 698 Program Torah Living :)"],[9200210138,"138\nמענות קודש – ה ' תשמ \" ב\nבאם פרנסתו עתה בשמירת שויו \" ט וכו ' – קדימה שימשיכו בעירם\nעתה .\nאזכיר עה \" צ .\nרנ ט\nתשמ \" ב ][\nמענה כ \" ק אדמו \" ר שליט \" א ( מהעתקה . המענה מתפרסם בזה לראשונה\nבאדיבות הת ' שלום דובער שי ' הרשקופ וזכות הרבים תלוי ' בו :)\nמצאגו \" ח שעניתי – כנראה מכתבו שמתחשבים בדעתי ודעתי ברורה :\nאין צורך כלל לדבר אתי פא \" פ , כ \" א כל השמות ואזכיר עה \" צ ,\nוהעיקר הנהגה יומית בכל הנ \" ל ע \" פ רצון השם כמבואר בשו \" ע .\nואדרבה הזמן שהיה צ \" ל להנסיעה לדבר אתי – יאמרו תהילים לזכות\nהנ \" ל והממון דהוצאות הנסיעה לזכות הנ \" ל .\nרס\nתשמ \" ב ][\nמענה לא ' התמימים ששאל עצת כ \" ק אדמו \" ר שליט \" א בקשר ללבישת\nעדשות - מגע . וכתב אשר אף שידוע דעת כ \" ק אדמו \" ר שליט \" א נגד לבישת\nעדשות מגע , הנה יש לו בעי ' מיוחדת , והרופא המליץ על עדשות נושמות ,\nשיש להן את שני התכונות , הן של עדשות קשות והן של רכות . ומבקש\nאת ברכתו ועצתו הק ' בזה ( מהעתקה . המענה מתפרסם בזה לראשונה\nבאדיבות הת ' שלום דובער שי ' הרשקופ וזכות הרבים תלוי ' בו :)\nכ \" ק אדמו \" ר שליט \" א סימן קו תחת התיבות \" שידוע דעת כ \" ק נגד\nעדשות מגע \", וכתב :\nאזכיר על הציון\n(2 ) כעצת רופא ידיד"],[9200210139,"139\nמענות קודש – ה ' תשמ \" ב\nר סא\nתשמ \" ב ][\nמענה לא ' התמימים שכתב שקנה עדשות מגע רכות וכבר משתמש בהן\n( מהעתקה . המענה מתפרסם בזה לראשונה באדיבות הת ' שלום דובער\nשי ' הרשקופ וזכות הרבים תלוי ' בו :)\nכעצת רופא ידיד ובדיקת התפילין"],[9200210140,"140\nמענות קודש – ה ' תשמ \" ב\nלזכות\nכ \" ק אדמו \" ר שליט \" א"],[9200220001,"ליקוט\nיום הבהיר י ” ד כסלו\nפראנקפורט , גרמני '\nיום הבהיר י “ א ניסן\nמענות קודש\n• •\n• ה ' תש ” נ תשמ \" ג •"],[9200220002,""],[9200220003,"ב \" ה .\nפתח דבר\nלקראת כ \" ף מנחם - אב , יום ההילולא של הרה \" ג הרה \" ח וכו ' הרב לוי יצחק\nז \" ל , אביו של כ \" ק אדמו \" ר שליט \" א –\nהננו מוציאים לאור בזה ליקוט \" מענות קודש – ה ' ת שמ \" ג \", הכולל את\nמענות קודש כ \" ק אדמו \" ר שליט \" א שכתבם במשך שנת ה ' ת שמ \" ג .\n*\n\" פון איין תורת נשיא דורנו גייט מען צו נאך א תורת נשיא דורנו \" ( שיחת\nש \" פ תזו \" מ תנש \" א – בלתי מוגה ). כמה \" חלקים \" ישנם לתורת נשיא דורנו\nכ \" ק אדמו \" ר שליט \" א .\nבין החלקים השונים בתורת כ \" ק אדמו \" ר שליט \" א , \" חלק \" מיוחד ישנו ,\nוהוא : \" מענות קודש \", הם אלפי המענות אשר כתב כ \" ק אדמו \" ר שליט \" א\nבמענה להשואלים :\nהחל מהשנים הראשונות לנשיאות כ \" ק אדמו \" ר שליט \" א , הנה לצד\nה \" אגרות \" ששלח להפונים אליו , נענו רבים מהמכתבים ע \" י כ \" ק אדמו \" ר\nשליט \" א בכתב יד קדשו על מכתב השואל , כאשר לאחר מכן נמסרים\nהדברים להנמען .\nבעוד ובשנים הראשונות הי ' זה באופן מצומצם ( בעיקר – לאלו הנמצאים\nבסמיכות מקום ), הנה ככל שעברו השנים הלך הדבר והתרחב יותר ויותר , עד\nשהי ' לאופן העיקרי בו עונה כ \" ק אדמו \" ר שליט \" א להכותבים אליו .\nעל אף היותו של \" חלק \" זה בתורת כ \" ק אדמו \" ר שליט \" א – חלק עיקרי ,\nנדמה , כי חלק זה אין מוסבת תשומת הלב אליו ככל הדרוש .\nטעם העיקרי לדבר הוא , ככל הנראה , כיון שמפוזרים מענות הקודש על\nפני כמה וכמה מקומות שונים , ועד עתה לא נמצא להם גואל שילקטם\nלפונדק אחד .\nצורך זה באנו למלאות בליקוטים אלו . קד מו לליקוט שלפנינו \" ליקוט\nמענות קודש – תש ד \" מ \" , \" ליקוט מענות קודש – תשמ \" ה ,\" \" ליקוט מענות\nקודש – תש מ \" ו \",\" ליקוט מענות קודש – תשמ \" ז ,\" \" ליקוט מענות קודש –\nתשמ \" ח \" , \" ליקוט מענות קודש – תשמ \" ט ,\" \" ליקוט מענות קודש – תש \" נ ,\"\n\" ליקוט מענות קודש – ת נש \" א ו \"\", ליקוט מענות קודש – תש נ \" ב ,\""],[9200220004,"4\nמענות קודש – ה ' תשמ \" ג\nובתכניתנו להוציא ליקוטים נוספים מסוג זה , להרוות צמאון אנ \" ש\nוהתמימים .\n*\nתודתנו נתונה לכל אלו שהואילו למסור את מענות הקודש שבידם\nלפרסום בליקוט זה , וזכות הרבים תלוי ' בהם .\nבמיוחד תודתנו נתונה למערכת אפליקציית \" מפתח \" על עזרתם .\nוכאן המקום לבקש בבקשה כפולה ומכופלת מכל מי שיש בידו מענות\nקודש שטרם פורסמו , למוסרם לידי המערכת על מנת לפרסמם בליקוטים\nיבואו , ויהיו בזה ממזכי הרבים .\nכתובת הדוא \" ל של המערכת : likkutkatyak@gmail.com .\n*\nויהי רצון שבמהרה בימינו תחזינה עינינו בהתפשטות מלכות כ \" ק\nאדמו \" ר שליט \" א על כל באי עולם , ו נזכה להתראות עם כ \" ק אדמו \" ר שליט \" א\nתיכף ומיד ממש , מלך ביפיו תחזינה עינינו , והוא יגאלנו תיכף ומיד ממש .\nמערכת \" ליקוט כתבי יד קודש \"\nערב כ \" ף מנ \" א , ה ' תש \" פ\nשבעים שנה לנשיאות כ \" ק אדמו \" ר שליט \" א\nברוקלין , נ . י ."],[9200220005,"5\nמענות קודש – ה ' תשמ \" ג\nצילו מי כתי \" ק\n– פרסום ראשון –\nלקמן מענה יג"],[9200220006,"6\nמענות קודש – ה ' תשמ \" ג\nלקמן מענה קז"],[9200220007,"7\nמענות קודש – ה ' תשמ \" ג\nלקמן מענה קח"],[9200220008,"8\nמענות קודש – ה ' תשמ \" ג\nלקמן מענה קכ"],[9200220009,"9\nמענות קודש – ה ' תשמ \" ג\nמענות קוד ש – ה ' תשמ \" ג\nא\nתשרי ][\nמענה כללי - פרטי דימים אלו [ בין השאר : ( 1 ) להנהלת \" צעירי אגודת\nחב \" ד \" המרכזית על דו \" ח כללי מכינוסם העשרים ושבע שהתקיים ביום\nא ' דחול המועד סוכות ( תדפיס מספר \" ועבדי דוד \" – ס \" ת הכלליים שע \" י\nתו \" ת המרכזית – ע ' 76 ;) ( 2 ) ל \" ועד רבני ליובאוויטש \" על ההודעה ע \" ד\nאסיפה שמתכננים לערוך ( מהעתקה , באדיבות הת ' מנחם מענדל שי '\nשמוקלער :])\nנת ' ות \" ח .\nודבר בעתו –\nבזמן שמחתנו ( לשון רבים ,)\nשהתחלתו ביום שמחתכם אלו השבתות .\nאזכיר עה \" צ .\nב\nתשרי ][\nמענה לר ' ישראל שם - טוב שהכניס תמונות מריקודי \" שמחת בית\nהשואבה \" בשכונת קראונהייטס שאירגן ( קטלוג התמונות של ספריית\nאגו \" ח מספר 3920 :)\nראיתי ת \" ח להחזיר"],[9200220010,"10\nמענות קודש – ה ' תשמ \" ג\nג\nתשרי ][\nמענה לר ' אפרים וואלף על שאלתו בקשר להעסקת נשים בבית הספר\nלדפוס \" יד החמשה \" ( ס ' \" ימי תמימים \" ח \" ח ע ' 166 :)\nכהמענה דכו \" כ פעמים כהוראת הרב מרא דאתרא .\nד\nתשרי ][\nמענה לר ' שלום הלוי דוכמאן חבר הנהלת \" כולל חב \" ד \" שכתב : \" הנני\nרוצה לשאול את דעת כ \" ק אדמו \" ר שליט \" א , בזה שבדעתי לקחת את . .\n( הוא הי ' המנהל של . .) לעבוד עבור הכולל , תפקידו יהי ' . . בכלל הוא\nעושה עלי רושם טוב וכו ' ובעל מרץ , וכנראה מזה שהוא פעל קצת בשטח\nזה לא בא ופן רשמי בימים האלה ונראה שאפשר לסמוך עליו , מובן שזהו\nלנסיון של שלושה חדשים וכו ' ואז נחליט וכו '\" (\" כפר חב \" ד \" גליון\n1678 :)\n[1 על כללות המכתב , כתב :]\nכנראה לא הבין כלל מענתי מאז , ומוכרחני לכתוב בפירוש שלא יהי '\nמקום לטעות – מספר האנשים שמקבלים משכורת בהכולל כאן – הוא\nבהרבה יותר מהדרוש , ובהיפך מהנהגות כל המוסדות ( הראויים לשם\nמוסד ), וכן מספר החדרים בהם פזור הכולל , פשוט\nבאם יהי ' איש מיוחד לכל פרט מהעבודה וחדר מיוחד לכל פרט בפ \" ע ,\nולכאו \" א מהם מזכיר וטלפון – ה \" ז מסודר יותר ויפה יותר וכו .'\nבכ \" ז ה \" ז היפך לגמרי מהנהגת מוסד מסודר כי כל מוסד משתדל\nשכאו \" א מהעובדים בו יהי ' זמנו בהמוסד מנוצל לגמרי .\nבהנוגע לפועל – מכבר הי ' צ \" ל ועכ \" פ יעשה זה עתה – יצמצם כהנ \" ל\nבהכולל , שיהי ' עכ \" פ לא יותר מעשר אחוז יותר ממוכרח – שזה ידרוש\nאָפזאגען ולא ... לשכור חדשים ! וכל הצמצום וההקדם בזה ישובח ,\nויה \" ר שיודיע מהבפו \" מ בקרוב ( 1 )"],[9200220011,"11\nמענות קודש – ה ' תשמ \" ג\n[2 על מה שכתב : \" תפקידו יהי ' כו '\", כתב :]\nבאם כ \" ז לא נעשה ע \" ע מה סו \" ס עושים בפועל לתועלת המוסד – כל\nהאנשים והמזכירים שבכולל ? ( 2 )\n[3 ] על מה שכתב : \" מובן שזהו לנסיון של שלושה חדשים וכו ' ואז נחליט\nוכו \"' – סימן בעיגול תיבת \" נחליט \", וכתב :\nמי הם המחליטים בכל כיו \" ב ? ( 3 )\nה\nתשרי ][\nמענה לשני שלוחים שהכניסו רשימת - דברים שהסכימו עליהם , בהמשך\nלסכסוכים בהם היו מעורבים ( מהעתקת המזכיר . המענה מתפרסם בזה\nלראשונה באדיבות א ' מאנ \" ש שי ' וזכות הרבים תלוי ' בו :)\nשייך להרבנים שי ' ( הועד ?) שעסקו בזה ע \" ע וכהוראתם יעשה\nאזכיר עה \" צ .\nלהחזיר החוזה\nו\nכ \" ד תשרי , אסרו חג הסוכות ][\nמענה להרב דוד ראסקין על דו \" ח שכתב ( בתאריך ד ' תשרי ) בקשר\nלקובצי חידושי תורה היו \" ל בכל רחבי תבל – בהמשך לדברי כ \" ק\nאדמו \" ר שליט \" א בזה לאחרונה ( מהעתקה . המענה מתפרסם בזה\nלראשונה באדיבות מערכת הספר \" ועבדי דוד \" וזכות הרבים תלוי '\nבהם :)\nאסחה \" ס\nהנעשה בכהנ \" ל עתה\n[ בקשר לקובצי חידושי תורה – ראה גם לקמן מענות : ח , י , נד , סב .]"],[9200220012,"12\nמענות קודש – ה ' תשמ \" ג\nז\nתחלת תשמ \" ג ][\nמענה לר ' שלום דובער לוין שכתב – בקשר לס ' אגרות - קודש אדמו \" ר\nמהריי \" ץ כרך א שבעריכתו : \" באגרות תרפ \" ג - ד השמטתי כמה עשרות\nאגרות בקשר לאגודת ישראל , ועוד עשרות קטעי אגרות , ורבים שאלו\nלטעם ההשמטה ( מאגרות שכבר נדפסו במקומות אחרים ), והשבתי\nשהוא מפני כבוד . .\" ( קובץ \" עבודת הקודש אצל הרבי \" ע ' מד :)\nח .\nוטוב עשה , כפשוט .\nח\nד ' מרחשון ][\nמענה להנהלת \" צבאות השם \" ששאלו – בקשר לדברי כ \" ק אדמו \" ר\nשליט \" א לאחרונה ע \" ד הדפסת קובצי חידושי תורה בכל מקום ומקום –\nהאם ילדי \" צבאות השם \" ישתתפו אף הם בכתיבת והדפסת קובצי\nחידושי תורה ( מצילום כתי \" ק – קונטרס ועד הנחות בלה \" ק ש \" פ מטות\nתשע \" ד :)\nלא נכון לקחת מזמן דהנ \" ל למה שאין זה ענינם\nוינצלוהו לתומ \" צ כו .'\nט\nלאחר ש \" פ נח , ו ' מרחשון ][\nמענה ל \" ועד הנחות התמימים \" על שאלתם בהמדובר בהתועדות ש \" פ\nנח :\n\" בהשיחה דפרש \" י ( נח ז , יב ) הקשה , דממ \" ש \" ויהי הגשם גו ' ארבעים\nיום \" מוכח דכוונת רש \" י \" הורידן ברחמים שאם יחזרו יהיו גשמי ברכה \"\nהיא שכל הארבעים יום ( לא רק בתחלתן ) הורידן באופן כזה ( שבאם\nיחזרו יהיו גשמי ברכה ). וא \" מ : א ) היאך שייך קס \" ד \" אם יחזרו \" במשך"],[9200220013,"13\nמענות קודש – ה ' תשמ \" ג\nארבעים יום והרי כבר בודאי מתו בתחילת המבול ( כשהי ' ריבוי מים ),\nוהיאך שייך ש \" יחזרו \"? ב ) מהו הפירוש בזה שכל הארבעים יום ( גם בסוף\nהמ ' יום ) הוריד המים באופן כזה – והרי בפועל הי ' מבול ? ויתירה מזו :\nאיך זה מתאים עם מ \" ש להלן ( בפסוק יז ) \" ויהי המבול ארבעים יום ,\"\nשבמשך כל המ ' יום ( גם בתחלתן ) הי ' מבול ?\nונתבאר התירוץ על קושיא הראשונה , דרש \" י פירש כבר לפנ \" ז פסוק ד )'(\n\" ארבעים יום – כנגד יצירת הולד שקלקלו להטריח ליוצרם כו '\". והיינו ,\nדארבעים ימי המבול הוא ענין אחד ( ובלשון הרגצובי : נקודה אחת .)\nומכיון שמצד הקס \" ד \" אם יחזרו \", ירידתן בתחלת המ ' יום הי ' לא באופן\nד \" מבול \" – הרי במילא נתבטל כבר ה \" נקודה \" דארבעים יום מבול , לכן\nבהימים שלפנ \" ז הורידן באופן שיוכלו להיות גשמי ברכה .\nאם נרשם נכון . ומהו התירוץ על קושיא השני ': היאך שייך שכל המ ' יום\n( גם ביום המ ') הי ' אפשר עדיין ( גם למטה , \" על הארץ \") שיהיו גשמי\nברכה ? וגם : איך זה מתאים עם \" ויהי המבול ארבעים יום \", שבכל המ '\nיום ( גם בתחלתן ) הי ' מבול .\"?\nמענה כ \" ק אדמו \" ר שליט \" א ( מצילום כתי \" ק – יחי המלך \" גליון תצ :)\"\n[1 ] על מה שכתבו : \" ומכיון שמצד הקס \" ד \" אם יחזרו \", ירידתן בתחלת\nהמ ' יום הי ' לא באופן ד \" מבול \" – הרי במילא נתבטל כבר ה \" נקודה \"\nדארבעים יום מבול , לכן בהימים שלפנ \" ז הורידן באופן שיוכלו להיות\nגשמי ברכה \", כתב :\nשמצד הקס \" ד \" אם יחזרו \", ירידתן ][ הייתה בבת אחת א פעקל ( של מ '\nיום ) – אחד בדוגמת יצירת ולד אחד\n[2 על מה שכתבו : \" איך זה מתאים עם \" ויהי המבול ארבעים יום ,\"]\nשבכל המ ' יום ( גם בתחלתן ) הי ' מבול כתב :?\",\nבנקודה אין שייך תחלתן ][ ואמצע – וסוף\nהמענה נכלל בלקו \" ש חכ \" ה ע '[ 24 ואילך .]"],[9200220014,"14\nמענות קודש – ה ' תשמ \" ג\nי\nז ' מרחשון ][\nמענה להרב דוד ראסקין על מכתבו – בהמשך להמענה שקיבל ( לעיל\nמענה ו ) – בו כתב ע \" ד ההתקדמות בהוצאת הקובצים דחידושי תורה\nבכל רחבי תבל ( מהעתקה . המענה מתפרסם בזה לראשונה באדיבות\nמערכת הספר \" ועבדי דוד \" וזכות הרבים תלוי ' בהם :)\nנת ' ות \" ח\nלהחזיר המצו \" ב\nיא\nועש \" ק לך , י \" ב מרחשון ][\nמענה לר ' שניאור זלמן גורארי ' על מכתבו בקשר לתכנית הרחבת 770\n(\" בית משיח \" גליון 270 תשורה הולצמן ט ' תמוז תשע \" ד . והעתקה :).\nתפסת מרובה וכו ' ויסתפקו לע \" ע ( בצידי דרום וצפון ) מבלי הריסת\nמשרדים או שינוי בהם .\nובפרט ( בנוגע להבטחות שלהם – במוכח ) המאורע המבהיל , ומבהיל עוד\nיותר – שאין אף אחד שם לב לזה כלל !!\nסתרו ( בממון צבור ובזריזות ) המקוה היחידה לנשים שהייתה בכל\nהשכונה דליובאוויטש ושמבקרים בה נשי חב \" ד מכמה מדינות – לפני\nכשנתיים !?\nוכיון שכנראה לא \" נודע \" להם עד \" ז – הריני להודיע : 1 ) אין מקוה\nבמקומה ע \" ע , כאן , 2 ) ע \" פ שו \" ע בנוגע לביהכנ \" ס אפילו , ואפילו כשיש\nעוד ביהכנ \" ס – צע \" ג איך סתרו מלכתחלה 3 ) במצב שמותר לסתור\nשלא הי '( כלל בנדו \" ז ) – צ \" ל \" לבנות במהרה ביום ובלילה \" ( ל ' השו \" ע\n.)\nובעיני ראיתי שמלבד ימים ספורים אין בונים כלל לא בלילה ולא ביום .\nוה ' ירחם על כולנו בתוכ \" י . ומסיימים בטוב .\n[ וראה לקמן מענות מח , נב .]"],[9200220015,"15\nמענות קודש – ה ' תשמ \" ג\nיב\nמרחשון ][\n\" צעטל \" בכתי \" ק שכתב כ \" ק אדמו \" ר שליט \" א להנהלת תו \" ת המרכזית\nבקשר לסגירת הישיבה - גדולה בסיאטל וואשינגטאן ( מצילום כתי \" ק –\nתשורה טלזנר כ \" ט שבט תשנ \" ז . \" בית משיח \" גליון 1123 :)\nהנהלת מרכז תו \" ת שי :'\nאף שאין דרכי כלל להתערב בעניניהם , כמפורסם\nלהיות הנ \" ל יוצא מן הכלל לגמרי\nיצאתי מן הכלל הנל ושואל בשאלותי הנ \" ל :\nהגעתני ז \" ע ידיעה שיסגר לשנ \" ה הבע \" ל סניף תו \" ת אשר ב .[ ].\nוהשאלות : א ) הידוע לכם עד \" ז . 2 ) אחריות הסניפים היא על המרכז ( כן\nהוא ע \" פ שו \" ע ) הידוע לכם עד \" ז ?\nכוונתי כפשוט לא לשקוט כי רק לבירור : .[ ].\nמהיר\nח\nיג\nכ \" ב מרחשון ][\nמענה לר ' מיכאל אהרן זליגסון שכתב : \" היות שיצא לאור סה \" מ תרמ \" ג -\nתרמ \" ד חשבתי לערוך מפתח ענינים להנ \" ל ( כמו מכבר – לשנות עטר \" ת -\nפר \" ת ) ורציתי לשאול הוראת כ \" ק אד \" ש בזה \" ( מצילום כתי \" ק – נדפס\nלעיל , מתפרסם בזה לראשונה באדיבות הנמען שי ' וזכות הרבים תלוי '\nבו . מבוא ל \" ס ' המפתחות לשיחות קודש :)\"\nיברר במזכ '\nבאם לא קדמו אחר – נכון כפשוט ( ובזריזות – כפשוט .)\nמהיר\nח"],[9200220016,"16\nמענות קודש – ה ' תשמ \" ג\nיד\nשלהי מרחשון ][\nמענה כללי - פרטי דימים אלו [ בין השאר – לר ' ישראל לייבוב מנהל\nצעירי אגודת חב \" ד \" באה \" ק על דו \" ח ( ס ' \" צעירי אגודת חב \" ד \" ע '\" 257 .\nוראה לקמן מענה טו :])\nנתקבל ותשואות חן ודבר בעתו טוב בסמיכות לשבת מברכים כסלו\nחודש הגאולה , אזכיר על הציון .\nטו\nשלהי מרחשון ][\nמענה לר ' ישראל לייבוב מנהל \" צעירי אגודת חב \" ד \" באה \" ק על דו \" ח ( ס '\nצעירי אגודת חב \" ד \" ע '\" 257 :)\nבטח מבצע חנוכה מיט א שטורם , והלכה כבית הלל דמוסיף והולך ,\nובפרט כשגם כן לכתחילה צריך להיות א ריבער .\nוצירף את המענה כללי - פרטי דימים אלו ( לעיל מענה יד .)\nטז\nלאחר ש \" פ חיי שרה , כ \" ז מרחשון ][\nמענה למערכת הערות התמימים ואנ \" ש מאריסטאון על מכתבם –\nבהמשך להגהת כ \" ק אדמו \" ר שליט \" א על הערה בהקובץ ( גליון רצג ,)\nבקשר להמבואר בהתועדות ש \" פ חיי שרה בההבדל בין עונש סדום\nועמורה לעונש שאר הערים , שה \" גפרית ואש \" היו על סדום ועמורה\nדוקא , משא \" כ שאר הערים בהפיכה – דהוא כי סדום ועמורה היו גם\nרעים לבריות , משא \" כ שאר הערים . וציינו בהערה הנ \" ל למש \" כ\nהרגצ ' ובי , דטעם הדבר הוא מפני שסדום ועמורה נענשו מדין עיר הנדחת ,\nומכיון שאין עושין ג ' עיירות עיר הנדחת , לכן שאר הערים נהפכו ולא\nנשרפו . וציינו שם , אשר אי \" צ לפרש כן בפשש \" מ , דאין צריכים לומר\nשהעונש דגפרית ואש הוא בגדר שריפת עיר הנדחת . ועל זה כתב כ \" ק\nאדמו \" ר שליט \" א : \"[ דבפשש \" מ ] עיר הנדחת הוא רק בע \" ז ועוד ועיקר"],[9200220017,"17\nמענות קודש – ה ' תשמ \" ג\nבפועל הי ' דד ' ערים – וטעם שלילת [ שאין עושים ג ' עיירות ] ה \" ז גם\nבהפיכה ובפרט לפני מ \" ת דנתחדש שצ \" ל דוקא שריפה \". ובהמשך לזה\nכתבו המערכת :\nמצו \" ב קטע מהגליון דשבוע זה ( פ ' ויצא )\" – מה שכתב כ \" ק אדמו \" ר\nשליט \" א על הגליון הקודם ( דפ ' תולדות ) – כפי שהוכן להו \" ל . .\nבנוגע למ \" ש כ \" ק אדמו \" ר שליט \" א שעיר הנדחת הוא רק בע \" ז ( ובסדום\nועמורה לא מצינו חטא דע \" ז ) – אולי יש להעיר מפרש \" י ( וירא יט , כד :)\n\" המטיר על סדום – בעלות השחר , כמש \" נ וכמו השחר עלה , בשעה\nשהלבנה עומדת ברקיע עם החמה , לפי שהיו מהם עובדין לחמה ומהם\nללבנה כו '\". וכן בפרש \" י ( לך יג , יג ): \" ואנשי סדום רעים וחטאים לה ' מאד\n– יודעים רבונם ומתכוונים למרוד בו .\"\nגם : לכאורה אפשר לתרץ בפשטות – שהבן חמש למקרא לא למד עדיין\nאודות הגדר דעיר הנדחת , ופשיטא שלא למד מ \" ש בסנהדרין שאין עושין\nג ' עיירות עיר הנדחת .\"\nמענה כ \" ק אדמו \" ר שליט \" א ( מצילום כתי \" ק – ס ' \" והאר עינינו בתורתך \"\nע ' קפא :)\n[1 ] על מה שכתבו : \" מצו \" ב קטע מהגליון . . מה שכתב כ \" ק אדמו \" ר\nשליט \" א . . כפי שהוכן להו \" ל \", כתב :\nבמה שנתייחדו סדום וכו ' הוא כמפורש צעקת ריבה ואם לא גו '\n[2 ] סימן בעיגול מה שכתבו ( מפרש \" י וירא ): \" לפי שהיו מהם עובדין\nלחמה ומהם ללבנה כו '\", וכתב :\nזה הי ' כל העולם אז ( פרש \" י כד , ז . ולפני זה ס \" פ נח\nוהאריך הרמבן ( לד , יג ) ומה יבקש בהן הרב כו '\nוהוא פשט במצב אז\n[3 סימן בעיגול מה שכתבו ( מפרש \" י לך ) \" יודעים רבונם \", וכתב :]\nראי ' לסתור\n[4 סימן בעיגול מה שכתבו ( מפרש \" י לך ) \" למרוד בו \", וכתב :]\nה \" ז כל דור ההוא הפלגה ונמרוד בראשם ( כפרש \" י )"],[9200220018,"18\nמענות קודש – ה ' תשמ \" ג\n[5 ] על מה שכתבו : \" גם : לכאורה אפשר לתרץ בפשטות – שהבן חמש\nלמקרא לא למד עדיין אודות הגדר דעיר הנדחת , ופשיטא שלא למד מ \" ש\nבסנהדרין שאין עושין ג ' עיירות עיר הנדחת \", כתב :\nהרי להרגצובי עסקינן\nולא לפרש \" י\nהמענה נכלל בלקו \" ש חל \" ה ע '[ 70 ואילך .]\nיז\nכ \" ח מרחשון ][\nמענה לאחת מנשות אנ \" ש על שאלותי ' בהמדובר בהתועדות ש \" פ חיי\nשרה ( מצילום כתי \" ק – יחי המלך \" גליונות תצב , תרמח :)\"\nא . במכתבה כתבה :\n\" ב \" ה איך האב א גוטן פלאץ בא די פארבריינגען לעבן רבצ ' ן מענדליק\nשתחי ' און איך קען ב \" ה הערן די שיחות קודש פון רבי ' ן שליט \" א און\nס ' גיט מיר א חיות פאר די גאנצע וואך .\nאיך האב געוואלט פרעגן דעם רבי ' ן שליט \" א א זאך וואס ס ' איז מיר נישט\nקלאר פון דעם שבת מברכים חודש כסלו פ ' חיי שרה .\nאין דעם הסבר אויף דעם רש \" י פון פ ' וירא בנוגע צו סדום האט דער רבי\nשליט \" א דערמאנט אז אברהם אבינו איז געווען בן ע ' שנה בשעת ברית\nבין הבתרים , און לויט דער דעה אז ברית בין הבתרים איז געווען נאך\nמלחמת סדום , וואס דערפאר האט ה ' געזאגט צו א \" א שכרך הרבה וכו ,'\nאיז אד ורך אזא משך זמן פון מלחמת סדום , וואס ווי קען מען זאגן אז\nההרה נסו און געבליבן דארטן אזוי לאנג , בשעת זייער לאנד איז געווען\nאזוי גוט כגן ה ' וכו .'\nאיז מיר נישט ברור א דיוק אין די חשבון פון די יאהר און דער סדר\nהענינים . איך האב נאך געקוקט אין חומש שמות פ ' בא וואו דער פ ' זאגט ,\nויהי מקץ שלשים שנה וארבע מאות שנה וכו ', און רש \" י איז מסביר אז\nמלידת יצחק איז געווען ת ' שנה און ברית בין הבתרים איז געווען 30\nיאה ר פריער , און שפתי חכמים זאגט אז א \" א איז געווען בן ע ' שנה בשעת\nברית בין הבתרים וכך איתא בסדר עולם . לויט דעם איז פארשטאנדיק ,\nאז אזוי ווי ס ' שטייט אין לך לך פרק י \" ב פס ' ד אז א \" א איז געווען בן 75\nשנה בצאתו מחרן , אז דער ברית בין הבתרים וואס א \" א איז דעמולט"],[9200220019,"19\nמענות קודש – ה ' תשמ \" ג\nגעווען בן ע ' איז געווען פאר דעם נסיון פון לך לך . ואין מוקדם ומאוחר\nבתורה .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\n[1 ] סימן קו תחת התיבות : ( א ) \" און לויט דער דעה אז ברית בין הבתרים\nאיז געווען נאך מלחמת סדום , וואס דערפאר האט ה ' געזאגט צו א \" א\nשכרך הרבה וכו '\"; ( ב ) \" און רש \" י איז מסביר אז מלידת יצחק איז געווען\nת ' שנה און ברית בין הבתרים איז געווען 30 יאהר פריער \"; וכתב :\nכך מפורש ברש \" י טו , א\n[2 ] על מה שכתבה : \" לויט דעם איז פארשטאנדיק , אז אזוי ווי ס ' שטייט\nאין לך לך פרק י \" ב פס ' ד אז א \" א איז געווען בן 75 שנה בצאתו מחרן , אז\nדער ברית בין הבתרים וואס א \" א איז דעמולט געווען בן ע ' איז געווען\nפאר דעם נסיון פון לך לך . ואין מוקדם ומאוחר בתורה \" – סימן קו תחת\nהתיבות \" ברית בין הבתרים \", וכתב :\nמפורש בכתוב שהי ' בארץ הזאת – בארץ ישראל [ כי לדעה זו יצא ב '\nפעמים מחרן ] כי בפעם הא ' שיצא מחרן הלך אתו לוט וכו ' ונשבה כו '\nואח \" כ ברית ביה \" ב ( בעלי התוס ' ר \" פ לך )\nב . במכתבה כתבה :\nאויך די לעצטע שאלה פון רבי ' ן שליט \" א אין פ ' וירא וועגן סדום ,\"\nפארוואס אין פסוק שטייט וה ' המטיר . . . אש וגפרית , און רש \" י איז\nמפרש מתחלה מטר ונעשה גפרית ואש , און איז גארנישט מסביר אזוי ווי\nאין נח בא דעם מבול וואו רש \" י האט מסביר געווען ויהי הגשם –\nשהורידן ברחמים אם יחזרו יהיו גשמי ברכה , און דא איז רש \" י גארנישט\nמסביר . אויב איך האב גוט פארשטאנען די שאלה , האב איך געטראכט\nאפשר איז דער ענטפער איז זייער פשוט . אזוי ווי דער בן חמש למקרא\nהאט שוין געלערנט אין פ ' נח וועגן די דרכי ה ' אז ער ווארט ביז די לעצטע\nמ ינוט צו געבן א Chance די רשעים צו טאהן תשובה , איז אפשר דער\nזעלבער ענין געווען דא , אז דער מטר האט געקענט זיין ברכה אויב זיי\nוואלטן געטאהן תשובה , ובפנימיות איז עס גוט .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\n[3 על התיבות : \" איז אפשר דער זעלבער ענין געווען דא \", כתב :]\nא \" כ הי ' צ \" ל הפיכת המים מברכה להיפך הברכה ( מים הזדונים ) ולא .\n. לגפרית ואש היפך דמים ,( ולא היפך דברכה )"],[9200220020,"20\nמענות קודש – ה ' תשמ \" ג\nיח\nער \" ח כסלו ][\nממענה לר ' אליעזר צבי זאב צירקינד על מכתבו בקשר להמדובר\nבהתועדויות ש \" פ וירא וש \" פ חיי שרה בענין משיחת מלך ( מצילום כתי \" ק\n– ס ' \" נלכה באורחותיו \" ע ' 225 :)\n[1 ] במכתבו כתב : \" כדאי להזכיר שגם אצל שמוא ' הנביא נמצא דעות\nשהיה מלך ואעפ \" כ לא מצינו שנמשח .\"\nכ \" ק אדמו \" ר שליט \" א סימן בעיגול קטע זה וסימן חץ וכתב :\nאליבי ' דהרמב \" ם עסקינן ומלשונו ברור ששמואל לא הי ' מלך ( 4 )\n[2 ] במכתבו כתב : \" וגם יש להעיר שאני לשפל ידיעתי לא מצאתי ענין\nמשיחה אצל משה רבינו , ולכ \" ע מלך הי .\"'\nכ \" ק אדמו \" ר שליט \" א סימן בעיגול קטע זה , וכתב :\nכמדומה הזכרתיו בההתועדות – בכל אופן יש להסביר בקל – לפי\nהשיטה שהי ' מלך – נעשה מלך קודם הציווי דשמן המשחה ודיני מלך\nשבתוש \" ב בכלל ( 5 )\nהמענה נכלל בלקו \" ש חכ \" ג ע '[ 190 .]\nיט\nועש \" ק תולדות , ג ' כסלו ][\nמענה לה \" ועד להפצת שיחות \" שכתבו : \" מצו \" ב ספר ליקוטי שיחות חלק\nיט . הוצאות הספר נתן ידידינו מר זאב הלוי הורביץ מפאלו בראזיל , ונתן\nאת זה לזכות כ \" ק אדמו \" ר שליט \" א והרבנית שתליט \" א \" ( מצילום\nכתי \" ק – \" בית משיח \" גליון 270 :)\nנת ' ות \" ח ת \" ח וכו '\nמוכרח שהחלק דבראשית שלאח \" ז יו \" ל בפועל בשבועות שלו תשמ \" ג .\nוההקדם בזה גופא ישובח\nובטח יבש \" ט .\n[ וראה לקמן מענות כג , כד .]"],[9200220021,"21\nמענות קודש – ה ' תשמ \" ג\nכ\nתחלת כסלו ][\nמענה כללי - פרטי דימים אלו [ בין השאר : ( 1 ) לר ' מאיר יהודה ישראל\nהארליג על דו \" ח מהתועדויות יום הבהיר ר \" ח כסלו ברחבי תבל (\" כפר\nחב \" ד \" גליון 76 ;) ( 2 ) לר ' שמואל הורביץ שהכניס את חוברת הלכות\nחנוכה באידיש שהו \" ל ( ס ' \" שבח המועדים :])\"\nנתקבל ות \" ח .\nודבר בעתו –\nבסמיכות ליוד כסלו יום הגאולה .\nאזכיר על הציון .\nכא\nתחלת כסלו ][\nמענה להנהלת \" צבאות השם \" ששאלו האם לקנות תנור גדול במיוחד\nלאפיית מצות , בכדי שיוכלו להדגים לילדים המבקרים את תהליך האפי '\nהתקשרות \" גליון לח , והעתקה :)(\"\nהרי לזה צ \" ל מומחים בכיו \" ב , תנור ובנין מתאים , משגיח וכו ' וכו ' ,\nואפילו לעשות חמץ ' דיגע מצות ג \" כ טרחא רבה ופזור הנפש וכו ', ומה\nמכריחם לכל זה ?\nלכל היותר – יכולים להתדבר עם מאפי ' הקיימת בלאה \" כ שישכירו\nפארדינגען זיי ) ימים אחדים וכו '(\nאזכיר עה \" צ\nכב\nז ' כסלו ][\nמענה להשליח הרב יוסף העכט שכתב ע \" ד פרופסור מסויים שטען\nשהתורה אינה סותרת את המדע בנוגע לגיל העולם , ובתוך דבריו ציטט\nאת כ \" ק אדמו \" ר שליט \" א שבספר \" אמונה ומדע \" כותב , לדבריו , שגם\nלפי התורה יתכן שהעולם קיים מיליוני שנים . כאשר התקשר אל"],[9200220022,"22\nמענות קודש – ה ' תשמ \" ג\nהפרופסור ונזף בו על שהוא מסלף בזדון את דברי כ \" ק אדמו \" ר שליט \" א ,\nהגיב הלה שכך הוא מבין את דברי כ \" ק אדמו \" ר שליט \" א , וכי כל אחד\nרשאי לפרש את דברי כ \" ק אדמו \" ר שליט \" א כרצונו ( לקו \" ש ח \" ל ע ' 267 .\nתשורה העכט ט \" ז כסלו תשס \" א :)\nעל מה שכתב שהפרופסור לא הטריח עצמו לקרוא עד הסוף , ובמילא\nסילף את דברי כ \" ק אדמו \" ר שליט \" א – כתב :\n1 ) גודל העגמ \" נ וכו ' הוא לא כ \" כ מזה שהנ \" ל עושה כך , אלא מזה\nשאנ \" ש שי ' נוהגים ככה ועוד יותר .\n2 ) כתבתי בפי ' ( ובטח הועתק בס ' אמונה ומדע ) שהמקבל השיטה\nשהבריאה בפועל היתה בהתפתחות דעתי שמבטל יסוד מצות שבת\nהכתוב בתורה ( נוסף על שזהו היפך מסורת ישראל שכותבים בשטרות\nגטין \" לבר \" ע )\" – ( מובן שידוע מש \" כ בתפא \" י על המשניות במאמרו\nהידוע ואכ \" מ ) ואיך אפ \" ל ספק בדעתי !?\nכג\nכסלו ][\nמענה לה \" ועד להפצת שיחות \" על מכתבם – בהמשך להמענה שקיבלו\n( לעיל מענה יט ) להו \" ל לקוטי שיחות כרך כ עד לש \" פ ויחי ( מצילום\nכתי \" ק – \" בית משיח \" גליון 270 :)\n[1 במכתבם כתבו ע \" ד הנושאים בהם יעסקו ה \" הוספות \" להספר .]\nמענה כ \" ק אדמו \" ר שליט \" א :\nיכולים לעשות כהנ \" ל ( וכן – השיחות לחו \" כ וברי מצוה ומכ ' לחנוכה )\nבאם יהי ' הס ' מכורך עכ \" פ לעש \" ק ויחי – עכ \" פ – מאה טופסים\n[2 ] במכתבם כתבו : \" באם מכניסים הליקוטים של ש . ז . בהספר נוכל\nלמסור הספר לדפוס אי \" ה תיכף לאחרי שיודפס הליקוט לפ ' ויחי . ע \" פ\nכל הנ \" ל – אולי כדאי לעשות כן .\"?\nכ \" ק אדמו \" ר שליט \" א סימן בעיגול את התיבות \" הליקוט לפ ' ויחי ,\"\nוכתב :\nיכניסוהו אלי לא יאוחר מעש \" ק ויגש או עוד מוקדם באם מוכרח לקיום\n(1) (2 )"],[9200220023,"23\nמענות קודש – ה ' תשמ \" ג\nכד\nכסלו ][\nמענה לה \" ועד להפצת שיחות \" על מכתבם – בהמשך להמענות שקיבלו\n( לעיל מענות יט , כג ) בקשר להו \" ל לקוטי שיחות כרך כ עד לש \" פ ויחי –\nבו כתבו :\n\" ואולי , היות וה \" קונטרסים \" שיצאו לאור בתחלת שנת תשל \" ח ( מצו \" ב\nטופסים ) הם התועדויות שלמות מתקופה אחת )( – אולי כדאי להדפיסם\nבמדור בפ \" ע [ ע \" ד השיחות – התועדויות – דשנת תשכ \" ה שנדפסו\nבהוספות ללקו \" ש כרך ה ' במדור בפ \" ע .]\nבאם זה נכון – אולי כדאי להדפיס ( בתור יוצא מן הכלל ) גם המאמרים\nשבקונטרסים אלו , ובפרט שכמה ענינים שבהשיחות באים בהמשך\nלהמאמר [ וכמו השיחות הנ \" ל משנת תשכ \" ה , שגם המאמרים שנאמרו\nאז נדפסו בלקו \" ש שם .\"]\nמענה כ \" ק אדמו \" ר שליט \" א ( מצילום כתי \" ק – \" בית משיח \" גליון 270 :)\nמחק תיבת \" אולי \" וסימן בחץ ובעיגול מה שכתבו \" כדאי להדפיסם\nבמדור בפ \" ע [ ע \" ד כו '\"; מחק תיבת \" אולי \" וסימן בחץ ובעיגול מה\nשכתבו \" כדאי להדפיס ( בתור יוצא מן הכלל ) גם המאמרים כו '\"; וכתב :\nויכניסו הר \" ד לחו \" כ וליג \" ש שנה ומכ ' דחנוכה כיון שמוגהים –\nבשינוי מהמדובר לפני זה – לא לחכות ללקו \" ש דויחי שנה זו ( ואולי גם\nלא ללקו \" ש דויגש ) ובמילא יוכלו להו \" ל באופן שילמדו בו עוד בזמן דס '\nבראשית\nלהחזיר כל המצו \" ב )(\n[ כאשר חברי ה \" ועד \" מיהרו בעבודה והכניסו את ה \" ליקוט \" דש \" פ ויגש\nלהגהה מוקדם , כתב על עלי - ההגהה : באם ימהרו וגם בדויחי – יוכל הכל\nלהכנס בהכרך .]"],[9200220024,"24\nמענות קודש – ה ' תשמ \" ג\nכה\nכסלו ][\nממענה לקבוצת אברכים בקשר להו \" ל חוברות בנושא זהותו של מלך\nהמשיח ( מצילום כתי \" ק – \" כפר חב \" ד \" גליונות 775 , 1050 :)\nזה מכו \" כ חדשים שמרעישים ויותר מכאן ע \" ד ההכרח דאחדות ישראל\n( ובהקדמת אהבת ישראל ) ושלילת מחלוקת וכו ', ושזהו ביטול סיבת\nהגלות , ובמילא נוגע ישירות – להשים קץ לגלות ולהביא את הגאולה ,\nוכל השתדלות האפשרית בזה מקדימה קץ הגלות , ובכ \" ז חובת כאו \" א\nהרוצה ומצפה לגאולה להשתדל ( ולהזהר – מהפכו .) .[ ].\nפרסום החוברת הב ' ואפילו דחוברת הא ' – ה \" ה במצב ההווה – פעולה\nהכי חזקה להגדיל מחלוקת , פירוד הלבבות וכו ' ר \" ל ., ( ונס גדול הוא\nשע \" ע לא בא לזה – למרות הרעש שמקימים שפיץ חב \" ד בזה \" בסוד .)\"\nזה שכוונתם היא כו ' – אין נפק \" מ , כי נוגע התוצאות בפו \" מ שהן כנ \" ל .,\nלסיכום – פעולתם הנ \" ל ותוצאותי ' מי דיות מחלוקת , פירוד הלבבות ,:\nהיפך מהפצת אהבת ישראל , פא ררייסען זיך עם רבבות מישראל , וכו ' ,\nוכתוצאה מכ \" ז – פא רשלעפען קץ הגלות , ר \" ל וכו .'.\nואין להאריך בדבר המבהיל . ומבהיל ג \" כ שאין שמים לב כלל לכ \" ז .\n[ והמציאו תרופה – שידפיסו שזהו \" לאנ \" ש פנימי \"! לא יאומן כי יסופר\nשאיש מבוגר יענה כהנ \" ל .]!\nכו\nכסלו ][\nממענה כ \" ק אדמו \" ר שליט \" א ( לקו \" ש חכ \" א ע ' 381 :)\n.[ ]. צדקה לפני הדלקת הנרות , והעיקר לנצל זה להדגיש שאסור\nלהמדליקה לטלטל הּפושקע לאחר ההדלקה , ולכן צ \" ל לכתחילה\nבמקום שתשאר שם עד לאחרי הבדלה ( שכמה אינן יודעות עד \" ז ) .[ ]."],[9200220025,"25\nמענות קודש – ה ' תשמ \" ג\nכז\nכסלו ][\nמענה להנהלת בית הספר \" בית רבקה \" בכפר חב \" ד ב ' ששאלו – לאור\nסיום הרישום לספר התורה הכללי השני של בית הספר ע \" י התלמידות –\nהאם עליהן להתמסר עתה לרישום ילדים לספר תורה של ילדי ישראל\nס ' אלבום \" אות בספר תורה \" ע '( 139 :)\nבכל כיו \" ב שייך לועד הרבנים דס \" ת באה \" ק . אזכיר עה \" צ .\nכח\nכסלו ][\nמענה לר ' שלום דובער לוין שכתב – בקשר להערת כ \" ק אדמו \" ר שליט \" א\nעל עלי - ההגהה דמבוא לאגרות - קודש אדמו \" ר מהריי \" ץ כרך ב , שבו בין\nהשאר תיאר את ביקורו בעיר לודמיר , וכתב עלי ' שהיא במחוז וואלין :\n\" לברר השנים בדיוק דאטוואצק . לברר המתאים השם ואלין להמחוז\nאודותו מדובר :\"\n\" מ \" ש ש \" לודמיר \" היא ב \" ואלין \" הוא ע \" פ הפניה שבראש האגרת\nהמצו \" ב . ומתאים להאמור באנצ ' העברית , שמצו \" ב צילומו .\nכיון שההעתקה מווארשא לאטוואצק היתה בקיץ תרצ \" ה , לכן לא\nהזכרתי עד \" ז בכרך זה , ובפרטיות עד \" ז במבוא לכרך השלישי .\"\nמענה כ \" ק אדמו \" ר שליט \" א ( קובץ \" עבודת הקודש אצל הרבי \" ע ' מה :)\nנת ' ות \" ח .\nלהחזיר ."],[9200220026,"26\nמענות קודש – ה ' תשמ \" ג\nכט\nכסלו ][\nמענה לא ' מעסקני חב \" ד באה \" ק על מכתבו עם טענות על עסקן אחר\nהתקשרות \" גליון פב , והעתקה :)(\"\nכנראה שאינו יודע – אבל לפלא שאינו משער – שכעין טענות הנ \" ל יש\nמכל הצדדים ועל כל הצדדים – ורק בי \" ד רבני אנ \" ש שי ' שבאה \" ק –\nביכולתו ומתפקידיו העיקריים לעשות בזה לתקן וכו .'\nל\nכסלו ][\nמענה לר ' אליעזר צבי זאב צירקינד שכתב ע \" ד ייסוד \" אגודת כותבי\nסת \" ם אנ \" ש דקראונהייטס \", וכתב : \" אנו פונים לכ \" ק אדמו \" ר שליט \" א\nליתן הסכמתו וברכתו ועוד וכו '\" ( קובץ זכרון הרב אליעזר צבי זאב\nצירקינד ע \" ה ע ' 7 :)\nכ \" ק אדמו \" ר שליט \" א מחק תיבת \" ליתן \" וסימן בחץ את התיבות\nהסכמתו וברכתו \", וכתב :\"\nויהי רצון שיקויים בזה החלצו מאתכם גו ' וכל משנ \" ת בקונטרס הנ \" ל\nאזכיר עה \" צ .\nלא\nכסלו ][\nמענה להשליח הרב יוסף העכט שכתב ע \" ד התפתחות הענינים בנוגע\nלקבלת האישורים לתכנית הדפסת ס ' התניא במצרים , וכתב שאין לו כל\nהערכה היכן המצב באמת עומד , ומבקש ברכה ( תשורה העכט כ \" ט אדר\nתשס \" ב :)\nבסגנון המתאים יסבירו להקונסול ( זה שיכול לדבר איתו יותר בגילוי\nלב ) מצרים מעונינת שה \" עולם \" ( ארצה \" ב ) – יוכל לומר שמצרים אינה\nמנגדת ליהודים כלל .[ ]. והדפסת ספר כהנ \" ל בלה \" ק וכו ' – ה \" ז הוכחה\nבולטת לזה וי \" ל שיגדל חן הקונסול במצרים ע \" י שהמציא זה לידם וכו .'\n[ וראה לקמן מענות קל א , קל ג ליקוט מענות קודש תשד \" מ מענה רז .]."],[9200220027,"27\nמענות קודש – ה ' תשמ \" ג\nלב\nכסלו ][\nמענה כללי - פרטי דימים אלו [ בין השאר – להרב דוד ראסקין על דו \" ח\nמאסיפת הנהלת ישיבת תו \" ת המרכזית בקשר לסיום ספר תורה הכללי\nהרביעי שלהם ( תדפיס מספר \" ועבדי דוד \" – ס \" ת הכלליים שע \" י תו \" ת\nהמרכזית – ע ' 77 . וראה לקמן מענה לו :])\nנת ' ות \" ח ,\nודבר בעתו –\nבין גאולה דיו \" ד כסלו\nוגאולה די \" ט כסלו\nאזכיר עה \" צ\nלג\nט \" ז כסלו ][\nמענה לר ' אפרים וואלף ( מצילום כתי \" ק – ס ' \" ימי תמימים \" ח \" ח ע '\n199 :)\n[1 ] במכתבו כתב : \" רצו \" ב מכתבים ע \" ד הכולל בנחלת הר חב \" ד ומקווים\nשבעזה \" י הענין יסודר .\"\nכ \" ק אדמו \" ר שליט \" א סימן בעיגול את התיבות \" רצו \" ב מכתבים ,\"\nוכתב :\nלהחזיר\n[2 ] במכתבו כתב : \" פנו אלינו מטעם עלית הנוער שנקבל בביסל \" מ ילדים\nפלשיים . אנו העברנו השאלה לבי \" ד רבני אנ \" ש ורצו \" ב תשובתם . אני\nחושש שמטעם עלית הנוער לא יחסכו מאמץ להשיג תעודה – כנדרש\nמטעם רבני אנ \" ש – והננו שואלים האם באמת לקבל ילדים פלשיים או\nלנסות להתנער מזה .\"\nכ \" ק אדמו \" ר שליט \" א מחק את התיבות \" או לנסות \" וסימן בחץ ובעיגול\nאת התיבות \" להתנער מזה \", וכתב :\nלהתנער מזה ][ בהחלט"],[9200220028,"28\nמענות קודש – ה ' תשמ \" ג\n[3 ] במכתבו כתב : \" היות ומטעם האוצר חולקו הרבה כספים ( הנקראים\nיחודיים ) ע \" י חברי הכנסת של אגו \" י למוסדות שלהם . פנינו ישירות לשר\nהאוצר ( בתור נסיון מקודם ) מטעם ביסל \" מ וגם מטעם הישיבה בטענת\nהפליה לרעה , ובקשה לקבל ג \" כ הקצבות דומות .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\nהיות ומטעם האוצר ] [ ומטעם ][ משרד הדתות חולקו ][ זה מכו \" כ שנים\nהרבה כספים ( הנקראים יחודיים ) ע \" י חברי הכנסת של ][ מפד \" ל ו [ אגו \" י\nלמוסדות שלהם ]\n[4 ] במכתבו כתב : \" בע \" פ דברו עם הפקידים שאנו מוכנים אפילו ללכת\nלבג \" צ בענין זה . הננו שואלים דעת כ \" ק אדמו \" ר שליט \" א האם ללחוץ עד\nכדי הגשת בג \" צ נגד משרד ושר האוצר , בענין הנ \" ל .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\nשייך להחלטת אנ \" ש שי ' שבאה \" ק\nלד\nי \" ט כסלו ][\nמענה לר ' הלל דוד קרינסקי שכתב : \" מכינים כל הענינים לשידור\nההתועדות די \" ט כסלו חי ע \" י סאטעלייט לכל ארצה \" ב קאנאדא וכו '. בין\nהשיחות ק ' נזכיר גם ע \" ד מבצע חנוכה \" ( מצילום כתי \" ק – תשורה\nקרינסקי כ \" ח סיון תשע \" ג :)\nהרה \" ד שי ' קרינסקי\nהבפומ ?\nלה\nי \" ט כסלו ][\nמענה לא ' מאנ \" ש שכתב : \" אבקש ברכה שאמלא רצון כ \" ק אדמו \" ר\nשליט \" א והוראותיו ובשמחה תמידית . מה תפקידי הפרטי בעולם \"?\nלקו \" ש חל \" ט ע '( 325 ס ' \" היכל מנחם \" ח \" ב ע ' צג :)."],[9200220029,"29\nמענות קודש – ה ' תשמ \" ג\nימלא רצון כ \" ק אדמו \" ר שליט \" א והוראותיו ][ ע \" י שיהי ' [ בשמחה\nתמידית ]\nוכשיפתהו היצה \" ר להתבונן במצב רוחו ובפרטיות יענהו שהוא תמים\nולא חקרן ובכלל אין לו פנאי לזה כי תפקידו לעשות רצון קונו ע \" י תומ \" צ\nולא ע \" י חקירות ופלפולים .\nלו\nכ \" ף כסלו ][\nמענה להרב דוד ראסקין על דו \" ח מאסיפת הנהלת ישיבת תו \" ת\nהמרכזית בקשר לסיום ספר תורה הכללי הרביעי שלהם , בו עלו שתי\nאפשרויות : ( 1) לעשות את הסיום בביהמ \" ד ב - 770 ביום כ \" ח טבת ; ( 2 )\nלעשות את הסיום בניו דזשערזי ביום ב ' שבט ( תדפיס מספר \" ועבדי דוד \"\n– ס \" ת הכלליים שע \" י תו \" ת המרכזית – ע ' 77 :)\nכפי שיתדברו ביניהם\nוצירף את המענה כללי - פרטי דימים אלו ( לעיל מענה לב .)\nלז\nועש \" ק וישב , כ \" ד כסלו , ערב חנוכה ][\nמענה לר ' הלל דוד קרינסקי שכתב :\nהשידור החי של ההתועדות די \" ט כסלו ע \" י סאטעלייט מחוף לחוף הי '\"\nבהצלחה . השתדלנו להוסיף מספר המקומות והעיירות שמקבלים\nהשידור ונתוסף עי \" ז מספר הרואים .\nבמשך ההתועדות טלפנו ( למספר מיוחד שסדרנו , והראנו זה על\nהטעלעווישאן סקרין ) בערך מאה וחמשים אנשים ונשים , מעירות שונים ,\nבעיקר יהודים אבל גם נכרים . מהם שביקשו ידיעות שונות , מהם\nשביקשו טראנסקריפטס מדברי כ \" ק אדמו \" ר שליט \" א , מהם ע \" ד חנוכה ,\nפגישה וכדומה . לערך מאה מה ם מסרו שמותיהם וכתובותיהם לקבל\nחומר . ."],[9200220030,"30\nמענות קודש – ה ' תשמ \" ג\nמכינים כעת החומר לשלוח להמבקשים . בדעתנו לשלוח ביאגרפיא קצרה\nמכ \" ק אדמו \" ר שליט \" א , חומר ע \" ד חנוכה , ע \" ד הפגישה , ס \" ת הכלליים ,\nצבאות ה ', קטלוג של המל \" ח , ושיחות באנגלית .\nהיות שכו \" כ מבקשים חומר ע \" ד השבע מצוות דבני נח , הנני שואל אם\nנכון לסדר חוברת עד \" ז , וכן אם לסדר חוברת קצרה ע \" ד ליובאוויטש\nלמילוי בקשות כנ \" ל .\"\nמענה כ \" ק אדמו \" ר שליט \" א ( מצילום כתי \" ק – תשורה קרינסקי ו ' תמוז\nתשס \" ט :)\nבאם ימצא מומחה בזה ( נוסף על הצד ההלכתי – בסגנון שלא ירגיז את\nהנכרים וגם יתאים להאמת – שלכן בספק – לא להו \" ל )\nוצירף את המענה כללי - פרטי דימים אלו ( לקמן מענה מא .)\nלח\nועש \" ק וישב , כ \" ד כסלו , ערב חנוכה ][\nמענה לר ' מנחם מאיר הכהן בלוי שהכניס את נוסח המצבה של אמו ע \" ה\nלאישור כ \" ק אדמו \" ר שליט \" א ( קובץ \" זכרון מנחם מאיר \" ח \" א ע ' 16 :)\nכפשוט כרצון אביו שליט \" א\n[ וראה לקמן מענה מ .]\nלט\nלאחר ש \" פ וישב , כ \" ה כסלו , א ' דחנוכה ][\nמענה ל \" ועד הנחות בלה \" ק \" על שאלתם בהמדובר בהתועדות ש \" פ וישב :\n\" בהשיחה דשבת העברה נתבאר שמהג ' ענינים שנתנו במיוחד לנשי\nישראל , נש \" ק ויו \" ט , כשרות האכו \" ש ( חלה ) וטהרת המשפחה ( נדה ,)\nמתחילים מנש \" ק , שהרי כן הי ' בסדר זמנים – שאצל חוה הי ' בתחלה נר\nשבת ואח \" כ טהרת המשפחה ( נדה ), כי דם טמא ( הקשור עם \" דמו של\nעולם \") בא דוקא אחרי החטא ( כי לפני החטא הי ' דמה טהור ), ואילו נר\nשבת ( הקשור עם \" נרו של עולם \") הי ' כבר קודם החטא . ונתבאר הטעם\nלזה בפשטות הענינים , כי בכדי ללמוד הלכות נדה וכן בכדי שיהי ' בדיקה"],[9200220031,"31\nמענות קודש – ה ' תשמ \" ג\nבפועל כו ', שזה דוקא בלילה ( מפני צניעות ) – צריכים לאור הנר ( בכדי\nלראות .)\nלא תפסנו :\nהענין דדמו של עולם ונרו של עולם שכנגדם באו איסור נדה ונר שבת –\nהובא בירושלמי שבת פ \" ג ה \" ו , וז \" ל : \" אדה \" ר דמו של עולם . . וגרמה לו\nחוה מיתה לפיכך מסרו מצות נדה לאשה . . אדה \" ר חלה טהורה לעולם\n. . וגרמו לו חוה מיתה , לפיכך מסרו מצות חלה לאשה . . אדה \" ר נרו של\nעולם . . וגרמו לו חוה מיתה , לפיכך מסרו מצות הנר לאשה \". וכ \" ה בכ \" מ\n– בשינויים ( תנחומ ' ר \" פ נח . פ ' מצורע . ב \" ר פי \" ז , ח . יל \" ש בראשי ' רמז\nלב .)\nומזה מובן שכל הג ' ענינים דנדה חלה ונר שבת ( ולהעיר שהסדר הוא נדה\nחלה ונר שבת – כבמשנה שבת שם ) באו אחרי ומפני ) החטא .\"(\nמענה כ \" ק אדמו \" ר שליט \" א ( מצילום כתי \" ק – יחי המלך \" גליון תעג :)\"\n[1 ] על מה שכתבו : \" שאצל חוה הי ' בתחלה נר שבת ואח \" כ טהרת\nהמשפחה ( נדה ), כי דם טמא ( הקשור עם \" דמו של עולם \") בא דוקא אחרי\nהחטא ( כי לפני החטא הי ' דמה טהור ), ואילו נר שבת ( הקשור עם \" נרו\nשל עולם \") הי ' כבר קודם החטא \", כתב :\nגם הציווי על נדה הי ' לפני החטא ( שבאם יהי ' כו ' – כפי ' הרמב \" ם .[ ].\n[2 ] על מה שכתבו : \" הענין דדמו של עולם ונרו של עולם שכנגדם באו\nאיסור נדה ונר שבת \" – סימן בעיגול תיבת \" באו \", וכתב :\n?\n[3 ] על מה שכתבו : \" ומזה מובן שכל הג ' ענינים דנדה חלה ונר שבת . .\nבאו אחרי ומפני ) החטא \"( – סימן שני קווים תחת תיבת \" באו \", וכתב :\n!?\n[4 סימן בעיגול את מה שכתבו ( מהירושלמי ) \" מסרו מצות נדה לאשה ,\"]\nמסרו מצות חלה לאשה \", \" מסרו מצות הנר לאשה \", וסימן בצדם :\" )*( ;\nוכתב :\nמודגש וג \" פ )*( – והוא מש נה ובלבד להקשות !"],[9200220032,"32\nמענות קודש – ה ' תשמ \" ג\nמ\nכ \" ו כסלו , ב ' דחנוכה ][\nמענה לר ' מנחם מאיר הכהן בלוי שכתב :\n\" אבקש סליחת כ \" ק אדמו \" ר על שהנני מבלה את זמנו הק ' עוה \" פ בקשר\nלנוסח המצבה של אמי מורתי ע \" ה – אבל מה אעשה שהבא לקמן נוגע לי\nבמאד , לכן הנני מעיז לשאול עוה \" פ להוראה ברורה בזה :\nכ \" ק אדמו \" ר שליט \" א ענה לי בעש \" ק : \" כפשוט כרצון אביו שליט \" א \"\nלעיל מענה לח ][ . והנה אבי שליט \" א [ הרב משה יהודה הכהן בלוי ] אישר\nאת כל הנוסח חוץ מהתיבות \" ת הי ' ש נת ג ילוי מ שיח \" שאינו שבע רצון\nמתיבות אלו על מציבה , חוץ מאם כ \" ק אדמו \" ר שליט \" א יאשר תיבות\nאלו , אז יסכים לזה בשמחה ובטוב לבב .\nוהנה כנ \" ל איז קוועטשט שטארק ( ע \" ד מאחז \" ל הואיל ונפיק מפומא דרב\nכהנא וכו ' וכו ') אז עס זאל יע שטיין די ווערטער , וגם הרב דווארקין אישר\nזה . וגם מר . גרינבוים ( שאינו חבדניק ) אישר את זה .\nוהנני שואל דעת כ \" ק אדמו \" ר שליט \" א בזה .\"?\nמענה כ \" ק אדמו \" ר שליט \" א ( קובץ \" זכרון מנחם מאיר \" ח \" א ע ' 17 :)\n[1 ] סימן שני קווים תחת מה שכתב ( העתקת המענה שקיבל ): \" כפשוט\nכרצון אביו שליט \" א \", וכתב :\nויתירה מזה פשוטה !?\n[2 על מה שכתב : \" והנני שואל דעת כ \" ק אדמו \" ר שליט \" א בזה ?\", וכתב :]\nבדיוק כמענתי הנ \" ל ( לא לכתוב הנ \" ל )\nמא\nשלהי כסלו ][\nמענה כללי - פרטי דימים אלו [ בין השאר – לר ' הלל דוד קרינסקי על דו \" ח\nמשידור התועדות י \" ט כסלו ( תשורה קרינסקי ו ' תמוז תשס \" ט . וראה\nלעיל מענה לז :])\nנת ' ות \" ח .\nודבר בעתו –"],[9200220033,"33\nמענות קודש – ה ' תשמ \" ג\nבין י \" ט כסלו , יום הגאולה והפצת המעינות חוצה ,\nוחנוכה דענינה מוסיף והולך ואור ולהמשיך זה בכל ימות השנה .\nאזכיר עה \" צ .\nמב\nלאחר ש \" פ מקץ , ב ' טבת , זאת חנוכה ][\nממענה ל \" ועד הנחות התמימים \" על שאלתם במאמר ד \" ה ברוך שעשה\nנסים דש \" פ מקץ ( ריש סה \" מ תשמ \" ג ( הוצאת ברוקלין , תשס \" ב :))\n[1 בקשר להצעת הבנה מסויימת בהמאמר שאודותיו שאלו : \" אם נכון \"?]\n– מחק תיבת \" אם \" וסימן - השאלה , וסימן בחץ ובעיגול תיבת \" נכון .\"\n[2 ] במכתבם כתבו : \" גם בקטע השני גופא ( בענין ג ' הדרגות מים יין\nושמן ), לא תפסנו במה שנתבאר מעלת השמן על היין שהיין הוא משקה\nחשוב משא \" כ השמן ( כשהוא בפ \" ע ) אינו ראוי לשתי ', והיינו דמה שאינו\nראוי לשתי ' מורה על העילוי שלו ( שהוא למעלה מבחי ' גילוי ממש ) –\nדלכאורה , לפי ביאור זה נמצא שגם המים הם למעלה מיין , מכיון שאין\nבהם טעם .\"?\nמענה כ \" ק אדמו \" ר שליט \" א :\n?! המים תמיד ראוים לשתי '\nאלא שזקוק להם רק אדם החסר צמא )(\n( להעיר שגם אינם מזון ( כמבואר בדא \" ח שזהו היפך מעלה ) – אבל לא\nהוזכר זה בנדו \" ד במאמרים שראיתי ) ( 3)\nהמענה נכלל בסה \" מ מלוקט ח \" ב ע ' רטז .]["],[9200220034,"34\nמענות קודש – ה ' תשמ \" ג\nמג\nלאחר ש \" פ מקץ , ב ' טבת , זאת חנוכה ][\nמענה ל \" ועד הנחות התמימים \" על שאלותיהם בהמדובר בהתועדות ש \" פ\nמקץ ( מצילום כתי \" ק – יחי המלך \" גליון תצז :)\"\n[1 ] במכתבם כתבו : \" אודות המדובר בהתוועדות בענין חמשה חומשי\nתורה וחמשה ספרי תהלים , הקשורים עם אות ה \" א שבציורה מרומזים\nג ' הקוין דמחדו \" מ , \" בפיך ובלבבך לעשותו \", שבהתחלת התניא – אולי\nיש מקום להוסיף שגם ספר התניא מחולק לחמשה חלקים לקו \" א ,:\nשעהיוה \" א , אגה \" ת , אגה \" ק , וקו \" א .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\nצע \" ג הלקרות ל קו \" א ][ חלק !\nוכמו קו \" א בשו \" ע , להש \" ך דמודגש שאינו חלק\n[ על גליון קובץ הערות וביאורים אהלי תורה ( גליון קסג ) שבו נדפסה הערה\nבקשר לחלק זה דהמענה , כתב כ \" ק אדמו \" ר שליט \" א :\nבכמה קובצים שקו \" ט ושפאלטען א האר – בטעות מוזר במה שרשמתי בהשם\nקו \" א .\nרשמתי ראי ' מן : קו \" א בשו \" ע , \" להש \" ך \" וכפשוטו קו \" א בשו \" ע \"\" – אין כל\nקס \" ד לקרותו חלק ( בפ \" ע .)\nוכן – קו \" א להש \" ך .\"\"\n\" כמובן \" הסיחו דעת מקו \" א לשו \" ע אדה \" ז , ומקו \" א להש \" ך , ומתפלפלים ע \" ד\nדף האחרון להט \" ז !\nאח \" כ הגי ' כ \" ק אדמו \" ר שליט \" א את הדברים להדפיסם בהקובץ ( גליון קסד ,)\nכדלהלן :\nאיש לא הקשה למה לא הבאתי ראי ' מקו \" א דאדה \" ז עצמו בשו \" ע שלו !? –\nוכהנ \" ל \" מתורץ \" בפשטות –\nרשמתי – הראי :)'( קו \" א בשו \" ע , להש \" ך ( בפסיק קודם לתיבת \" להש \" ך )\"\nוכפשוטו קו \" א בשו \" ע \" ( דאדה \" ז )\" – אין כל קס \" ד לקרותו חלק ( בפ \" ע ), וכן\nקו \" א להש \" ך .\"\"\nתוכן הדברים נכלל גם בסה \" ש תנש \" א ח \" ב ע ' 765 הערה 130 .]"],[9200220035,"35\nמענות קודש – ה ' תשמ \" ג\n[2 ] במכתבם כתבו : \" אודות המבואר שמיד לאחרי סיום התניא בענין\nדשבת מתחילים \" לקוטי אמרים \" ענין של בירורים הקשור עם עובדין\nדחול – להורות שצריכים להמשיך קדושת השבת גם בעובדין דחול , וכן\nלאחרי סיום החומש בענין \" האותות והמופתים גו '\" מתחילים \" בראשית\nברא אלקים את השמים ואת הארץ \" – להורות על המשכת אלקות\nבבריאת שו \" א , עדיין צריך ביאור מדוע הענין ד \" מתכיפין התחלה\nלהשלמה \" ( בפועל ) הוא רק בחומש ( שבאותו יום – שמח \" ת – קורין \" לכל\nהאותות והמופתים גו '\", ו \" בראשית ברא גו '\"), משא \" כ בלימוד התניא –\nלומדים בי \" ח כסלו אודות ענין השבת , ורק למחרתו מתחילים מ \" ספר\nלקוטי אמרים .\"\"\nמענה כ \" ק אדמו \" ר שליט \" א :\nבתושבע \" פ שמיוסד ההדרן משמע שאין מתחילין כו .' ומעשה רב שאין\nמתחילין\nמד\nלאחר ש \" פ מקץ , ב ' טבת , זאת חנוכה ][\nמענה לר ' שלום דובער לוין שכתב : \" מה שנתבאר בש \" ק בענין קריאת שם\nהנכד כשם זקנו החי ; האם יש לקשר לזה את קריאת שמו של זקנו של\nכ \" ק אדמו \" ר שליט \" א – מוהר \" ר ברוך שניאור , שנולד בחיי אבי אביו\nמוהר \" ר ברוך שלום ; או אפשר נוסף לו השם ברוך מחמת חולי – לאחר\nהסתלקות אבי אביו ?\" ( מצילום כתי \" ק – ס ' \" תולדות חב \" ד ברוסיא\nהצארית \" ע ' קסט :)\n[1 סימן בעיגול את התיבות \" זקנו החי \", וכתב :]\nמלתי ' דתמי ' ביותר בחוג זה והי ' מעורר שקו \" ט וכו '\n[2 על כללות המכתב , כתב :]\nלא שמעתי בזה"],[9200220036,"36\nמענות קודש – ה ' תשמ \" ג\nמה\nד ' טבת ][\nמענה לאחת השלוחות ששאלה כיצד יסביר הבן לאביו שלא כדאי\nשישרפו את גופתו לאחר פטירתו ( קונטרס ועד הנחות בלה \" ק ש \" פ נשא\nתשע \" א :)\nלהרוצה , ר \" ל , שישרפו גופו לאחרי המיתה – יש לומר ברור ובפשטות\nשלהגוף יש לו קיום \" ומעין חיים \" גם לאחר סילוק הנשמה , וכל זמן\nשלא נרקב הגוף לגמרי , חלק מהנשמה קשור בו .\nוכל המצוה או מסכים לשריפת גופו – ה \" ז הסכמה לשרוף חלק\nמהנשמה – מעין שריפת אדם חי ( אלא שלא כולו אלא חלקו ( אכזריות\nמאין כמוה )), ואפילו בשורף נשמת עצמו ר \" ל , ומצדיק עצמו שלא ידע\nמה עושה .\nלהטענה שעוד כמה אנשים עשו כן – הרי אלפי נאצים שרפו אנשים\nחיים ממש – וביניהם מדענים רופאים , סוחרים , בעלי משפחה וכו .'\nמו\nתחלת טבת ][\nמענה כללי - פרטי דימים אלו [ בין השאר : ( 1 ) להנהלת \" צעירי אגודת\nחב \" ד \" המרכזית על דו \" ח מפעולות ה \" טנקיסטים \" ועש \" ק פ ' וישב\nמהעתקה , באדיבות מערכת הספר \" ועבדי דוד ;)\"( ( 2 ) להנהלת \" צעירי\nאגודת חב \" ד \" המרכזית שהכניסו את ההזמנה למלוה - מלכה השנתית\nשתתקיים במוצש \" ק שמות ( מה עתקה , באדיבות מערכת הספר \" ועבדי\nדוד :])\"\nנת ' ות \" ח .\nודבר בעתו –\nבסמיכות לימי חנוכה דענינה מוסיף והולך ואור ולהמשיך זה בכל ימות\nהשנה .\nאזכיר עה \" צ ."],[9200220037,"37\nמענות קודש – ה ' תשמ \" ג\nמז\nי \" ב טבת ][\nמענה להרב משה שרמן והרב יוסף וולף שכתבו :\n\" אחדשה \" ט , השנה תימלאנה להדרת גאונו , מורנו ורבנו מרן רבי יוסף\nדוב הלוי סולובייצ ' יק שליט \" א ארבעים שנה בהן מרביץ תרה בישיבתנו ,\nישיבת רבינו יצחק אלחנן וזכה בעהי \" ת להעמיד תלמידים הרבה .\nלכבוד מאורע גדול זה , החליטה הסתדרות תלמידי ישיבתנו הקדושה\nלהעלות על מכבש הדפוס הוצאה מיוחדת של חיבורנו התורני \" בית\nיצחק \", שכבר נודע בעולם הישיבות כמלא וגדוש חדו \" ת ובירורי הלכה .\nכרך מיוחד זה כמאז ומתמיד יהיה כולו קדוש לדברי תורה .\nלכן פונים אנו לכ \" ק אדמו \" ר שליט \" א שיואיל נא בטובו לתרום מאמר\nבחדו \" ת לכבוד מורנו הגדול שליט \" א .\nיודעים אנו כמה הדוקים הם קשרי הידידות , ההוקרה וההערצה\nההדדית בין כ \" ק שליט \" א לבין מורנו ורבנו שליט \" א ובטוחים אנו שכבוד\nגדול יהיה למו \" ר שליט \" א אם יענה כ \" ק שליט \" א לבקשתנו .\nואנו תפילה שנזכה בקרוב לקבל תשובתו הרמה .\"\nמענה כ \" ק אדמו \" ר שליט \" א ( מצילום כתי \" ק – תשורה קרינסקי ט \" ו\nאלול תש \" ע :)\n[1 ] סימן בעיגול את מה שכתבו : \" לכבוד מאורע גדול זה , החליטה\nהסתדרות תלמידי ישיבתנו הקדושה להעלות על מכבש הדפוס הוצאה\nמיוחדת של חיבורנו התורני \", וכתב :\nונכון במאד מאד ( 1 )\n[2 ] סימן בעיגול את מה שכתבו : \" יודעים אנו כמה הדוקים הם קשרי\nהידידות , ההוקרה וההערצה ההדדית בין כ \" ק שליט \" א לבין מורנו ורבנו\nשליט \" א \", וכתב :\nהרבה יותר מאשר יודעים ( 2 )\n[3 על מה שכתבו : \" ואנו תפילה שנזכה בקרוב לקבל תשובתו הרמה ,\"]\nכתב :\nכוונתם רצוי ' וכו ' , אבל אין הנ \" ל נהוג בבית הרב כלל ומכמה דורות –\nואתם הסליחה ( 3)"]]});
